export interface RGB {
  r: number;
  g: number;
  b: number;
}

export interface Segment {
  id: number;
  path: string;
  targetRGB: RGB;
  currentRGB: RGB;
  isCorrect: boolean;
  labelPosition: { x: number; y: number };
}

export type Difficulty = 'easy' | 'medium' | 'hard';
export type Screen = 'splash' | 'menu' | 'drawing' | 'quiz' | 'mixing-menu' | 'mixing-rgb' | 'mixing-cmyk';

import React, { useState } from 'react';
import SplashScreen from './components/SplashScreen';
import Menu from './components/Menu';
import RGBDrawing from './components/RGBDrawing';
import Quiz from './components/Quiz';
import MixingMenu from './components/MixingMenu';
import ColorMixer from './components/ColorMixer';
import { Screen, Difficulty, Segment } from './types';
import { ROCKET_DATA, CAT_DATA, COMPUTER_DATA } from './constants';

const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<Screen>('splash');
  const [selectedData, setSelectedData] = useState<Segment[]>([]);
  const [levelName, setLevelName] = useState<string>('');

  const handleStartLevel = (difficulty: Difficulty) => {
    switch (difficulty) {
      case 'easy':
        setSelectedData(ROCKET_DATA);
        setLevelName('Raketa');
        break;
      case 'medium':
        setSelectedData(CAT_DATA);
        setLevelName('Kočka');
        break;
      case 'hard':
        setSelectedData(COMPUTER_DATA);
        setLevelName('Počítač');
        break;
    }
    setCurrentScreen('drawing');
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case 'splash':
        return (
          <SplashScreen 
            onEnter={() => setCurrentScreen('menu')} 
            onQuiz={() => setCurrentScreen('quiz')}
            onMixing={() => setCurrentScreen('mixing-menu')}
          />
        );
      case 'menu':
        return <Menu onStart={handleStartLevel} onBack={() => setCurrentScreen('splash')} />;
      case 'drawing':
        return (
          <RGBDrawing 
            onBack={() => setCurrentScreen('menu')} 
            initialSegments={selectedData}
            title={levelName}
          />
        );
      case 'quiz':
        return <Quiz onBack={() => setCurrentScreen('splash')} />;
      case 'mixing-menu':
        return (
          <MixingMenu 
            onSelectRGB={() => setCurrentScreen('mixing-rgb')}
            onSelectCMYK={() => setCurrentScreen('mixing-cmyk')}
            onBack={() => setCurrentScreen('splash')}
          />
        );
      case 'mixing-rgb':
        return <ColorMixer mode="RGB" onBack={() => setCurrentScreen('mixing-menu')} />;
      case 'mixing-cmyk':
        return <ColorMixer mode="CMYK" onBack={() => setCurrentScreen('mixing-menu')} />;
      default:
        return <SplashScreen onEnter={() => setCurrentScreen('menu')} onQuiz={() => setCurrentScreen('quiz')} onMixing={() => setCurrentScreen('mixing-menu')} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-[#f8fafc]">
      {renderScreen()}
    </div>
  );
};

export default App;

