export interface RGB {
  r: number;
  g: number;
  b: number;
}

export interface Segment {
  id: number;
  path: string;
  targetRGB: RGB;
  currentRGB: RGB;
  isCorrect: boolean;
  labelPosition: { x: number; y: number };
}

export interface Line {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
}

export type Difficulty = 'easy' | 'medium' | 'hard';
export type Screen = 'landing' | 'splash' | 'menu' | 'drawing' | 'quiz' | 'lines-menu' | 'vector-drawing';

import React, { useState } from 'react';
import LandingPage from './components/LandingPage';
import SplashScreen from './components/SplashScreen';
import Menu from './components/Menu';
import RGBDrawing from './components/RGBDrawing';
import Quiz from './components/Quiz';
import LinesMenu from './components/LinesMenu';
import VectorDrawing from './components/VectorDrawing';
import { Screen, Difficulty, Segment } from './types';
import { ROCKET_DATA, CAT_DATA, COMPUTER_DATA } from './constants';

const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<Screen>('landing');
  const [selectedData, setSelectedData] = useState<Segment[]>([]);
  const [levelName, setLevelName] = useState<string>('');

  const handleStartLevel = (difficulty: Difficulty) => {
    switch (difficulty) {
      case 'easy':
        setSelectedData(ROCKET_DATA);
        setLevelName('Raketa');
        break;
      case 'medium':
        setSelectedData(CAT_DATA);
        setLevelName('Kočka');
        break;
      case 'hard':
        setSelectedData(COMPUTER_DATA);
        setLevelName('Počítač');
        break;
    }
    setCurrentScreen('drawing');
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case 'landing':
        return (
          <LandingPage 
            onStartColors={() => setCurrentScreen('splash')} 
            onStartLines={() => setCurrentScreen('lines-menu')} 
          />
        );
      case 'lines-menu':
        return (
          <LinesMenu 
            onVectorDrawing={() => setCurrentScreen('vector-drawing')}
            onBack={() => setCurrentScreen('landing')}
          />
        );
      case 'vector-drawing':
        return (
          <VectorDrawing 
            onBack={() => setCurrentScreen('lines-menu')}
          />
        );
      case 'splash':
        return (
          <SplashScreen 
            onEnter={() => setCurrentScreen('menu')} 
            onQuiz={() => setCurrentScreen('quiz')}
            onBack={() => setCurrentScreen('landing')}
          />
        );
      case 'menu':
        return <Menu onStart={handleStartLevel} onBack={() => setCurrentScreen('splash')} />;
      case 'drawing':
        return (
          <RGBDrawing 
            onBack={() => setCurrentScreen('menu')} 
            initialSegments={selectedData}
            title={levelName}
          />
        );
      case 'quiz':
        return <Quiz onBack={() => setCurrentScreen('splash')} />;
      default:
        return <LandingPage onStartColors={() => setCurrentScreen('splash')} onStartLines={() => setCurrentScreen('lines-menu')} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-[#f8fafc]">
      {renderScreen()}
    </div>
  );
};

export default App;

