import React, { useState, useEffect } from 'react';
import { ArrowLeft, Plus, Trash2, HelpCircle, Check, Info } from 'lucide-react';
import { Line } from '../types';

interface VectorDrawingProps {
  onBack: () => void;
}

const VectorDrawing: React.FC<VectorDrawingProps> = ({ onBack }) => {
  const [lines, setLines] = useState<Line[]>([]);
  const [isChained, setIsChained] = useState(false);
  const [p1, setP1] = useState({ x: 0, y: 0 });
  const [p2, setP2] = useState({ x: 0, y: 0 });
  const [lastPoint, setLastPoint] = useState<{ x: number; y: number } | null>(null);

  const gridSize = 400;
  const step = 20;

  const handleAddLine = () => {
    if (isChained) {
      if (lastPoint) {
        const newLine: Line = {
          x1: lastPoint.x,
          y1: lastPoint.y,
          x2: p1.x,
          y2: p1.y
        };
        setLines([...lines, newLine]);
      }
      setLastPoint({ x: p1.x, y: p1.y });
    } else {
      const newLine: Line = {
        x1: p1.x,
        y1: p1.y,
        x2: p2.x,
        y2: p2.y
      };
      setLines([...lines, newLine]);
    }
  };

  const clearLines = () => {
    if (confirm('Opravdu chcete smazat celý obrázek?')) {
      setLines([]);
      setLastPoint(null);
    }
  };

  const handleInputChange = (point: 'p1' | 'p2', axis: 'x' | 'y', value: string) => {
    const num = Math.min(gridSize, Math.max(0, parseInt(value) || 0));
    if (point === 'p1') {
      setP1(prev => ({ ...prev, [axis]: num }));
    } else {
      setP2(prev => ({ ...prev, [axis]: num }));
    }
  };

  // Synchronize chained mode
  useEffect(() => {
    if (!isChained) {
      setLastPoint(null);
    }
  }, [isChained]);

  return (
    <div className="w-full max-w-6xl flex flex-col lg:flex-row gap-8 items-start animate-in fade-in duration-500">
      {/* Grid Area */}
      <div className="flex-1 bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 w-full overflow-hidden">
        <div className="flex items-center justify-between mb-6">
          <button 
            onClick={onBack}
            className="flex items-center text-gray-400 hover:text-indigo-600 transition-colors font-bold"
          >
            <ArrowLeft className="w-5 h-5 mr-2" />
            Zpět
          </button>
          <h2 className="text-xl font-black text-gray-800 uppercase tracking-tighter">Vektorové kreslení</h2>
          <div className="text-xs font-bold text-indigo-500 bg-indigo-50 px-3 py-1 rounded-full uppercase tracking-widest">
            {lines.length} úseček
          </div>
        </div>

        <div className="relative aspect-square w-full border-4 border-gray-100 rounded-[2rem] bg-white overflow-hidden shadow-inner flex items-center justify-center">
          <svg 
            viewBox={`0 0 ${gridSize} ${gridSize}`} 
            className="w-full h-full"
            preserveAspectRatio="xMidYMid meet"
          >
            <defs>
              <pattern id="vectorGrid" width={step} height={step} patternUnits="userSpaceOnUse">
                <path d={`M ${step} 0 L 0 0 0 ${step}`} fill="none" stroke="#f1f5f9" strokeWidth="1"/>
              </pattern>
            </defs>
            <rect width={gridSize} height={gridSize} fill="url(#vectorGrid)" />

            {/* Axes */}
            <line x1="0" y1={gridSize} x2={gridSize} y2={gridSize} stroke="#94a3b8" strokeWidth="4" />
            <line x1="0" y1="0" x2="0" y2={gridSize} stroke="#94a3b8" strokeWidth="4" />

            {/* Grid labels every 100 units */}
            {[0, 100, 200, 300, 400].map(val => (
              <React.Fragment key={val}>
                <text x={val} y={gridSize - 5} fontSize="10" className="fill-gray-400 font-bold" textAnchor="middle">{val}</text>
                <text x="5" y={gridSize - val} fontSize="10" className="fill-gray-400 font-bold" alignmentBaseline="middle">{val}</text>
              </React.Fragment>
            ))}

            {/* Lines */}
            {lines.map((line, idx) => (
              <line
                key={idx}
                x1={line.x1}
                y1={gridSize - line.y1}
                x2={line.x2}
                y2={gridSize - line.y2}
                stroke="#4f46e5"
                strokeWidth="3"
                strokeLinecap="round"
              />
            ))}

            {/* Preview point/line */}
            {isChained && lastPoint && (
              <line
                x1={lastPoint.x}
                y1={gridSize - lastPoint.y}
                x2={p1.x}
                y2={gridSize - p1.y}
                stroke="#cbd5e1"
                strokeWidth="2"
                strokeDasharray="5,5"
              />
            )}

            {/* Last point indicator */}
            {lastPoint && (
              <circle cx={lastPoint.x} cy={gridSize - lastPoint.y} r="4" fill="#ef4444" />
            )}
          </svg>
        </div>

        <div className="mt-4 flex items-center text-gray-400 text-xs font-bold uppercase tracking-widest">
          <Info className="w-4 h-4 mr-2 text-indigo-500" />
          Zadávání probíhá v souřadnicích 0 až 400.
        </div>
      </div>

      {/* Control Panel */}
      <div className="w-full lg:w-96 flex flex-col gap-6">
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100">
          <h3 className="text-xl font-black text-gray-800 mb-8 flex items-center uppercase tracking-tight">
            <div className="w-3 h-8 bg-indigo-600 rounded-full mr-3"></div>
            Nástroje
          </h3>

          <div className="space-y-6">
            <div className="flex items-center justify-between p-4 bg-gray-50 rounded-2xl border-2 border-transparent hover:border-indigo-100 transition-all cursor-pointer select-none"
                 onClick={() => setIsChained(!isChained)}>
              <div className="flex flex-col">
                <span className="text-sm font-black text-gray-800 uppercase tracking-tight">Úsečky navazují</span>
                <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Kreslit řetězec bodů</span>
              </div>
              <div className={`w-12 h-6 rounded-full transition-colors flex items-center px-1 ${isChained ? 'bg-indigo-600' : 'bg-gray-300'}`}>
                <div className={`w-4 h-4 bg-white rounded-full transition-transform ${isChained ? 'translate-x-6' : 'translate-x-0'}`} />
              </div>
            </div>

            <div className="space-y-4">
              <div className="bg-indigo-50/50 p-6 rounded-3xl border-2 border-indigo-50">
                <p className="text-xs font-black text-indigo-700 uppercase tracking-widest mb-4 flex items-center">
                  {isChained ? (
                    <>Další bod (X, Y)</>
                  ) : (
                    <>Bod 1 (X1, Y1)</>
                  )}
                </p>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">X</label>
                    <input 
                      type="number" 
                      value={p1.x} 
                      onChange={(e) => handleInputChange('p1', 'x', e.target.value)}
                      className="w-full p-3 bg-white border-2 border-indigo-100 rounded-2xl text-center font-bold text-indigo-900 focus:border-indigo-500 outline-none transition-all"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Y</label>
                    <input 
                      type="number" 
                      value={p1.y} 
                      onChange={(e) => handleInputChange('p1', 'y', e.target.value)}
                      className="w-full p-3 bg-white border-2 border-indigo-100 rounded-2xl text-center font-bold text-indigo-900 focus:border-indigo-500 outline-none transition-all"
                    />
                  </div>
                </div>
              </div>

              {!isChained && (
                <div className="bg-purple-50/50 p-6 rounded-3xl border-2 border-purple-50 animate-in slide-in-from-top duration-300">
                  <p className="text-xs font-black text-purple-700 uppercase tracking-widest mb-4">Bod 2 (X2, Y2)</p>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">X</label>
                      <input 
                        type="number" 
                        value={p2.x} 
                        onChange={(e) => handleInputChange('p2', 'x', e.target.value)}
                        className="w-full p-3 bg-white border-2 border-purple-100 rounded-2xl text-center font-bold text-purple-900 focus:border-purple-500 outline-none transition-all"
                      />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Y</label>
                      <input 
                        type="number" 
                        value={p2.y} 
                        onChange={(e) => handleInputChange('p2', 'y', e.target.value)}
                        className="w-full p-3 bg-white border-2 border-purple-100 rounded-2xl text-center font-bold text-purple-900 focus:border-purple-500 outline-none transition-all"
                      />
                    </div>
                  </div>
                </div>
              )}

              <button
                onClick={handleAddLine}
                className="w-full py-5 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-3xl shadow-xl shadow-indigo-100 transition-all hover:scale-[1.02] active:scale-[0.98] flex items-center justify-center gap-3 uppercase tracking-widest text-sm mt-4"
              >
                <Plus className="w-5 h-5" />
                Přidej úsečku
              </button>
            </div>
          </div>
        </div>

        <div className="flex gap-4">
          <button 
            onClick={clearLines}
            className="flex-1 py-4 flex items-center justify-center bg-white hover:bg-red-50 text-red-400 hover:text-red-600 font-black rounded-3xl transition-all shadow-sm border-2 border-gray-100 uppercase text-[10px] tracking-widest"
          >
            <Trash2 className="w-4 h-4 mr-2" />
            Smazat vše
          </button>
          <div className="flex-1 bg-gradient-to-br from-indigo-50 to-purple-50 p-4 rounded-3xl border border-indigo-100 flex items-center gap-3">
             <HelpCircle className="w-4 h-4 text-indigo-400 shrink-0" />
             <p className="text-[10px] text-indigo-900 font-bold leading-tight uppercase">
               Osa Y roste směrem nahoru.
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

