import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Plus, Trash2, HelpCircle, Info, MousePointer2 } from 'lucide-react';
import { Line } from '../types';

interface VectorDrawingProps {
  onBack: () => void;
}

const VectorDrawing: React.FC<VectorDrawingProps> = ({ onBack }) => {
  const [lines, setLines] = useState<Line[]>([]);
  const [isChained, setIsChained] = useState(false);
  const [p1, setP1] = useState({ x: 0, y: 0 });
  const [p2, setP2] = useState({ x: 0, y: 0 });
  const [lastPoint, setLastPoint] = useState<{ x: number; y: number } | null>(null);
  const [settingPoint, setSettingPoint] = useState<'p1' | 'p2'>('p1');

  const svgRef = useRef<SVGSVGElement>(null);

  const gridSize = 10;
  const step = 1;

  const handleAddLine = () => {
    if (isChained) {
      if (lastPoint) {
        const newLine: Line = {
          x1: lastPoint.x,
          y1: lastPoint.y,
          x2: p1.x,
          y2: p1.y
        };
        setLines([...lines, newLine]);
      }
      setLastPoint({ x: p1.x, y: p1.y });
    } else {
      const newLine: Line = {
        x1: p1.x,
        y1: p1.y,
        x2: p2.x,
        y2: p2.y
      };
      setLines([...lines, newLine]);
    }
  };

  const handleGridClick = (e: React.MouseEvent<SVGSVGElement>) => {
    if (!svgRef.current) return;

    const svg = svgRef.current;
    const pt = svg.createSVGPoint();
    pt.x = e.clientX;
    pt.y = e.clientY;

    const svgP = pt.matrixTransform(svg.getScreenCTM()?.inverse());

    // Snap to nearest integer
    const snappedX = Math.round(Math.max(0, Math.min(gridSize, svgP.x)));
    const snappedY = Math.round(Math.max(0, Math.min(gridSize, gridSize - svgP.y)));

    if (isChained) {
      const newPoint = { x: snappedX, y: snappedY };
      setP1(newPoint);

      if (lastPoint) {
        setLines([...lines, { x1: lastPoint.x, y1: lastPoint.y, x2: snappedX, y2: snappedY }]);
      }
      setLastPoint(newPoint);
    } else {
      const newPoint = { x: snappedX, y: snappedY };
      if (settingPoint === 'p1') {
        setP1(newPoint);
        setSettingPoint('p2');
      } else {
        setP2(newPoint);
        setLines([...lines, { x1: p1.x, y1: p1.y, x2: snappedX, y2: snappedY }]);
        setSettingPoint('p1');
      }
    }
  };

  const clearLines = () => {
    if (confirm('Opravdu chcete smazat celý obrázek?')) {
      setLines([]);
      setLastPoint(null);
      setSettingPoint('p1');
    }
  };

  const handleInputChange = (point: 'p1' | 'p2', axis: 'x' | 'y', value: string) => {
    const num = Math.min(gridSize, Math.max(0, parseInt(value) || 0));
    if (point === 'p1') {
      setP1(prev => ({ ...prev, [axis]: num }));
    } else {
      setP2(prev => ({ ...prev, [axis]: num }));
    }
  };

  useEffect(() => {
    if (!isChained) {
      setLastPoint(null);
