  onBack: () => void;
}

const VectorDrawing: React.FC<VectorDrawingProps> = ({ onBack }) => {
  const [points, setPoints] = useState<Point[]>([]);
  const [currentP, setCurrentP] = useState<Point>({ x: 0, y: 0 });

  const svgRef = useRef<SVGSVGElement>(null);

  const gridSize = 10;
  const step = 1;

