  y: number;
}

interface Line {
  p1: Point;
  p2: Point;
}

interface VectorDrawingProps {
  onBack: () => void;
  mode?: 'points' | 'lines';
}

const VectorDrawing: React.FC<VectorDrawingProps> = ({ onBack, mode = 'points' }) => {
  const [points, setPoints] = useState<Point[]>([]);
