export type Difficulty = 'easy' | 'medium' | 'hard';
export type Screen = 'landing' | 'splash' | 'menu' | 'drawing' | 'quiz' | 'lines-menu' | 'vector-drawing' | 'line-drawing' | 'shape-puzzle';

import React, { useState } from 'react';
import LandingPage from './components/LandingPage';
import SplashScreen from './components/SplashScreen';
import Menu from './components/Menu';
import RGBDrawing from './components/RGBDrawing';
import Quiz from './components/Quiz';
import LinesMenu from './components/LinesMenu';
import VectorDrawing from './components/VectorDrawing';
import ShapePuzzle from './components/ShapePuzzle';
import { Screen, Difficulty, Segment } from './types';
import { ROCKET_DATA, CAT_DATA, COMPUTER_DATA } from './constants';

const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<Screen>('landing');
  const [selectedData, setSelectedData] = useState<Segment[]>([]);
  const [levelName, setLevelName] = useState<string>('');

  const handleStartLevel = (difficulty: Difficulty) => {
    switch (difficulty) {
      case 'easy':
        setSelectedData(ROCKET_DATA);
        setLevelName('Raketa');
        break;
      case 'medium':
        setSelectedData(CAT_DATA);
        setLevelName('Kočka');
        break;
      case 'hard':
        setSelectedData(COMPUTER_DATA);
        setLevelName('Počítač');
        break;
    }
    setCurrentScreen('drawing');
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case 'landing':
        return (
          <LandingPage 
            onStartColors={() => setCurrentScreen('splash')} 
            onStartLines={() => setCurrentScreen('lines-menu')} 
          />
        );
      case 'lines-menu':
        return (
          <LinesMenu 
            onShapePuzzle={() => setCurrentScreen('shape-puzzle')}
            onVectorDrawing={() => setCurrentScreen('vector-drawing')}
            onLineDrawing={() => setCurrentScreen('line-drawing')}
            onBack={() => setCurrentScreen('landing')}
          />
        );
      case 'shape-puzzle':
        return (
          <ShapePuzzle onBack={() => setCurrentScreen('lines-menu')} />
        );
      case 'vector-drawing':
        return (
          <VectorDrawing 
            mode="points"
            onBack={() => setCurrentScreen('lines-menu')}
          />
        );
      case 'line-drawing':
        return (
          <VectorDrawing 
            mode="lines"
            onBack={() => setCurrentScreen('lines-menu')}
          />
        );
      case 'splash':
        return (
          <SplashScreen 
            onEnter={() => setCurrentScreen('menu')} 
            onQuiz={() => setCurrentScreen('quiz')}
            onBack={() => setCurrentScreen('landing')}
          />
        );
      case 'menu':
        return <Menu onStart={handleStartLevel} onBack={() => setCurrentScreen('splash')} />;
      case 'drawing':
        return (
          <RGBDrawing 
            onBack={() => setCurrentScreen('menu')} 
            initialSegments={selectedData}
            title={levelName}
          />
        );
      case 'quiz':
        return <Quiz onBack={() => setCurrentScreen('splash')} />;
      default:
        return <LandingPage onStartColors={() => setCurrentScreen('splash')} onStartLines={() => setCurrentScreen('lines-menu')} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-[#f8fafc]">
      {renderScreen()}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { ArrowLeft, RefreshCcw, MousePointer2, LayoutGrid, Trash2, CheckCircle } from 'lucide-react';

type ShapeType = 'square' | 'triangle-left' | 'triangle-right';

interface PlacedShape {
  id: string;
  type: ShapeType;
  x: number;
  y: number;
  color: string;
}

interface ShapePuzzleProps {
  onBack: () => void;
}

const ShapePuzzle: React.FC<ShapePuzzleProps> = ({ onBack }) => {
  const [placedShapes, setPlacedShapes] = useState<PlacedShape[]>([]);
  const [selectedShapeType, setSelectedShapeType] = useState<ShapeType | null>(null);
  const [selectedColor, setSelectedColor] = useState<string>('#5D9CEC');

  const svgRef = useRef<SVGSVGElement>(null);
  const gridSize = 10;
  const step = 1;

  const handleGridClick = (e: React.MouseEvent<SVGSVGElement>) => {
    if (!svgRef.current || !selectedShapeType) return;

    const svg = svgRef.current;
    const pt = svg.createSVGPoint();
    pt.x = e.clientX;
    pt.y = e.clientY;

    const svgP = pt.matrixTransform(svg.getScreenCTM()?.inverse());

    // Snap to grid (bottom-left coordinate of the shape)
    const snappedX = Math.floor(Math.max(0, Math.min(gridSize - 1, svgP.x)));
    const snappedY = Math.floor(Math.max(0, Math.min(gridSize - 1, gridSize - svgP.y)));

    const newShape: PlacedShape = {
      id: Math.random().toString(36).substr(2, 9),
      type: selectedShapeType,
      x: snappedX,
      y: snappedY,
      color: selectedColor,
    };

    setPlacedShapes(prev => [...prev, newShape]);
  };

  const removeShape = (id: string) => {
    setPlacedShapes(prev => prev.filter(s => s.id !== id));
  };

  const clearAll = () => setPlacedShapes([]);

  const renderShapePath = (shape: PlacedShape | { type: ShapeType; x: number; y: number; color: string }, isPreview = false) => {
    const { type, x, y, color } = shape;
    const baseY = gridSize - y;

    let d = "";
    if (type === 'square') {
      d = `M ${x} ${baseY} L ${x+1} ${baseY} L ${x+1} ${baseY-1} L ${x} ${baseY-1} Z`;
    } else if (type === 'triangle-left') {
      // Pointy top-right
      d = `M ${x} ${baseY} L ${x+1} ${baseY} L ${x+1} ${baseY-1} Z`;
    } else if (type === 'triangle-right') {
      // Pointy top-left
      d = `M ${x} ${baseY} L ${x+1} ${baseY} L ${x} ${baseY-1} Z`;
    }

    return (
      <path 
        d={d} 
        fill={color} 
        stroke="rgba(0,0,0,0.1)" 
        strokeWidth="0.05"
        className={`${isPreview ? 'opacity-30' : 'animate-in zoom-in-50 duration-200'}`}
      />
    );
  };

  const paletteItems = [
    { type: 'square' as ShapeType, color: '#5D9CEC', label: 'Modrý čtverec' },
    { type: 'square' as ShapeType, color: '#FFCE54', label: 'Žlutý čtverec' },
    { type: 'triangle-left' as ShapeType, color: '#A0D468', label: 'Zelený trojúhelník' },
    { type: 'triangle-right' as ShapeType, color: '#FC6E51', label: 'Oranžový trojúhelník' },
  ];

  return (
    <div className="w-full max-w-6xl flex flex-col lg:flex-row gap-8 items-start animate-in fade-in duration-500">
      {/* Grid Area */}
      <div className="flex-1 bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 w-full overflow-hidden">
        <div className="flex items-center justify-between mb-6">
          <button 
            onClick={onBack}
            className="flex items-center text-gray-400 hover:text-orange-600 transition-colors font-bold"
          >
            <ArrowLeft className="w-5 h-5 mr-2" />
            Zpět
          </button>
          <div className="text-right">
            <h2 className="text-xl font-black text-gray-800 uppercase tracking-tighter">Skládání tvarů</h2>
            <div className="text-[10px] font-bold text-orange-500 bg-orange-50 px-3 py-1 rounded-full uppercase tracking-widest inline-block mt-1">
              {placedShapes.length} prvků
            </div>
          </div>
        </div>

        <div className="relative aspect-square w-full border-4 border-gray-100 rounded-[2rem] bg-white overflow-hidden shadow-inner flex items-center justify-center p-6">
          <svg 
            ref={svgRef}
            viewBox="-0.5 -0.5 11 11" 
            className="w-full h-full cursor-pointer select-none"
            preserveAspectRatio="xMidYMid meet"
            onClick={handleGridClick}
          >
            <defs>
              <pattern id="shapeGrid" width={step} height={step} patternUnits="userSpaceOnUse">
                <rect width={step} height={step} fill="none" stroke="#f1f5f9" strokeWidth="0.05"/>
              </pattern>
            </defs>
            <rect x="0" y="0" width={gridSize} height={gridSize} fill="url(#shapeGrid)" pointerEvents="all" />

            {/* Shapes */}
            {placedShapes.map(shape => (
              <g key={shape.id} onClick={(e) => { e.stopPropagation(); removeShape(shape.id); }} className="cursor-help">
                {renderShapePath(shape)}
              </g>
            ))}

            {/* Preview */}
            {selectedShapeType && (
              <g className="pointer-events-none">
                {/* Visual cursor helper could go here */}
              </g>
            )}
          </svg>
        </div>

        <div className="mt-4 flex items-center text-gray-400 text-xs font-bold uppercase tracking-widest">
          <MousePointer2 className="w-4 h-4 mr-2 text-orange-500" />
          Vyber tvar vpravo a kliknutím do mřížky ho umísti. Kliknutím na tvar ho smažeš.
        </div>
      </div>

      {/* Control Panel */}
      <div className="w-full lg:w-96 flex flex-col gap-6">
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100">
          <h3 className="text-xl font-black text-gray-800 mb-6 flex items-center uppercase tracking-tight">
            <div className="w-3 h-8 bg-orange-600 rounded-full mr-3"></div>
            Paleta tvarů
          </h3>

          <div className="grid grid-cols-2 gap-4 mb-8">
            {paletteItems.map((item, idx) => (
              <button
                key={idx}
                onClick={() => {
                  setSelectedShapeType(item.type);
                  setSelectedColor(item.color);
                }}
                className={`flex flex-col items-center justify-center p-4 rounded-3xl border-4 transition-all ${
                  selectedShapeType === item.type && selectedColor === item.color
                    ? 'border-orange-500 bg-orange-50 shadow-inner'
                    : 'border-gray-50 bg-white hover:border-gray-200'
                }`}
              >
                <div className="w-12 h-12 mb-3 drop-shadow-sm">
                  <svg viewBox="0 0 1 1">
                    {renderShapePath({ type: item.type, x: 0, y: 0, color: item.color })}
                  </svg>
                </div>
                <span className="text-[9px] font-black uppercase text-gray-500 tracking-tighter">
                  {item.label}
                </span>
              </button>
            ))}
          </div>

          <div className="bg-gray-50 p-6 rounded-[2rem] border-2 border-gray-100">
             <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center">
               <LayoutGrid className="w-4 h-4 mr-2" />
               Úkoly k procvičení
             </h4>
             <ul className="space-y-3">
               {[
                 "Poskládej obdélník ze 2 čtverců",
                 "Poskládej rovnoběžník",
                 "Poskládej lichoběžník"
               ].map((task, i) => (
                 <li key={i} className="flex items-center gap-2 text-[10px] font-bold text-gray-600 uppercase tracking-tight leading-tight">
                   <div className="w-4 h-4 rounded-full bg-white border border-gray-200 flex items-center justify-center text-[8px] text-gray-300">
                     {i+1}
                   </div>
                   {task}
                 </li>
               ))}
             </ul>
          </div>
        </div>

        <button 
          onClick={clearAll}
          className="w-full py-4 flex items-center justify-center bg-white hover:bg-red-50 text-red-500 hover:text-red-600 font-black rounded-[2rem] transition-all shadow-sm border-2 border-red-50 hover:border-red-200 uppercase text-xs tracking-widest"
        >
          <RefreshCcw className="w-4 h-4 mr-2" />
          Vyčistit plochu
        </button>

        <div className="bg-gradient-to-br from-orange-50 to-yellow-50 p-6 rounded-[2.5rem] border border-orange-100 flex items-start gap-3">
             <CheckCircle className="w-6 h-6 text-orange-400 shrink-0" />
             <div className="space-y-1">
               <p className="text-[10px] text-orange-900 font-black leading-tight uppercase tracking-tight">
                 Cíl aktivity
               </p>
               <p className="text-[9px] text-orange-700/70 font-bold leading-relaxed uppercase tracking-wider">
                 Naučit se, jak se složitější tvary skládají ze základních prvků a jak funguje jejich orientace.
               </p>
             </div>
          </div>
      </div>
    </div>
  );
};

