import React, { useState, useRef } from 'react';
import { ArrowLeft, RefreshCcw, MousePointer2, LayoutGrid, Trash2, CheckCircle, Square, Triangle, HelpCircle } from 'lucide-react';

type ShapeType = 'square' | 'triangle-left' | 'triangle-right';

interface PlacedShape {
  id: string;
  type: ShapeType;
  x: number;
  y: number;
  color: string;
}

interface ShapePuzzleProps {
  onBack: () => void;
}

const ShapePuzzle: React.FC<ShapePuzzleProps> = ({ onBack }) => {
  const [placedShapes, setPlacedShapes] = useState<PlacedShape[]>([]);
  const [selectedShapeType, setSelectedShapeType] = useState<ShapeType>('square');
  const [selectedColor, setSelectedColor] = useState<string>('#5D9CEC');

  const svgRef = useRef<SVGSVGElement>(null);
  const gridSize = 10;
  const step = 1;

  const handleGridClick = (e: React.MouseEvent<SVGSVGElement>) => {
    if (!svgRef.current) return;

    const svg = svgRef.current;
    const pt = svg.createSVGPoint();
    pt.x = e.clientX;
    pt.y = e.clientY;

    const svgP = pt.matrixTransform(svg.getScreenCTM()?.inverse());

    // Snap to grid (floor to stay within the unit cell)
    const snappedX = Math.floor(Math.max(0, Math.min(gridSize - 1, svgP.x)));
    const snappedY = Math.floor(Math.max(0, Math.min(gridSize - 1, gridSize - svgP.y)));

    const newShape: PlacedShape = {
      id: Math.random().toString(36).substr(2, 9),
      type: selectedShapeType,
      x: snappedX,
      y: snappedY,
      color: selectedColor,
    };

    setPlacedShapes(prev => [...prev, newShape]);
  };

  const removeShape = (id: string) => {
    setPlacedShapes(prev => prev.filter(s => s.id !== id));
  };

  const clearAll = () => setPlacedShapes([]);

  const renderShapePath = (type: ShapeType, x: number, y: number, color: string, isPreview = false) => {
    const baseY = gridSize - y;
    let d = "";

    if (type === 'square') {
      d = `M ${x} ${baseY} L ${x+1} ${baseY} L ${x+1} ${baseY-1} L ${x} ${baseY-1} Z`;
    } else if (type === 'triangle-left') {
      // Right triangle pointing top-right (slant on the left)
      d = `M ${x} ${baseY} L ${x+1} ${baseY} L ${x+1} ${baseY-1} Z`;
    } else if (type === 'triangle-right') {
      // Right triangle pointing top-left (slant on the right)
      d = `M ${x} ${baseY} L ${x+1} ${baseY} L ${x} ${baseY-1} Z`;
    }

    return (
      <path 
        d={d} 
        fill={color} 
        stroke="rgba(0,0,0,0.15)" 
        strokeWidth="0.05"
        className={`${isPreview ? 'opacity-30' : 'animate-in zoom-in-50 duration-200'}`}
      />
    );
  };

  const renderPaletteIcon = (type: ShapeType, color: string) => {
    let d = "";
    if (type === 'square') {
      d = "M 0.1 0.1 H 0.9 V 0.9 H 0.1 Z";
    } else if (type === 'triangle-left') {
      // Slant on left
      d = "M 0.1 0.9 H 0.9 V 0.1 Z";
    } else if (type === 'triangle-right') {
      // Slant on right
      d = "M 0.1 0.9 H 0.9 L 0.1 0.1 Z";
    }
    return <path d={d} fill={color} stroke="rgba(0,0,0,0.2)" strokeWidth="0.05" />;
  };

  const paletteItems = [
    { type: 'square' as ShapeType, color: '#5D9CEC', label: 'Modrý čtverec', icon: Square },
    { type: 'square' as ShapeType, color: '#FFCE54', label: 'Žlutý čtverec', icon: Square },
    { type: 'triangle-left' as ShapeType, color: '#FC6E51', label: 'Oranžový díl', icon: Triangle },
    { type: 'triangle-right' as ShapeType, color: '#A0D468', label: 'Zelený díl', icon: Triangle },
  ];

  return (
    <div className="w-full max-w-6xl flex flex-col lg:flex-row gap-8 items-start animate-in fade-in duration-500">
      {/* Grid Area */}
      <div className="flex-1 bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 w-full overflow-hidden">
        <div className="flex items-center justify-between mb-6">
          <button 
            onClick={onBack}
            className="flex items-center text-gray-400 hover:text-orange-600 transition-colors font-bold"
          >
            <ArrowLeft className="w-5 h-5 mr-2" />
            Zpět
          </button>
          <div className="text-right">
            <h2 className="text-xl font-black text-gray-800 uppercase tracking-tighter">Skládání tvarů</h2>
            <div className="text-[10px] font-bold text-orange-500 bg-orange-50 px-3 py-1 rounded-full uppercase tracking-widest inline-block mt-1">
              {placedShapes.length} dílků
            </div>
          </div>
        </div>

        <div className="bg-orange-50/50 p-4 rounded-3xl mb-6 border border-orange-100">
          <p className="text-sm font-black text-orange-900 uppercase tracking-tight flex items-center leading-tight">
            <HelpCircle className="w-4 h-4 mr-2" />
            Aktivita: Poskládejte z čtverců a trojúhelníků:
          </p>
          <p className="text-xs text-orange-700/70 font-bold uppercase tracking-widest mt-1">
            Obdélník • Rovnoběžník • Lichoběžník
          </p>
        </div>

        <div className="relative aspect-square w-full border-4 border-gray-100 rounded-[2rem] bg-white overflow-hidden shadow-inner flex items-center justify-center p-6">
          <svg 
            ref={svgRef}
            viewBox="-0.5 -0.5 11 11" 
            className="w-full h-full cursor-pointer select-none"
            preserveAspectRatio="xMidYMid meet"
            onClick={handleGridClick}
          >
            <defs>
              <pattern id="shapeGrid" width={step} height={step} patternUnits="userSpaceOnUse">
                <rect width={step} height={step} fill="none" stroke="#f1f5f9" strokeWidth="0.05"/>
              </pattern>
            </defs>
            <rect x="0" y="0" width={gridSize} height={gridSize} fill="url(#shapeGrid)" pointerEvents="all" />

            {/* Placed Shapes */}
            {placedShapes.map(shape => (
              <g key={shape.id} onClick={(e) => { e.stopPropagation(); removeShape(shape.id); }} className="cursor-pointer hover:opacity-80 transition-opacity">
                {renderShapePath(shape.type, shape.x, shape.y, shape.color)}
              </g>
            ))}
          </svg>
        </div>

        <div className="mt-4 flex items-center text-gray-400 text-xs font-bold uppercase tracking-widest leading-tight">
          <MousePointer2 className="w-4 h-4 mr-2 text-orange-500" />
          Vyber tvar vpravo a umísti ho do mřížky. Kliknutím na dílek ho smažeš.
        </div>
      </div>

      {/* Control Panel */}
      <div className="w-full lg:w-96 flex flex-col gap-6">
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100">
          <h3 className="text-xl font-black text-gray-800 mb-6 flex items-center uppercase tracking-tight">
            <div className="w-3 h-8 bg-orange-600 rounded-full mr-3"></div>
            Paleta prvků
          </h3>

          <div className="grid grid-cols-2 gap-4 mb-8">
            {paletteItems.map((item, idx) => {
              const isActive = selectedShapeType === item.type && selectedColor === item.color;

              return (
                <button
                  key={idx}
                  onClick={() => {
                    setSelectedShapeType(item.type);
                    setSelectedColor(item.color);
                  }}
                  className={`flex flex-col items-center justify-center p-5 rounded-[2.5rem] border-4 transition-all duration-300 group ${
                    isActive
                      ? 'border-orange-500 bg-orange-50 shadow-inner scale-100'
                      : 'border-gray-50 bg-white hover:border-gray-200 hover:scale-105 shadow-sm'
                  }`}
                >
                  <div className="w-16 h-16 mb-4 flex items-center justify-center relative">
                    <svg viewBox="0 0 1 1" className="w-full h-full drop-shadow-md">
                      {renderPaletteIcon(item.type, item.color)}
                    </svg>
                  </div>
                  <span className={`text-[10px] font-black uppercase tracking-tighter leading-tight ${
                    isActive ? 'text-orange-600' : 'text-gray-500'
                  }`}>
                    {item.label}
                  </span>
                </button>
              );
            })}
          </div>

          <div className="bg-gray-50 p-6 rounded-[2rem] border-2 border-gray-100">
             <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center">
               <LayoutGrid className="w-4 h-4 mr-2" />
               Úkoly z učebnice
             </h4>
             <ul className="space-y-3">
               {[
                 "Obdélník (ze 2 čtverců)",
                 "Rovnoběžník (čtverce + trojúhelníky)",
                 "Lichoběžník (ze všech 4 dílů)"
               ].map((task, i) => (
                 <li key={i} className="flex items-center gap-2 text-[10px] font-bold text-gray-600 uppercase tracking-tight leading-tight">
                   <div className="w-5 h-5 rounded-lg bg-white border border-gray-200 flex items-center justify-center text-[10px] text-orange-500 font-black">
                     {i+1}
                   </div>
                   {task}
                 </li>
               ))}
             </ul>
          </div>
        </div>

        <div className="flex flex-col gap-4">
          <button 
            onClick={clearAll}
            className="w-full py-5 flex items-center justify-center bg-white hover:bg-red-50 text-red-500 hover:text-red-600 font-black rounded-[2.5rem] transition-all shadow-sm border-2 border-red-50 hover:border-red-200 uppercase text-xs tracking-widest"
          >
            <RefreshCcw className="w-4 h-4 mr-2" />
            Vymazat celou plochu
          </button>

          <div className="bg-gradient-to-br from-orange-500 to-orange-600 p-6 rounded-[2.5rem] shadow-xl shadow-orange-100 text-white">
             <div className="flex items-start gap-4">
               <div className="bg-white/20 p-2 rounded-xl">
                 <CheckCircle className="w-6 h-6 text-white" />
               </div>
               <div>
                 <p className="text-[10px] font-black uppercase tracking-widest opacity-80 mb-1">
                   Cíl studia
                 </p>
                 <p className="text-xs font-bold leading-relaxed">
                   Naučit se skládat složité geometrické útvary ze základních prvků.
                 </p>
               </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ShapePuzzle;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, RefreshCcw, MousePointer2, LayoutGrid, RotateCw, CheckCircle, HelpCircle, GripVertical } from 'lucide-react';

type ShapeType = 'square' | 'triangle';

interface PlacedShape {
  id: string;
  type: ShapeType;
  x: number;
  y: number;
  rotation: number; // 0, 1, 2, 3 (steps of 90 degrees)
  color: string;
  label: string;
}

const INITIAL_SHAPES: PlacedShape[] = [
  { id: 'sq-1', type: 'square', x: 1, y: 1, rotation: 0, color: '#5D9CEC', label: 'Modrý čtverec' },
  { id: 'sq-2', type: 'square', x: 3, y: 1, rotation: 0, color: '#FFCE54', label: 'Žlutý čtverec' },
  { id: 'tr-1', type: 'triangle', x: 5, y: 1, rotation: 0, color: '#FC6E51', label: 'Oranžový díl' },
  { id: 'tr-2', type: 'triangle', x: 7, y: 1, rotation: 2, color: '#A0D468', label: 'Zelený díl' },
];

interface ShapePuzzleProps {
  onBack: () => void;
}

const ShapePuzzle: React.FC<ShapePuzzleProps> = ({ onBack }) => {
  const [shapes, setShapes] = useState<PlacedShape[]>(INITIAL_SHAPES);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const svgRef = useRef<SVGSVGElement>(null);
  const gridSize = 10;

  // Convert mouse coordinates to SVG coordinates
  const getSVGPoint = (e: React.MouseEvent | MouseEvent) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    const svg = svgRef.current;
    const pt = svg.createSVGPoint();
    pt.x = e.clientX;
    pt.y = e.clientY;
    return pt.matrixTransform(svg.getScreenCTM()?.inverse());
  };

  const handleMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const point = getSVGPoint(e);
    const shape = shapes.find(s => s.id === id);
    if (shape) {
      setDraggingId(id);
      setSelectedId(id);
      setDragOffset({
        x: point.x - shape.x,
        y: (gridSize - point.y) - shape.y
      });
    }
  };

  const handleMouseMove = (e: MouseEvent) => {
    if (!draggingId) return;

    const point = getSVGPoint(e);
    const newX = point.x - dragOffset.x;
    const newY = (gridSize - point.y) - dragOffset.y;

    setShapes(prev => prev.map(s => 
      s.id === draggingId 
        ? { ...s, x: newX, y: newY } 
        : s
    ));
  };

  const handleMouseUp = () => {
    if (draggingId) {
      // Snap to grid on release
      setShapes(prev => prev.map(s => 
        s.id === draggingId 
          ? { ...s, x: Math.round(Math.max(0, Math.min(gridSize - 1, s.x))), y: Math.round(Math.max(0, Math.min(gridSize - 1, s.y))) } 
          : s
      ));
      setDraggingId(null);
    }
  };

  useEffect(() => {
    if (draggingId) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    } else {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [draggingId, dragOffset]);

  const rotateShape = (id: string) => {
    setShapes(prev => prev.map(s => 
      s.id === id ? { ...s, rotation: (s.rotation + 1) % 4 } : s
    ));
  };

  const resetAll = () => {
    setShapes(INITIAL_SHAPES);
    setSelectedId(null);
  };

  const getShapePath = (type: ShapeType, rotation: number) => {
    if (type === 'square') {
      return "M 0 0 H 1 V 1 H 0 Z";
    }
    // Triangle rotations (right-angled triangle occupying half of a 1x1 cell)
    const paths = [
      "M 0 1 L 1 1 L 1 0 Z", // Bottom-right half
      "M 1 1 L 1 0 L 0 0 Z", // Top-right half
      "M 1 0 L 0 0 L 0 1 Z", // Top-left half
      "M 0 0 L 0 1 L 1 1 Z", // Bottom-left half
    ];
    return paths[rotation];
  };

  return (
    <div className="w-full max-w-6xl flex flex-col lg:flex-row gap-8 items-start animate-in fade-in duration-500">
      {/* Grid Area */}
      <div className="flex-1 bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 w-full overflow-hidden">
        <div className="flex items-center justify-between mb-6">
          <button 
            onClick={onBack}
            className="flex items-center text-gray-400 hover:text-orange-600 transition-colors font-bold"
          >
            <ArrowLeft className="w-5 h-5 mr-2" />
            Zpět
          </button>
          <div className="text-right">
            <h2 className="text-xl font-black text-gray-800 uppercase tracking-tighter">Geometrická laboratoř</h2>
            <div className="text-[10px] font-bold text-orange-500 bg-orange-50 px-3 py-1 rounded-full uppercase tracking-widest inline-block mt-1">
              Interaktivní skládání
            </div>
          </div>
        </div>

        <div className="bg-orange-50/50 p-4 rounded-3xl mb-6 border border-orange-100">
          <p className="text-sm font-black text-orange-900 uppercase tracking-tight flex items-center leading-tight">
            <HelpCircle className="w-4 h-4 mr-2" />
            Úkol: Posuň a otoč dílky tak, abys vytvořil obrazce:
          </p>
          <div className="flex gap-4 mt-2">
            <span className="text-[10px] bg-white px-2 py-0.5 rounded-full text-orange-600 font-black border border-orange-100">OBDÉLNÍK</span>
            <span className="text-[10px] bg-white px-2 py-0.5 rounded-full text-orange-600 font-black border border-orange-100">ROVNOBĚŽNÍK</span>
            <span className="text-[10px] bg-white px-2 py-0.5 rounded-full text-orange-600 font-black border border-orange-100">LICHOBĚŽNÍK</span>
          </div>
        </div>

        <div className="relative aspect-square w-full border-4 border-gray-100 rounded-[2rem] bg-white overflow-hidden shadow-inner flex items-center justify-center p-6">
          <svg 
            ref={svgRef}
            viewBox="-0.5 -0.5 11 11" 
            className="w-full h-full select-none touch-none"
            preserveAspectRatio="xMidYMid meet"
          >
            <defs>
              <pattern id="puzzleGrid" width="1" height="1" patternUnits="userSpaceOnUse">
                <rect width="1" height="1" fill="none" stroke="#f1f5f9" strokeWidth="0.05"/>
              </pattern>
            </defs>
            <rect x="0" y="0" width={gridSize} height={gridSize} fill="url(#puzzleGrid)" pointerEvents="none" />

            {/* Shapes */}
            {shapes.map(shape => (
              <g 
                key={shape.id} 
                transform={`translate(${shape.x}, ${gridSize - shape.y - 1})`}
                onMouseDown={(e) => handleMouseDown(e, shape.id)}
                onClick={() => !draggingId && rotateShape(shape.id)}
                className={`cursor-move transition-opacity ${draggingId === shape.id ? 'opacity-70' : 'hover:opacity-90'}`}
              >
                <path 
                  d={getShapePath(shape.type, shape.rotation)} 
                  fill={shape.color} 
                  stroke={selectedId === shape.id ? "white" : "rgba(0,0,0,0.15)"} 
                  strokeWidth={selectedId === shape.id ? "0.1" : "0.05"}
                  className="drop-shadow-sm transition-all"
                />
                {selectedId === shape.id && (
                  <rect x="-0.05" y="-0.05" width="1.1" height="1.1" fill="none" stroke="#3b82f6" strokeWidth="0.05" strokeDasharray="0.1,0.1" pointerEvents="none" />
                )}
              </g>
            ))}
          </svg>
        </div>

        <div className="mt-4 flex items-center text-gray-400 text-xs font-bold uppercase tracking-widest leading-tight">
          <MousePointer2 className="w-4 h-4 mr-2 text-orange-500" />
          Táhni dílek pro přesun • Klikni pro otočení o 90°
        </div>
      </div>

      {/* Control Panel */}
      <div className="w-full lg:w-96 flex flex-col gap-6">
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100">
          <h3 className="text-xl font-black text-gray-800 mb-6 flex items-center uppercase tracking-tight">
            <div className="w-3 h-8 bg-orange-600 rounded-full mr-3"></div>
            Prvky na ploše
          </h3>

          <div className="space-y-3 mb-8">
            {shapes.map((shape) => (
              <div 
                key={shape.id}
                onClick={() => setSelectedId(shape.id)}
                className={`flex items-center justify-between p-4 rounded-3xl border-2 transition-all cursor-pointer ${
                  selectedId === shape.id ? 'border-orange-500 bg-orange-50 shadow-sm' : 'border-gray-50 hover:border-gray-200'
                }`}
              >
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-lg shadow-sm" style={{ backgroundColor: shape.color }}></div>
                  <span className="text-[10px] font-black uppercase tracking-tight text-gray-700">{shape.label}</span>
                </div>
                <div className="flex gap-2">
                  <button 
                    onClick={(e) => { e.stopPropagation(); rotateShape(shape.id); }}
                    className="p-2 bg-white rounded-xl shadow-sm border border-gray-100 hover:text-orange-600 transition-colors"
                    title="Otočit"
                  >
                    <RotateCw className="w-4 h-4" />
                  </button>
                </div>
              </div>
            ))}
          </div>

          <div className="bg-gray-50 p-6 rounded-[2rem] border-2 border-gray-100">
             <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center">
               <LayoutGrid className="w-4 h-4 mr-2" />
