import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, RefreshCcw, MousePointer2, LayoutGrid, RotateCw, CheckCircle, HelpCircle, Magnet } from 'lucide-react';

type ShapeType = 'square' | 'triangle-roof' | 'triangle-right';

interface PlacedShape {
  id: string;
  type: ShapeType;
  x: number;
  y: number;
  rotation: number; // 0, 1, 2, 3 (steps of 90 degrees)
  color: string;
  label: string;
}

const INITIAL_SHAPES: PlacedShape[] = [
  { id: 'sq-1', type: 'square', x: 1, y: 7, rotation: 0, color: '#5D9CEC', label: 'Modrý čtverec' },
  { id: 'sq-2', type: 'square', x: 2.5, y: 7, rotation: 0, color: '#FFCE54', label: 'Žlutý čtverec' },
  { id: 'tr-roof', type: 'triangle-roof', x: 4, y: 7, rotation: 0, color: '#FC6E51', label: 'Střecha' },
  { id: 'tr-r1', type: 'triangle-right', x: 6, y: 7, rotation: 0, color: '#A0D468', label: 'Zelený díl' },
  { id: 'tr-r2', type: 'triangle-right', x: 7.5, y: 7, rotation: 2, color: '#AC92EC', label: 'Fialový díl' },
];

interface ShapePuzzleProps {
  onBack: () => void;
}

const ShapePuzzle: React.FC<ShapePuzzleProps> = ({ onBack }) => {
  const [shapes, setShapes] = useState<PlacedShape[]>(INITIAL_SHAPES);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [useGrid, setUseGrid] = useState(false);

  const svgRef = useRef<SVGSVGElement>(null);
  const gridSize = 10;

  const getSVGPoint = (e: React.MouseEvent | MouseEvent) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    const svg = svgRef.current;
    const pt = svg.createSVGPoint();
    pt.x = e.clientX;
    pt.y = e.clientY;
    return pt.matrixTransform(svg.getScreenCTM()?.inverse());
  };

  const handleMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const point = getSVGPoint(e);
    const shape = shapes.find(s => s.id === id);
    if (shape) {
      setDraggingId(id);
      setSelectedId(id);
      setDragOffset({
        x: point.x - shape.x,
        y: (gridSize - point.y) - shape.y
      });
      // Move dragged element to top of the stack
      setShapes(prev => {
        const others = prev.filter(s => s.id !== id);
        return [...others, shape];
      });
    }
  };

  const handleMouseMove = (e: MouseEvent) => {
    if (!draggingId) return;

    const point = getSVGPoint(e);
    let newX = point.x - dragOffset.x;
    let newY = (gridSize - point.y) - dragOffset.y;

    if (useGrid) {
      newX = Math.round(newX * 2) / 2; // Snap to 0.5 units
      newY = Math.round(newY * 2) / 2;
    }

    setShapes(prev => prev.map(s => 
      s.id === draggingId 
        ? { ...s, x: newX, y: newY } 
        : s
    ));
  };

  const handleMouseUp = () => {
    setDraggingId(null);
  };

  useEffect(() => {
    if (draggingId) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    } else {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [draggingId, dragOffset, useGrid]);

  const rotateShape = (id: string) => {
    setShapes(prev => prev.map(s => 
      s.id === id ? { ...s, rotation: (s.rotation + 1) % 4 } : s
    ));
  };

  const resetAll = () => {
    setShapes(INITIAL_SHAPES);
    setSelectedId(null);
  };

  const getShapePath = (type: ShapeType, rotation: number) => {
    // Rotation is handled by SVG transform for simplicity in coordinate space
    if (type === 'square') {
      return "M -0.5 -0.5 H 0.5 V 0.5 H -0.5 Z";
    }
    if (type === 'triangle-roof') {
      // Isosceles "Roof" triangle
      return "M -0.5 0.5 L 0.5 0.5 L 0 -0.5 Z";
    }
    if (type === 'triangle-right') {
      // Classic right triangle (half-square)
      return "M -0.5 0.5 L 0.5 0.5 L 0.5 -0.5 Z";
    }
    return "";
  };

  return (
    <div className="w-full max-w-6xl flex flex-col lg:flex-row gap-8 items-start animate-in fade-in duration-500">
      {/* Grid Area */}
      <div className="flex-1 bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 w-full overflow-hidden">
        <div className="flex items-center justify-between mb-6">
          <button 
            onClick={onBack}
            className="flex items-center text-gray-400 hover:text-orange-600 transition-colors font-bold"
          >
            <ArrowLeft className="w-5 h-5 mr-2" />
            Zpět
          </button>
          <div className="text-right">
            <h2 className="text-xl font-black text-gray-800 uppercase tracking-tighter">Geometrická skládačka</h2>
            <div className="text-[10px] font-bold text-orange-500 bg-orange-50 px-3 py-1 rounded-full uppercase tracking-widest inline-block mt-1">
              Volné posouvání
            </div>
          </div>
        </div>

        <div className="bg-orange-50/50 p-4 rounded-3xl mb-6 border border-orange-100 flex items-center justify-between">
          <div className="flex items-center">
            <HelpCircle className="w-4 h-4 mr-2 text-orange-500" />
            <p className="text-sm font-black text-orange-900 uppercase tracking-tight">
              Sestav z připravených dílků různé obrazce.
            </p>
          </div>
          <button 
            onClick={() => setUseGrid(!useGrid)}
            className={`flex items-center px-4 py-2 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all ${
              useGrid ? 'bg-orange-500 text-white shadow-md' : 'bg-white text-gray-400 border border-gray-100'
            }`}
          >
            <Magnet className="w-3 h-3 mr-2" />
            Magnet: {useGrid ? 'ZAP' : 'VYP'}
          </button>
        </div>

        <div className="relative aspect-square w-full border-4 border-gray-100 rounded-[2rem] bg-white overflow-hidden shadow-inner flex items-center justify-center p-6">
          <svg 
            ref={svgRef}
            viewBox="-0.5 -0.5 11 11" 
            className="w-full h-full select-none touch-none"
            preserveAspectRatio="xMidYMid meet"
          >
            <defs>
              <pattern id="freeGrid" width="1" height="1" patternUnits="userSpaceOnUse">
                <rect width="1" height="1" fill="none" stroke="#f1f5f9" strokeWidth="0.05"/>
              </pattern>
            </defs>
            <rect x="0" y="0" width={gridSize} height={gridSize} fill="url(#freeGrid)" pointerEvents="none" />

            {/* Shapes */}
            {shapes.map(shape => (
              <g 
                key={shape.id} 
                transform={`translate(${shape.x + 0.5}, ${gridSize - (shape.y + 0.5)}) rotate(${shape.rotation * 90})`}
                onMouseDown={(e) => handleMouseDown(e, shape.id)}
                className={`cursor-move transition-all ${draggingId === shape.id ? 'opacity-80 scale-[1.02]' : 'hover:opacity-95'}`}
              >
                <path 
                  d={getShapePath(shape.type, shape.rotation)} 
                  fill={shape.color} 
                  stroke={selectedId === shape.id ? "white" : "rgba(0,0,0,0.2)"} 
                  strokeWidth={selectedId === shape.id ? "0.1" : "0.05"}
                  className="drop-shadow-md transition-all"
                />
                {selectedId === shape.id && (
                  <rect x="-0.6" y="-0.6" width="1.2" height="1.2" fill="none" stroke="#3b82f6" strokeWidth="0.05" strokeDasharray="0.1,0.1" pointerEvents="none" className="rotate-[-rotation]" />
                )}
              </g>
            ))}
          </svg>
        </div>

        <div className="mt-4 grid grid-cols-2 gap-4">
          <div className="flex items-center text-gray-400 text-[10px] font-bold uppercase tracking-widest leading-tight">
            <MousePointer2 className="w-4 h-4 mr-2 text-orange-500" />
            Táhni pro přesun
          </div>
          <div className="flex items-center text-gray-400 text-[10px] font-bold uppercase tracking-widest leading-tight">
            <RotateCw className="w-4 h-4 mr-2 text-orange-500" />
            Klikni pro otočení
          </div>
        </div>
      </div>

      {/* Control Panel */}
      <div className="w-full lg:w-80 flex flex-col gap-6">
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100">
          <h3 className="text-xl font-black text-gray-800 mb-6 flex items-center uppercase tracking-tight">
            <div className="w-3 h-8 bg-orange-600 rounded-full mr-3"></div>
            Sada dílků
          </h3>

          <div className="space-y-3 mb-8">
            {shapes.slice().reverse().map((shape) => (
              <div 
                key={shape.id}
                onClick={() => setSelectedId(shape.id)}
                className={`flex items-center justify-between p-4 rounded-3xl border-2 transition-all cursor-pointer ${
                  selectedId === shape.id ? 'border-orange-500 bg-orange-50 shadow-sm' : 'border-gray-50 hover:border-gray-200'
                }`}
              >
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-lg shadow-sm border border-black/5" style={{ backgroundColor: shape.color }}></div>
                  <span className="text-[10px] font-black uppercase tracking-tight text-gray-700">{shape.label}</span>
                </div>
                <button 
                  onClick={(e) => { e.stopPropagation(); rotateShape(shape.id); }}
                  className="p-2 bg-white rounded-xl shadow-sm border border-gray-100 hover:text-orange-600 transition-colors"
                >
                  <RotateCw className="w-3 h-3" />
                </button>
              </div>
            ))}
          </div>

          <div className="bg-gray-50 p-6 rounded-[2rem] border-2 border-gray-100">
             <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center">
               <LayoutGrid className="w-4 h-4 mr-2" />
               Úkoly z učebnice
             </h4>
             <ul className="space-y-3">
               {[
                 "Obdélník (2 čtverce)",
                 "Rovnoběžník",
                 "Větší čtverec",
                 "Lichoběžník"
               ].map((task, i) => (
                 <li key={i} className="flex items-center gap-2 text-[10px] font-bold text-gray-600 uppercase tracking-tight leading-tight">
                   <div className="w-5 h-5 rounded-lg bg-white border border-gray-200 flex items-center justify-center text-[10px] text-orange-500 font-black shrink-0">
                     {i+1}
                   </div>
                   {task}
                 </li>
               ))}
             </ul>
          </div>
        </div>

        <button 
          onClick={resetAll}
          className="w-full py-5 flex items-center justify-center bg-white hover:bg-orange-50 text-orange-600 font-black rounded-[2.5rem] transition-all shadow-sm border-2 border-orange-50 hover:border-orange-200 uppercase text-xs tracking-widest"
        >
          <RefreshCcw className="w-4 h-4 mr-2" />
          Vrátit dílky na start
        </button>

        <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 p-6 rounded-[2.5rem] shadow-xl text-white">
           <div className="flex items-start gap-4">
             <div className="bg-white/20 p-2 rounded-xl">
               <CheckCircle className="w-6 h-6 text-white" />
             </div>
             <div>
               <p className="text-[10px] font-black uppercase tracking-widest opacity-80 mb-1">
                 Tip pro žáky
               </p>
               <p className="text-xs font-bold leading-relaxed">
                 Dílky se dají libovolně otáčet. Dva stejné trojúhelníky k sobě přiložené přeponou vytvoří čtverec!
               </p>
             </div>
           </div>
        </div>
      </div>
    </div>
  );
};

