import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ArrowLeft, RefreshCcw, MousePointer2, LayoutGrid, RotateCw, CheckCircle, HelpCircle, Magnet } from 'lucide-react';

type ShapeType = 'square' | 'triangle-roof';

interface PlacedShape {
  id: string;
  type: ShapeType;
  x: number;
  y: number;
  rotation: number; // 0, 1, 2, 3 (90 degree steps)
  color: string;
  label: string;
}

const INITIAL_SHAPES: PlacedShape[] = [
  { id: 'sq-1', type: 'square', x: 2, y: 3.5, rotation: 0, color: '#5D9CEC', label: 'Modrý čtverec' },
  { id: 'sq-2', type: 'square', x: 4, y: 3.5, rotation: 0, color: '#FFCE54', label: 'Žlutý čtverec' },
  { id: 'tr-roof-1', type: 'triangle-roof', x: 6, y: 3.5, rotation: 0, color: '#FC6E51', label: 'Červená střecha' },
  { id: 'tr-roof-2', type: 'triangle-roof', x: 8, y: 3.5, rotation: 0, color: '#A0D468', label: 'Zelená střecha' },
];

interface ShapePuzzleProps {
  onBack: () => void;
}

const ShapePuzzle: React.FC<ShapePuzzleProps> = ({ onBack }) => {
  const [shapes, setShapes] = useState<PlacedShape[]>(INITIAL_SHAPES);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [useGrid, setUseGrid] = useState(false);

  const svgRef = useRef<SVGSVGElement>(null);
  const gridSize = 10;

  // Track dragging state in refs to avoid closure staleness and unnecessary re-renders during high-freq events
  const dragRef = useRef({
    offsetX: 0,
    offsetY: 0,
    hasMoved: false,
    initialX: 0,
    initialY: 0
  });

  const getSVGPoint = useCallback((clientX: number, clientY: number) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    const svg = svgRef.current;
    const pt = svg.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    const transformed = pt.matrixTransform(svg.getScreenCTM()?.inverse());
    return {
      x: transformed.x,
      y: gridSize - transformed.y // Flip Y for mathematical grid
    };
  }, []);

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    e.preventDefault();
    const point = getSVGPoint(e.clientX, e.clientY);
    const shape = shapes.find(s => s.id === id);

    if (shape) {
      setDraggingId(id);
      setSelectedId(id);

      dragRef.current = {
        offsetX: point.x - shape.x,
        offsetY: point.y - shape.y,
        hasMoved: false,
        initialX: e.clientX,
        initialY: e.clientY
      };

      // Move to top of stack
      setShapes(prev => {
        const others = prev.filter(s => s.id !== id);
        return [...others, shape];
      });
    }
  };

  useEffect(() => {
    if (!draggingId) return;

    const handlePointerMove = (e: PointerEvent) => {
      // Check if mouse actually moved significantly to distinguish from click
      if (!dragRef.current.hasMoved) {
        const dist = Math.hypot(e.clientX - dragRef.current.initialX, e.clientY - dragRef.current.initialY);
        if (dist > 3) dragRef.current.hasMoved = true;
      }

      if (dragRef.current.hasMoved) {
        const point = getSVGPoint(e.clientX, e.clientY);
        let newX = point.x - dragRef.current.offsetX;
        let newY = point.y - dragRef.current.offsetY;

        if (useGrid) {
          newX = Math.round(newX * 2) / 2;
          newY = Math.round(newY * 2) / 2;
        }

        setShapes(prev => prev.map(s => 
          s.id === draggingId ? { ...s, x: newX, y: newY } : s
        ));
      }
    };

    const handlePointerUp = () => {
      if (!dragRef.current.hasMoved && draggingId) {
        setShapes(prev => prev.map(s => 
          s.id === draggingId ? { ...s, rotation: (s.rotation + 1) % 4 } : s
        ));
      }
      setDraggingId(null);
    };

    window.addEventListener('pointermove', handlePointerMove);
    window.addEventListener('pointerup', handlePointerUp);

    return () => {
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('pointerup', handlePointerUp);
    };
  }, [draggingId, getSVGPoint, useGrid]);

  const rotateShape = (id: string) => {
    setShapes(prev => prev.map(s => 
      s.id === id ? { ...s, rotation: (s.rotation + 1) % 4 } : s
    ));
  };

  const resetAll = () => {
    setShapes(INITIAL_SHAPES);
    setSelectedId(null);
    setDraggingId(null);
  };

  const getShapePath = (type: ShapeType) => {
    if (type === 'square') {
      return "M -0.5 -0.5 H 0.5 V 0.5 H -0.5 Z";
    }
    if (type === 'triangle-roof') {
      // Isosceles triangle "roof"
      // Basic orientation (0 deg): Tip at top, base at bottom
      return "M -0.5 0.5 L 0.5 0.5 L 0 -0.5 Z";
    }
    return "";
  };

  return (
    <div className="w-full max-w-6xl flex flex-col lg:flex-row gap-8 items-start animate-in fade-in duration-500">
      {/* Workspace Area */}
      <div className="flex-1 bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 w-full overflow-hidden">
        <div className="flex items-center justify-between mb-6">
          <button 
            onClick={onBack}
            className="flex items-center text-gray-400 hover:text-orange-600 transition-colors font-bold"
          >
            <ArrowLeft className="w-5 h-5 mr-2" />
            Zpět
          </button>
          <div className="text-right">
            <h2 className="text-xl font-black text-gray-800 uppercase tracking-tighter leading-none">Geometrická laboratoř</h2>
            <div className="text-[10px] font-bold text-orange-500 bg-orange-50 px-3 py-1 rounded-full uppercase tracking-widest inline-block mt-2">
              Plynulé skládání
            </div>
          </div>
        </div>

        <div className="bg-orange-50/50 p-4 rounded-3xl mb-6 border border-orange-100 flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="flex items-center">
            <HelpCircle className="w-5 h-5 mr-3 text-orange-500 shrink-0" />
            <p className="text-sm font-black text-orange-900 uppercase tracking-tight leading-tight">
              Táhni dílek pro přesun • Klikni pro otočení
            </p>
          </div>
          <button 
            onClick={() => setUseGrid(!useGrid)}
            className={`flex items-center px-5 py-2.5 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all ${
              useGrid ? 'bg-orange-500 text-white shadow-lg' : 'bg-white text-gray-400 border border-gray-200'
            }`}
          >
            <Magnet className="w-3.5 h-3.5 mr-2" />
            Magnet: {useGrid ? 'ZAP' : 'VYP'}
          </button>
        </div>

        <div className="relative aspect-square w-full border-4 border-gray-100 rounded-[2.5rem] bg-white overflow-hidden shadow-inner flex items-center justify-center p-6">
          <svg 
            ref={svgRef}
            viewBox="-0.5 -0.5 11 11" 
            className="w-full h-full select-none touch-none overflow-visible"
            preserveAspectRatio="xMidYMid meet"
          >
            <defs>
              <pattern id="puzzleGrid" width="1" height="1" patternUnits="userSpaceOnUse">
                <rect width="1" height="1" fill="none" stroke="#f1f5f9" strokeWidth="0.05"/>
              </pattern>
              <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation="0.1" result="blur" />
                <feComposite in="SourceGraphic" in2="blur" operator="over" />
              </filter>
            </defs>
            <rect x="0" y="0" width={gridSize} height={gridSize} fill="url(#puzzleGrid)" pointerEvents="none" />

            {/* Render objects */}
            {shapes.map(shape => (
              <g 
                key={shape.id} 
                transform={`translate(${shape.x}, ${gridSize - shape.y}) rotate(${shape.rotation * 90})`}
                onPointerDown={(e) => handlePointerDown(e, shape.id)}
                className={`cursor-grab active:cursor-grabbing transition-all ${draggingId === shape.id ? 'opacity-80 scale-105' : 'hover:opacity-95'}`}
              >
                <path 
                  d={getShapePath(shape.type)} 
