import React, { useState, useRef, useCallback } from 'react';
import { ArrowLeft, RefreshCcw, MousePointer2, LayoutGrid, RotateCw, CheckCircle, HelpCircle, Magnet } from 'lucide-react';

type ShapeType = 'square' | 'triangle-roof';

interface PlacedShape {
  id: string;
  type: ShapeType;
  x: number;
  y: number;
  rotation: number; // 0, 1, 2, 3 (kroky po 90 stupních)
  color: string;
  label: string;
}

const INITIAL_SHAPES: PlacedShape[] = [
  { id: 'sq-1', type: 'square', x: 2, y: 4, rotation: 0, color: '#5D9CEC', label: 'Modrý čtverec' },
  { id: 'sq-2', type: 'square', x: 4, y: 4, rotation: 0, color: '#FFCE54', label: 'Žlutý čtverec' },
  { id: 'tr-roof-1', type: 'triangle-roof', x: 6, y: 4, rotation: 0, color: '#FC6E51', label: 'Červená střecha' },
  { id: 'tr-roof-2', type: 'triangle-roof', x: 8, y: 4, rotation: 0, color: '#A0D468', label: 'Zelená střecha' },
];

interface ShapePuzzleProps {
  onBack: () => void;
}

const ShapePuzzle: React.FC<ShapePuzzleProps> = ({ onBack }) => {
  const [shapes, setShapes] = useState<PlacedShape[]>(INITIAL_SHAPES);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [useGrid, setUseGrid] = useState(false);

  const svgRef = useRef<SVGSVGElement>(null);
  const gridSize = 10;

  // Stav pro manipulaci uchovávaný v refu pro okamžitou odezvu bez lagů
  const dragInfo = useRef({
    offsetX: 0,
    offsetY: 0,
    initialX: 0,
    initialY: 0,
    hasMoved: false,
    isDragging: false
  });

  const getSVGPoint = useCallback((clientX: number, clientY: number) => {
    if (!svgRef.current) return { x: 0, y: 0 };
    const svg = svgRef.current;
    const pt = svg.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    const transformed = pt.matrixTransform(svg.getScreenCTM()?.inverse());
    return {
      x: transformed.x,
      y: gridSize - transformed.y // Převod na matematické souřadnice (0 dole)
    };
  }, []);

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    const target = e.currentTarget as HTMLElement;
    target.setPointerCapture(e.pointerId);

    const point = getSVGPoint(e.clientX, e.clientY);
    const shape = shapes.find(s => s.id === id);

    if (shape) {
      dragInfo.current = {
        offsetX: point.x - shape.x,
        offsetY: point.y - shape.y,
        initialX: e.clientX,
        initialY: e.clientY,
        hasMoved: false,
        isDragging: true
      };

      setDraggingId(id);
      setSelectedId(id);

      // Změna pořadí (z-index) - aktuální dílek jde nahoru
      setShapes(prev => {
        const others = prev.filter(s => s.id !== id);
        return [...others, shape];
      });
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!draggingId || !dragInfo.current.isDragging) return;

    // Detekce, zda jde o tah nebo jen kliknutí
    if (!dragInfo.current.hasMoved) {
      const dist = Math.hypot(e.clientX - dragInfo.current.initialX, e.clientY - dragInfo.current.initialY);
      if (dist > 5) {
        dragInfo.current.hasMoved = true;
      }
    }

    if (dragInfo.current.hasMoved) {
      const point = getSVGPoint(e.clientX, e.clientY);
      let newX = point.x - dragInfo.current.offsetX;
      let newY = point.y - dragInfo.current.offsetY;

      // Magnetické přichytávání k mřížce (krok 0.5)
      if (useGrid) {
        newX = Math.round(newX * 2) / 2;
        newY = Math.round(newY * 2) / 2;
      }

      setShapes(prev => prev.map(s => 
        s.id === draggingId ? { ...s, x: newX, y: newY } : s
      ));
    }
  };

  const handlePointerUp = (e: React.PointerEvent, id: string) => {
    const target = e.currentTarget as HTMLElement;
    target.releasePointerCapture(e.pointerId);

    // Pokud se s dílkem nepohnulo, rotujeme ho
    if (!dragInfo.current.hasMoved && draggingId === id) {
      setShapes(prev => prev.map(s => 
        s.id === id ? { ...s, rotation: (s.rotation + 1) % 4 } : s
      ));
    }

    setDraggingId(null);
    dragInfo.current.isDragging = false;
  };

  const resetAll = () => {
    setShapes(INITIAL_SHAPES);
    setSelectedId(null);
    setDraggingId(null);
  };

  const getShapePath = (type: ShapeType) => {
    if (type === 'square') {
      return "M -0.5 -0.5 H 0.5 V 0.5 H -0.5 Z";
    }
    if (type === 'triangle-roof') {
      return "M -0.5 0.5 L 0.5 0.5 L 0 -0.5 Z";
    }
    return "";
  };

  return (
    <div className="w-full max-w-6xl flex flex-col lg:flex-row gap-8 items-start animate-in fade-in duration-500">
      {/* Hlavní pracovní plocha */}
      <div className="flex-1 bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 w-full overflow-hidden">
        <div className="flex items-center justify-between mb-6">
          <button 
            onClick={onBack}
            className="flex items-center text-gray-400 hover:text-orange-600 transition-colors font-bold"
          >
            <ArrowLeft className="w-5 h-5 mr-2" />
            Zpět
          </button>
          <div className="text-right">
            <h2 className="text-xl font-black text-gray-800 uppercase tracking-tighter">Geometrická laboratoř</h2>
            <div className="text-[10px] font-bold text-orange-500 bg-orange-50 px-3 py-1 rounded-full uppercase tracking-widest inline-block mt-2">
              Interaktivní skládání
            </div>
          </div>
        </div>

        <div className="bg-orange-50/50 p-4 rounded-3xl mb-6 border border-orange-100 flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="flex items-center">
            <HelpCircle className="w-5 h-5 mr-3 text-orange-500 shrink-0" />
            <p className="text-sm font-black text-orange-900 uppercase tracking-tight leading-tight">
              Drž dílek a táhni • Kliknutím ho otočíš
            </p>
          </div>
          <button 
            onClick={() => setUseGrid(!useGrid)}
            className={`flex items-center px-5 py-2.5 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all ${
              useGrid ? 'bg-orange-500 text-white shadow-lg' : 'bg-white text-gray-400 border border-gray-200'
            }`}
          >
            <Magnet className="w-3.5 h-3.5 mr-2" />
            Magnet: {useGrid ? 'ZAP' : 'VYP'}
          </button>
        </div>

        <div className="relative aspect-square w-full border-4 border-gray-100 rounded-[2.5rem] bg-white overflow-hidden shadow-inner flex items-center justify-center p-6 touch-none">
          <svg 
            ref={svgRef}
            viewBox="-0.5 -0.5 11 11" 
            className="w-full h-full select-none touch-none overflow-visible"
            preserveAspectRatio="xMidYMid meet"
          >
            <defs>
              <pattern id="puzzleGrid" width="1" height="1" patternUnits="userSpaceOnUse">
                <rect width="1" height="1" fill="none" stroke="#f1f5f9" strokeWidth="0.05"/>
              </pattern>
            </defs>
            <rect x="0" y="0" width={gridSize} height={gridSize} fill="url(#puzzleGrid)" pointerEvents="none" />

            {shapes.map(shape => (
              <g 
                key={shape.id} 
                transform={`translate(${shape.x}, ${gridSize - shape.y}) rotate(${shape.rotation * 90})`}
                onPointerDown={(e) => handlePointerDown(e, shape.id)}
                onPointerMove={handlePointerMove}
                onPointerUp={(e) => handlePointerUp(e, shape.id)}
                className={`cursor-grab active:cursor-grabbing transition-transform duration-75 ${draggingId === shape.id ? 'scale-110 opacity-80' : 'hover:scale-105'}`}
                style={{ touchAction: 'none' }}
              >
                <path 
                  d={getShapePath(shape.type)} 
                  fill={shape.color} 
                  stroke={selectedId === shape.id ? "white" : "rgba(0,0,0,0.15)"} 
                  strokeWidth={selectedId === shape.id ? "0.1" : "0.04"}
                  className="drop-shadow-sm pointer-events-auto"
                />
              </g>
            ))}
          </svg>
        </div>

        <div className="mt-5 grid grid-cols-2 gap-4">
          <div className="flex items-center text-gray-400 text-[10px] font-black uppercase tracking-widest">
            <MousePointer2 className="w-4 h-4 mr-2 text-orange-500" />
            Plynulý pohyb po ploše
          </div>
          <div className="flex items-center text-gray-400 text-[10px] font-black uppercase tracking-widest">
            <RotateCw className="w-4 h-4 mr-2 text-orange-500" />
            Rotace o 90° při kliknutí
          </div>
        </div>
      </div>

      {/* Boční panel s úkoly */}
      <div className="w-full lg:w-96 flex flex-col gap-6 h-full">
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100 flex flex-col gap-8 flex-1">
          <div className="bg-orange-50/50 p-8 rounded-[2.5rem] border-2 border-orange-100 flex-1">
             <h3 className="text-xl font-black text-orange-800 uppercase tracking-tight mb-8 flex items-center">
               <LayoutGrid className="w-7 h-7 mr-3 text-orange-600" />
               Úkoly k procvičení
             </h3>
             <ul className="space-y-6">
               {[
                 "Sestav dům (čtverec + střecha)",
                 "Vytvoř dlouhý obdélník",
                 "Sestav rovnoběžník",
                 "Vytvoř vysokou věž"
               ].map((task, i) => (
                 <li key={i} className="flex items-center gap-5 text-lg font-black text-gray-700 uppercase tracking-tight leading-snug group">
                   <div className="w-10 h-10 rounded-2xl bg-white border-2 border-orange-200 flex items-center justify-center text-sm text-orange-500 font-black shrink-0 shadow-sm group-hover:bg-orange-500 group-hover:text-white group-hover:border-orange-500 transition-all">
                     {i+1}
                   </div>
                   {task}
                 </li>
               ))}
             </ul>
          </div>

          <button 
            onClick={resetAll}
            className="w-full py-6 flex items-center justify-center bg-white hover:bg-orange-50 text-orange-600 font-black rounded-[2.5rem] transition-all shadow-md border-2 border-orange-100 uppercase text-sm tracking-widest"
          >
            <RefreshCcw className="w-5 h-5 mr-3" />
            Vrátit vše na start
          </button>
        </div>
      </div>
    </div>
  );
};

