        s.id === draggingId ? { ...s, rotation: (s.rotation + 1) % 4 } : s
      ));
    }

    // Uvolnění capture a ukončení tahu
    if (svgRef.current) {
      svgRef.current.releasePointerCapture(e.pointerId);
    }
    setDraggingId(null);
