            FIXNÍ MŘÍŽKA
          </div>
        </div>

        <div className="relative aspect-square w-full border-4 border-gray-100 rounded-[2.5rem] bg-white overflow-hidden shadow-inner flex items-center justify-center p-6 touch-none">
