            Původní rozlišení: {level.sourceSize}x{level.sourceSize} px
          </div>
        </div>
        <div className="flex items-center gap-2">
           <span className="text-xs font-black text-gray-400 uppercase tracking-widest">{currentLevelIdx + 1} / {LEVELS.length}</span>
           <div className="w-20 h-2 bg-emerald-50 rounded-full overflow-hidden">
             <div 
               className="h-full bg-emerald-500 transition-all duration-500"
               style={{ width: `${((currentLevelIdx + 1) / LEVELS.length) * 100}%` }}
             ></div>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 w-full">
        {/* Source Grid */}
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100 flex flex-col items-center">
          <h3 className="text-lg font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
