interface CompressionGameProps {
  onBack: () => void;
}

const CompressionGame: React.FC<CompressionGameProps> = ({ onBack }) => {
  const [currentLevelIdx, setCurrentLevelIdx] = useState(0);
  const [userGrid, setUserGrid] = useState<Grid>([]);
  const [isFinished, setIsFinished] = useState(false);
  const [showWin, setShowWin] = useState(false);

  const level = LEVELS[currentLevelIdx];
  const compressedSize = level.sourceSize / 2;

  useEffect(() => {
    // Reset user grid for new level
    const emptyGrid = Array(compressedSize).fill(0).map(() => Array(compressedSize).fill(0));
    setUserGrid(emptyGrid);
    setIsFinished(false);
  }, [currentLevelIdx, compressedSize]);

  const targetGrid = useMemo(() => {
    const target: Grid = Array(compressedSize).fill(0).map(() => Array(compressedSize).fill(0));
    for (let r = 0; r < compressedSize; r++) {
      // Fix: Change idx++ to c++ to correctly iterate through columns
      for (let c = 0; c < compressedSize; c++) {
        let blackCount = 0;
        // Check 2x2 block
        for (let dr = 0; dr < 2; dr++) {
          for (let dc = 0; dc < 2; dc++) {
            if (level.sourceData[r * 2 + dr][c * 2 + dc] === 1) blackCount++;
          }
        }
        // RULE: 2 or more black pixels = black block
        target[r][c] = blackCount >= 2 ? 1 : 0;
      }
    }
    return target;
  }, [level, compressedSize]);

  const handleCellClick = (r: number, c: number) => {
    if (isFinished) return;
    const newGrid = userGrid.map((row, ri) => 
      row.map((cell, ci) => ri === r && ci === c ? (cell === 0 ? 1 : 0) : cell)
    );
    setUserGrid(newGrid);
  };

  const checkAnswer = () => {
    let correct = true;
    for (let r = 0; r < compressedSize; r++) {
      for (let c = 0; c < compressedSize; c++) {
        if (userGrid[r][c] !== targetGrid[r][c]) {
          correct = false;
          break;
        }
      }
    }

    if (correct) {
      if (currentLevelIdx < LEVELS.length - 1) {
        setIsFinished(true);
      } else {
        setShowWin(true);
      }
    } else {
      // Shaky effect or feedback
    }
  };

  const nextLevel = () => {
    setCurrentLevelIdx(prev => prev + 1);
  };

  return (
    <div className="w-full max-w-6xl flex flex-col gap-8 items-center animate-in fade-in duration-500 pb-20">
      {/* Header */}
      <div className="w-full flex items-center justify-between bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100">
        <button 
          onClick={onBack}
          className="flex items-center text-gray-400 hover:text-emerald-600 transition-colors font-bold uppercase text-xs tracking-widest"
        >
          <ArrowLeft className="w-5 h-5 mr-2" />
          Zpět
        </button>
        <div className="text-center">
          <h2 className="text-xl font-black text-gray-800 uppercase tracking-tighter">{level.name}</h2>
          <div className="text-[10px] font-bold text-emerald-500 bg-emerald-50 px-3 py-1 rounded-full uppercase tracking-widest inline-block mt-2">
            Původní rozlišení: {level.sourceSize}x{level.sourceSize} px
          </div>
        </div>
        <div className="flex items-center gap-2">
           <span className="text-xs font-black text-gray-400 uppercase tracking-widest">{currentLevelIdx + 1} / {LEVELS.length}</span>
           <div className="w-20 h-2 bg-emerald-50 rounded-full overflow-hidden">
             <div 
               className="h-full bg-emerald-500 transition-all duration-500"
               style={{ width: `${((currentLevelIdx + 1) / LEVELS.length) * 100}%` }}
             ></div>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 w-full">
        {/* Source Grid */}
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100 flex flex-col items-center">
          <h3 className="text-lg font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
             <div className="w-3 h-6 bg-emerald-500 rounded-full"></div>
             Původní obrázek
          </h3>
          <div 
            className="grid gap-px bg-gray-200 border-2 border-gray-200 rounded-2xl overflow-hidden shadow-inner"
            style={{ 
              gridTemplateColumns: `repeat(${level.sourceSize}, 1fr)`,
              width: '100%',
              maxWidth: '400px',
              aspectRatio: '1/1'
            }}
          >
            {level.sourceData.map((row, r) => (
              row.map((cell, c) => (
                <div 
                  key={`${r}-${c}`}
                  className={`w-full h-full ${cell === 1 ? 'bg-gray-800' : 'bg-white'}`}
                ></div>
              ))
            ))}
          </div>
          <div className="mt-8 p-4 bg-emerald-50/50 rounded-2xl border border-emerald-100 flex items-start gap-3">
            <HelpCircle className="w-5 h-5 text-emerald-600 shrink-0 mt-0.5" />
            <p className="text-xs text-emerald-900 font-bold leading-relaxed">
              Pravidlo: Spojujeme 2x2 pixely do jednoho velkého. Pokud jsou aspoň 2 pixely černé, výsledek je černý.
            </p>
          </div>
        </div>

        {/* Compressed Grid */}
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-emerald-100 ring-4 ring-emerald-50 flex flex-col items-center">
          <h3 className="text-lg font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
             <div className="w-3 h-6 bg-emerald-500 rounded-full"></div>
             Komprimovaný obrázek
          </h3>
          <div 
            className="grid gap-1 bg-emerald-100 border-4 border-emerald-100 rounded-3xl overflow-hidden shadow-lg"
            style={{ 
              gridTemplateColumns: `repeat(${compressedSize}, 1fr)`,
              width: '100%',
              maxWidth: '400px',
              aspectRatio: '1/1'
            }}
          >
            {userGrid.map((row, r) => (
              row.map((cell, c) => (
                <button 
                  key={`comp-${r}-${c}`}
                  onClick={() => handleCellClick(r, c)}
                  className={`w-full h-full transition-colors duration-200 ${cell === 1 ? 'bg-gray-800' : 'bg-white hover:bg-emerald-50'}`}
                ></button>
              ))
            ))}
          </div>

          <div className="mt-10 w-full flex flex-col gap-4">
             {isFinished ? (
               <button 
                 onClick={nextLevel}
                 className="w-full py-6 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-3xl shadow-xl shadow-emerald-200 transition-all flex items-center justify-center gap-3 uppercase tracking-widest"
               >
                 Pokračovat na další <ChevronRight className="w-5 h-5" />
               </button>
             ) : (
               <button 
                 onClick={checkAnswer}
                 className="w-full py-6 bg-gray-900 hover:bg-black text-white font-black rounded-3xl shadow-xl transition-all flex items-center justify-center gap-3 uppercase tracking-widest"
               >
                 <Minimize2 className="w-5 h-5" />
                 Zkontrolovat kompresi
               </button>
             )}

             <button 
                onClick={() => setUserGrid(userGrid.map(row => row.map(() => 0)))}
                className="w-full py-3 text-gray-400 font-black uppercase text-[10px] tracking-widest hover:text-emerald-600 transition-colors flex items-center justify-center gap-2"
             >
                <RefreshCcw className="w-3 h-3" /> Smazat pokus
             </button>
          </div>
        </div>
      </div>

      {showWin && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-md flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-[3rem] p-12 max-w-sm w-full text-center shadow-2xl animate-in zoom-in duration-500">
