            </div>
            <h2 className="text-4xl font-black text-gray-800 mb-3 uppercase tracking-tighter">Mistr komprese!</h2>
            <p className="text-gray-500 mb-10 leading-relaxed font-medium">
              Úspěšně jsi zkomprimoval všech 5 obrázků podle pravidel rastrové grafiky.
            </p>
            <button 
              onClick={onBack}
              className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl shadow-emerald-200 transition-all active:scale-95 uppercase tracking-widest text-sm"
            >
              Zpět do menu
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default CompressionGame;

