import SplashScreen from './components/SplashScreen';
import Menu from './components/Menu';
import RGBDrawing from './components/RGBDrawing';
import Quiz from './components/Quiz';
import LinesMenu from './components/LinesMenu';
import VectorDrawing from './components/VectorDrawing';
import ShapePuzzle from './components/ShapePuzzle';
import CompressionMenu from './components/CompressionMenu';
import CompressionGame from './components/CompressionGame';
import TextCompression from './components/TextCompression';
import { Screen, Difficulty, Segment } from './types';
import { ROCKET_DATA, CAT_DATA, COMPUTER_DATA } from './constants';

const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<Screen>('landing');
  const [selectedData, setSelectedData] = useState<Segment[]>([]);
  const [levelName, setLevelName] = useState<string>('');

  const handleStartLevel = (difficulty: Difficulty) => {
    switch (difficulty) {
      case 'easy':
        setSelectedData(ROCKET_DATA);
        setLevelName('Raketa');
        break;
      case 'medium':
        setSelectedData(CAT_DATA);
        setLevelName('Kočka');
        break;
      case 'hard':
        setSelectedData(COMPUTER_DATA);
        setLevelName('Počítač');
        break;
    }
    setCurrentScreen('drawing');
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case 'landing':
        return (
          <LandingPage 
            onStartColors={() => setCurrentScreen('splash')} 
            onStartLines={() => setCurrentScreen('lines-menu')} 
            onStartCompression={() => setCurrentScreen('compression-menu')}
          />
        );
      case 'compression-menu':
        return (
          <CompressionMenu 
            onStartGame={() => setCurrentScreen('compression-game')}
            onStartText={() => setCurrentScreen('text-compression')}
            onBack={() => setCurrentScreen('landing')}
          />
        );
      case 'compression-game':
        return (
          <CompressionGame onBack={() => setCurrentScreen('compression-menu')} />
        );
      case 'text-compression':
        return (
          <TextCompression onBack={() => setCurrentScreen('compression-menu')} />
        );
      case 'lines-menu':
        return (
          <LinesMenu 
            onShapePuzzle={() => setCurrentScreen('shape-puzzle')}
            onVectorDrawing={() => setCurrentScreen('vector-drawing')}
            onLineDrawing={() => setCurrentScreen('line-drawing')}
            onBack={() => setCurrentScreen('landing')}
          />
        );
      case 'shape-puzzle':
        return (
          <ShapePuzzle onBack={() => setCurrentScreen('lines-menu')} />
        );
      case 'vector-drawing':
        return (
          <VectorDrawing 
            mode="points"
            onBack={() => setCurrentScreen('lines-menu')}
          />
        );
      case 'line-drawing':
        return (
          <VectorDrawing 
            mode="lines"
            onBack={() => setCurrentScreen('lines-menu')}
          />
        );
      case 'splash':
        return (
          <SplashScreen 
            onEnter={() => setCurrentScreen('menu')} 
            onQuiz={() => setCurrentScreen('quiz')}
            onBack={() => setCurrentScreen('landing')}
          />
        );
      case 'menu':
        return <Menu onStart={handleStartLevel} onBack={() => setCurrentScreen('splash')} />;
      case 'drawing':
        return (
          <RGBDrawing 
            onBack={() => setCurrentScreen('menu')} 
            initialSegments={selectedData}
            title={levelName}
          />
        );
      case 'quiz':
        return <Quiz onBack={() => setCurrentScreen('splash')} />;
      default:
        return <LandingPage onStartColors={() => setCurrentScreen('splash')} onStartLines={() => setCurrentScreen('lines-menu')} onStartCompression={() => setCurrentScreen('compression-menu')} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-[#f8fafc]">
      {renderScreen()}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { ArrowLeft, RefreshCcw, HelpCircle, FileText, Zap, Sparkles, Hash } from 'lucide-react';

interface TextLevel {
  id: number;
  title: string;
  lines: string[];
}

const LEVELS: TextLevel[] = [
  {
    id: 1,
    title: "Prší, prší",
    lines: [
      "PRŠÍ, PRŠÍ, JEN SE LEJE.",
      "KAM KONÍČKY POJEDEME?",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ.",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ."
    ]
  },
  {
    id: 2,
    title: "Kukačka",
    lines: [
      "KUKAČKA UŽ ZAKUKALA,",
      "MÁ PANENKA ZAPLAKALA.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ."
    ]
  }
];

const TextCompression: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [levelIdx, setLevelIdx] = useState(0);
  const [dictionary, setDictionary] = useState<{ [word: string]: number }>({});

  const currentLevel = LEVELS[levelIdx];

  // Normalizace textu pro analýzu
  const processedLines = useMemo(() => {
    return currentLevel.lines.map(line => {
      // Rozdělení na slova a interpunkci, abychom mohli slova klikat
      return line.split(/(\s+|,|\.|\?)/).filter(Boolean);
    });
  }, [currentLevel]);

  const handleWordClick = (word: string) => {
    const cleanWord = word.trim().replace(/[,.?]/g, '').toUpperCase();
    if (!cleanWord || cleanWord.length < 2) return;

    if (dictionary[cleanWord]) {
      // Odstranit ze slovníku
      const newDict = { ...dictionary };
      delete newDict[cleanWord];
      setDictionary(newDict);
    } else {
      // Přidat do slovníku
      const nextId = Object.keys(dictionary).length + 1;
      setDictionary({ ...dictionary, [cleanWord]: nextId });
    }
  };

  const calculateStats = () => {
    let originalChars = currentLevel.lines.join('\n').length;
    let compressedChars = 0;

    currentLevel.lines.forEach(line => {
      let tempLine = line.toUpperCase();
      Object.entries(dictionary).forEach(([word, id]) => {
        const regex = new RegExp(`\\b${word}\\b`, 'g');
        tempLine = tempLine.replace(regex, `#${id}`);
      });
      compressedChars += tempLine.length;
    });

    // Připočteme velikost "slovníku" (předpoklad: slovo + oddělovač + kód)
    const dictionarySize = Object.entries(dictionary).reduce((acc, [word, id]) => acc + word.length + 3, 0);
    const totalCompressed = compressedChars + dictionarySize;

    return {
      original: originalChars,
      compressed: totalCompressed,
      savings: Math.max(0, originalChars - totalCompressed)
    };
  };

  const stats = calculateStats();

  return (
    <div className="w-full max-w-6xl flex flex-col gap-8 items-center animate-in fade-in duration-500 pb-20">
      {/* Header */}
      <div className="w-full bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col md:flex-row items-center justify-between gap-6">
        <button 
          onClick={onBack}
          className="flex items-center text-gray-400 hover:text-blue-600 transition-colors font-black uppercase text-xs tracking-widest shrink-0"
        >
          <ArrowLeft className="w-5 h-5 mr-2" />
          Zpět
        </button>

        <div className="flex gap-4">
          {LEVELS.map((l, idx) => (
            <button
              key={l.id}
              onClick={() => { setLevelIdx(idx); setDictionary({}); }}
              className={`px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
                levelIdx === idx 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' 
                  : 'bg-blue-50 text-blue-600 hover:bg-blue-100'
              }`}
            >
              {l.title}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-4 bg-blue-50 px-5 py-3 rounded-2xl border border-blue-100">
          <Zap className="w-5 h-5 text-blue-600" />
          <div className="text-left">
            <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Ušetřená energie</p>
            <p className="text-lg font-black text-blue-900 tracking-tighter leading-none">{stats.savings} znaků</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 w-full items-start">
        {/* Editor Area */}
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100 flex flex-col items-center min-h-[500px]">
          <div className="w-full flex justify-between items-center mb-8">
            <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight flex items-center gap-3">
               <div className="w-3 h-8 bg-blue-500 rounded-full"></div>
               Zápis písně
            </h3>
            <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Klikni na slovo k zakódování</span>
          </div>

          <div className="w-full space-y-4 font-mono text-lg sm:text-xl">
            {processedLines.map((parts, lineIdx) => (
              <div key={lineIdx} className="flex flex-wrap items-center bg-gray-50/50 p-4 rounded-2xl border border-transparent hover:border-blue-100 transition-colors">
                {parts.map((part, partIdx) => {
                  const cleanPart = part.trim().replace(/[,.?]/g, '').toUpperCase();
                  const isCoded = dictionary[cleanPart];

                  if (/^\s+$/.test(part)) return <span key={partIdx} className="w-2"></span>;
                  if ([, '.', '?', ','].includes(part)) return <span key={partIdx} className="text-gray-400">{part}</span>;

                  return (
                    <button
                      key={partIdx}
                      onClick={() => handleWordClick(part)}
                      className={`px-1.5 py-0.5 rounded-lg transition-all duration-200 font-black relative group ${
                        isCoded 
                          ? 'bg-blue-600 text-white shadow-md scale-105' 
                          : 'hover:bg-blue-100 hover:text-blue-700'
                      }`}
                    >
                      {isCoded ? `#${dictionary[cleanPart]}` : part}
                      {!isCoded && <span className="absolute -top-1 -right-1 opacity-0 group-hover:opacity-100"><Sparkles className="w-3 h-3 text-blue-400" /></span>}
                    </button>
                  );
                })}
              </div>
            ))}
          </div>

          <div className="mt-auto w-full pt-8">
            <div className="p-6 bg-blue-50 rounded-[2rem] border border-blue-100 flex items-start gap-4">
              <HelpCircle className="w-6 h-6 text-blue-600 shrink-0 mt-0.5" />
              <div>
                <p className="text-xs text-blue-900 font-black uppercase tracking-tight mb-1">Úkol pro tebe</p>
                <p className="text-xs text-blue-800 font-medium leading-relaxed">
                  Každé slovo nás stojí energii k zaznamenání. Najdi v textu slova, která se opakují, a klikni na ně. 
                  Uvidíš, jak se nahradí kódem (např. #1) a kolik znaků tím ušetříš!
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* Dictionary and Stats Area */}
        <div className="flex flex-col gap-6">
          {/* Dictionary Table */}
          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-blue-100">
            <h3 className="text-xl font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
               <Hash className="w-6 h-6 text-blue-600" />
               Kódová tabulka (Slovník)
            </h3>

            <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
              {Object.keys(dictionary).length === 0 ? (
                <div className="py-12 text-center text-gray-300 italic font-bold uppercase text-xs tracking-widest border-2 border-dashed border-gray-50 rounded-3xl">
                  Zatím jsi nic nezakódoval
                </div>
              ) : (
                Object.entries(dictionary).map(([word, id]) => (
                  <div key={id} className="flex items-center justify-between p-4 bg-blue-50 border border-blue-100 rounded-2xl animate-in slide-in-from-right duration-300">
                    <div className="flex items-center gap-4">
                      <span className="w-10 h-10 bg-blue-600 text-white font-black rounded-xl flex items-center justify-center shadow-sm">
                        #{id}
                      </span>
                      <span className="font-black text-blue-900 text-lg uppercase tracking-tight">{word}</span>
                    </div>
                    <button 
                      onClick={() => handleWordClick(word)}
                      className="p-2 text-blue-300 hover:text-red-500 transition-colors"
                    >
                      <RefreshCcw className="w-4 h-4" />
                    </button>
                  </div>
                ))
              )}
            </div>
          </div>

          {/* Detailed Stats */}
          <div className="bg-gray-900 p-8 rounded-[3rem] shadow-2xl text-white">
            <h3 className="text-sm font-black text-gray-400 mb-8 uppercase tracking-[0.2em] flex items-center gap-3">
               <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>
               Analýza dat
            </h3>

            <div className="space-y-6">
              <div className="flex justify-between items-center">
                <span className="text-gray-400 font-bold uppercase text-[10px] tracking-widest">Původní velikost</span>
                <span className="text-xl font-black">{stats.original} znaků</span>
              </div>

              <div className="h-px bg-gray-800 w-full"></div>

              <div className="flex justify-between items-center">
                <span className="text-gray-400 font-bold uppercase text-[10px] tracking-widest">Komprimovaná velikost</span>
                <span className="text-xl font-black text-blue-400">{stats.compressed} znaků</span>
              </div>

              <div className="bg-blue-600/10 border border-blue-500/20 p-6 rounded-[2rem] flex flex-col items-center text-center">
                <p className="text-xs font-black text-blue-400 uppercase tracking-widest mb-1">Úspora místa</p>
                <div className="text-4xl font-black text-white tracking-tighter">
                  {stats.original > 0 ? Math.round((stats.savings / stats.original) * 100) : 0}%
                </div>
                <p className="text-[10px] font-bold text-blue-300/50 uppercase tracking-widest mt-2">včetně velikosti slovníku</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f1f5f9;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #3b82f6;
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
};

export default TextCompression;

import React, { useState, useMemo, useEffect } from 'react';
import { ArrowLeft, RefreshCcw, HelpCircle, FileText, Zap, CheckCircle2, Hash, ArrowRight, Play } from 'lucide-react';

interface TextLevel {
  id: number;
  title: string;
  lines: string[];
}

const LEVELS: TextLevel[] = [
  {
    id: 1,
    title: "Prší, prší",
    lines: [
      "PRŠÍ, PRŠÍ, JEN SE LEJE.",
      "KAM KONÍČKY POJEDEME?",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ.",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ."
    ]
  },
  {
    id: 2,
    title: "Kukačka",
    lines: [
      "KUKAČKA UŽ ZAKUKALA,",
      "MÁ PANENKA ZAPLAKALA.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ."
    ]
  }
];

type Phase = 'identification' | 'dictionary' | 'encoding' | 'finished';

const TextCompression: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [levelIdx, setLevelIdx] = useState(0);
  const [phase, setPhase] = useState<Phase>('identification');
  const [selectedIndices, setSelectedIndices] = useState<Set<string>>(new Set());
  const [dictionary, setDictionary] = useState<{ word: string, code: number }[]>([]);
  const [userEncoding, setUserEncoding] = useState<{ [key: string]: 'word' | 'code' }>({});

  const currentLevel = LEVELS[levelIdx];

  // Rozklad textu na slova s jejich souřadnicemi
  const wordsMatrix = useMemo(() => {
    return currentLevel.lines.map((line, lIdx) => {
      const parts = line.split(/(\s+)/);
      let charOffset = 0;
      return parts.map((part, pIdx) => {
        const isWord = /[A-ZČŠŽŘĎŤŇŮÚ]+/.test(part.toUpperCase());
        const cleanWord = part.trim().replace(/[,.?]/g, '').toUpperCase();
        const item = {
          id: `${lIdx}-${pIdx}`,
          text: part,
          cleanWord,
          isWord,
          lineIdx: lIdx,
          wordIdx: pIdx
        };
        return item;
      });
    });
  }, [currentLevel]);

  // Seznam všech slov v textu pro analýzu opakování
  const allWords = useMemo(() => wordsMatrix.flat().filter(w => w.isWord), [wordsMatrix]);

  // Identifikace, která slova se skutečně opakují
  const repeatingWords = useMemo(() => {
    const counts: { [key: string]: number } = {};
    allWords.forEach(w => {
      counts[w.cleanWord] = (counts[w.cleanWord] || 0) + 1;
    });
    return Object.keys(counts).filter(word => counts[word] > 1);
  }, [allWords]);

  // Reset při změně levelu
  useEffect(() => {
    setPhase('identification');
    setSelectedIndices(new Set());
    setDictionary([]);
    setUserEncoding({});
  }, [levelIdx]);

  const handleWordSelection = (id: string, cleanWord: string) => {
    if (phase !== 'identification') return;

    const newSelected = new Set(selectedIndices);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedIndices(newSelected);
  };

  const validateIdentification = () => {
    // Musí být vybrána všechna slova, která se v textu opakují
    const allRepeatingIds = allWords
      .filter(w => repeatingWords.includes(w.cleanWord))
      .map(w => w.id);

    const isComplete = allRepeatingIds.every(id => selectedIndices.has(id)) && 
                       selectedIndices.size === allRepeatingIds.size;

    if (isComplete) {
      // Automaticky vytvořit slovník seřazený podle prvního výskytu v textu
      const foundWordsInOrder: string[] = [];
      allWords.forEach(w => {
        if (repeatingWords.includes(w.cleanWord) && !foundWordsInOrder.includes(w.cleanWord)) {
          foundWordsInOrder.push(w.cleanWord);
        }
      });

      const newDict = foundWordsInOrder.map((word, index) => ({
        word,
        code: index + 1
      }));

      setDictionary(newDict);
      setPhase('encoding');
    } else {
      alert("Některá opakující se slova ti ještě chybí, nebo jsi označil slovo, které se neopakuje!");
    }
  };

  const toggleEncoding = (id: string) => {
    if (phase !== 'encoding') return;
    setUserEncoding(prev => ({
      ...prev,
      [id]: prev[id] === 'code' ? 'word' : 'code'
    }));
  };

  const calculateCompression = () => {
    const originalSize = currentLevel.lines.join('').length;
    let compressedSize = 0;

    // Velikost textu s kódy
    wordsMatrix.flat().forEach(w => {
      if (!w.isWord) {
        compressedSize += w.text.length;
      } else {
        const mode = userEncoding[w.id] || 'word';
        if (mode === 'code' && repeatingWords.includes(w.cleanWord)) {
          const dictItem = dictionary.find(d => d.word === w.cleanWord);
          compressedSize += (dictItem ? `#${dictItem.code}`.length : w.text.length);
        } else {
          compressedSize += w.text.length;
        }
      }
    });

    // Velikost slovníku
    const dictSize = dictionary.reduce((acc, curr) => acc + curr.word.length + 4, 0);
    const totalCompressed = compressedSize + dictSize;

    return {
      original: originalSize,
      compressed: totalCompressed,
      percent: originalSize > 0 ? Math.round(((originalSize - totalCompressed) / originalSize) * 100) : 0
    };
  };

  const stats = calculateCompression();

  const isLevelComplete = phase === 'encoding' && 
    allWords.filter(w => repeatingWords.includes(w.cleanWord)).every(w => userEncoding[w.id] === 'code');

  return (
    <div className="w-full max-w-6xl flex flex-col gap-8 items-center animate-in fade-in duration-500 pb-20">
      {/* Header */}
      <div className="w-full bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col md:flex-row items-center justify-between gap-6">
        <button 
          onClick={onBack}
          className="flex items-center text-gray-400 hover:text-blue-600 transition-colors font-black uppercase text-xs tracking-widest shrink-0"
        >
          <ArrowLeft className="w-5 h-5 mr-2" />
          Zpět
        </button>

        <div className="flex gap-4">
          {LEVELS.map((l, idx) => (
            <button
              key={l.id}
              onClick={() => setLevelIdx(idx)}
              className={`px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
                levelIdx === idx 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' 
                  : 'bg-blue-50 text-blue-600 hover:bg-blue-100'
              }`}
            >
              {l.title}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-4 bg-blue-50 px-5 py-3 rounded-2xl border border-blue-100">
          <Zap className="w-5 h-5 text-blue-600" />
          <div className="text-left">
            <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Fáze úkolu</p>
            <p className="text-lg font-black text-blue-900 tracking-tighter leading-none">
              {phase === 'identification' ? 'Hledání slov' : 'Komprese'}
            </p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 w-full items-start">
        {/* Left Panel: Identification */}
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100 flex flex-col min-h-[550px]">
          <div className="w-full flex justify-between items-center mb-8">
            <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight flex items-center gap-3">
               <div className="w-3 h-8 bg-blue-500 rounded-full"></div>
               {phase === 'identification' ? '1. Najdi opakující se slova' : 'Původní text'}
            </h3>
          </div>

          <div className="w-full space-y-4 font-mono text-lg">
            {wordsMatrix.map((line, lIdx) => (
              <div key={lIdx} className="flex flex-wrap items-center bg-gray-50/50 p-4 rounded-2xl border border-transparent">
                {line.map((w) => {
                  if (!w.isWord) return <span key={w.id} className="whitespace-pre text-gray-300">{w.text}</span>;

                  const isSelected = selectedIndices.has(w.id);
                  const canSelect = phase === 'identification';

                  return (
                    <button
                      key={w.id}
                      onClick={() => handleWordSelection(w.id, w.cleanWord)}
                      disabled={!canSelect}
                      className={`px-1.5 py-0.5 rounded-lg transition-all duration-200 font-black ${
                        isSelected 
                          ? 'bg-blue-600 text-white shadow-md' 
                          : canSelect ? 'hover:bg-blue-100 hover:text-blue-700 text-gray-700' : 'text-gray-400'
                      }`}
                    >
                      {w.text}
                    </button>
                  );
                })}
              </div>
            ))}
          </div>

          {phase === 'identification' && (
            <div className="mt-auto pt-8">
              <button 
                onClick={validateIdentification}
                className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-3xl shadow-xl transition-all flex items-center justify-center gap-3 uppercase tracking-widest"
              >
                Mám označeno vše <ArrowRight className="w-5 h-5" />
              </button>
              <p className="text-center text-[10px] text-gray-400 font-bold uppercase tracking-widest mt-4">
                Tip: Označ každé slovo, které se v textu objeví více než jednou.
              </p>
            </div>
          )}
        </div>

        {/* Right Panel: Encoding / Dictionary */}
        <div className="flex flex-col gap-6">
          {phase === 'identification' ? (
            <div className="bg-gray-900 p-8 rounded-[3rem] shadow-2xl text-white h-full flex flex-col items-center justify-center text-center">
              <HelpCircle className="w-16 h-16 text-blue-500 mb-6 opacity-50" />
              <h4 className="text-xl font-black uppercase mb-2">Metodika komprese</h4>
              <p className="text-gray-400 font-medium leading-relaxed max-w-xs">
                V první fázi musíme najít redundanci (opakování). Klikni na všechna slova vlevo, o kterých si myslíš, že se v písni opakují.
              </p>
            </div>
          ) : (
            <>
              {/* Dictionary Section */}
              <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-blue-100 animate-in slide-in-from-bottom duration-500">
                <h3 className="text-xl font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
                   <Hash className="w-6 h-6 text-blue-600" />
                   Kódová tabulka
                </h3>
                <div className="grid grid-cols-2 gap-3">
                  {dictionary.map((item) => (
                    <div key={item.code} className="flex items-center gap-3 p-3 bg-blue-50 border border-blue-100 rounded-2xl">
                       <span className="w-8 h-8 bg-blue-600 text-white font-black rounded-xl flex items-center justify-center text-xs shadow-sm shrink-0">
                        #{item.code}
                      </span>
                      <span className="font-black text-blue-900 text-sm uppercase tracking-tight truncate">{item.word}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* Encoding Section */}
              <div className="bg-white p-8 rounded-[3rem] shadow-xl border-4 border-emerald-100 ring-8 ring-emerald-50/50 animate-in slide-in-from-right duration-500">
                <div className="w-full flex justify-between items-center mb-6">
                  <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight flex items-center gap-3">
                     <div className="w-3 h-8 bg-emerald-500 rounded-full"></div>
                     2. Sestav kódovaný text
                  </h3>
                </div>

                <div className="w-full space-y-3 font-mono text-sm">
                  {wordsMatrix.map((line, lIdx) => (
                    <div key={lIdx} className="flex flex-wrap items-center bg-emerald-50/30 p-3 rounded-xl border border-emerald-100/50">
                      {line.map((w) => {
                        if (!w.isWord) return <span key={w.id} className="whitespace-pre text-gray-300">{w.text}</span>;

                        const isRepeating = repeatingWords.includes(w.cleanWord);
                        const displayMode = userEncoding[w.id] || 'word';
                        const dictItem = dictionary.find(d => d.word === w.cleanWord);

                        return (
                          <button
                            key={w.id}
                            onClick={() => isRepeating && toggleEncoding(w.id)}
                            className={`px-1 py-0.5 rounded-md transition-all font-black mx-0.5 ${
                              isRepeating 
                                ? (displayMode === 'code' ? 'bg-emerald-600 text-white' : 'bg-white border border-emerald-200 text-emerald-700 hover:bg-emerald-50') 
                                : 'text-gray-400'
                            }`}
                          >
                            {displayMode === 'code' && dictItem ? `#${dictItem.code}` : w.text}
                          </button>
                        );
                      })}
                    </div>
                  ))}
                </div>

                {/* Stats & Finish */}
                <div className="mt-8 pt-6 border-t border-emerald-100 flex items-center justify-between">
                   <div className="text-left">
                      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Aktuální úspora</p>
                      <p className="text-2xl font-black text-emerald-600 tracking-tighter">{stats.percent}%</p>
                   </div>
                   {isLevelComplete && (
                     <div className="bg-emerald-100 px-4 py-2 rounded-2xl flex items-center gap-2 text-emerald-800 animate-bounce">
                        <CheckCircle2 className="w-5 h-5" />
                        <span className="font-black text-xs uppercase tracking-widest">Skvělá komprese!</span>
                     </div>
                   )}
                </div>

                <button 
                  onClick={() => { setPhase('identification'); setSelectedIndices(new Set()); setDictionary([]); setUserEncoding({}); }}
                  className="w-full mt-6 py-3 text-gray-400 font-black uppercase text-[10px] tracking-widest hover:text-blue-600 transition-colors flex items-center justify-center gap-2"
                >
                  <RefreshCcw className="w-3 h-3" /> Začít znovu
                </button>
              </div>
            </>
          )}
        </div>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f1f5f9;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #3b82f6;
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
};

export default TextCompression;

export interface RGB {
  r: number;
  g: number;
  b: number;
}

export interface Segment {
  id: number;
  path: string;
  targetRGB: RGB;
  currentRGB: RGB;
  isCorrect: boolean;
  labelPosition: { x: number; y: number };
}

export interface Line {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
}

export type Difficulty = 'easy' | 'medium' | 'hard';
export type Screen = 'landing' | 'splash' | 'menu' | 'drawing' | 'quiz' | 'lines-menu' | 'vector-drawing' | 'line-drawing' | 'shape-puzzle' | 'compression-menu' | 'compression-game' | 'text-compression';

import React, { useState } from 'react';
import LandingPage from './components/LandingPage';
import SplashScreen from './components/SplashScreen';
import Menu from './components/Menu';
import RGBDrawing from './components/RGBDrawing';
import Quiz from './components/Quiz';
import LinesMenu from './components/LinesMenu';
import VectorDrawing from './components/VectorDrawing';
import ShapePuzzle from './components/ShapePuzzle';
import CompressionMenu from './components/CompressionMenu';
import CompressionGame from './components/CompressionGame';
import TextCompression from './components/TextCompression';
import { Screen, Difficulty, Segment } from './types';
import { ROCKET_DATA, CAT_DATA, COMPUTER_DATA } from './constants';

const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<Screen>('landing');
  const [selectedData, setSelectedData] = useState<Segment[]>([]);
  const [levelName, setLevelName] = useState<string>('');

  const handleStartLevel = (difficulty: Difficulty) => {
    switch (difficulty) {
      case 'easy':
        setSelectedData(ROCKET_DATA);
        setLevelName('Raketa');
        break;
      case 'medium':
        setSelectedData(CAT_DATA);
        setLevelName('Kočka');
        break;
      case 'hard':
        setSelectedData(COMPUTER_DATA);
        setLevelName('Počítač');
        break;
    }
    setCurrentScreen('drawing');
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case 'landing':
        return (
          <LandingPage 
            onStartColors={() => setCurrentScreen('splash')} 
            onStartLines={() => setCurrentScreen('lines-menu')} 
            onStartCompression={() => setCurrentScreen('compression-menu')}
          />
        );
      case 'compression-menu':
        return (
          <CompressionMenu 
            onStartGame={() => setCurrentScreen('compression-game')}
            onStartText={() => setCurrentScreen('text-compression')}
            onBack={() => setCurrentScreen('landing')}
          />
        );
      case 'compression-game':
        return (
          <CompressionGame onBack={() => setCurrentScreen('compression-menu')} />
        );
      case 'text-compression':
        return (
          <TextCompression onBack={() => setCurrentScreen('compression-menu')} />
        );
      case 'lines-menu':
        return (
          <LinesMenu 
            onShapePuzzle={() => setCurrentScreen('shape-puzzle')}
            onVectorDrawing={() => setCurrentScreen('vector-drawing')}
            onLineDrawing={() => setCurrentScreen('line-drawing')}
            onBack={() => setCurrentScreen('landing')}
          />
        );
      case 'shape-puzzle':
        return (
          <ShapePuzzle onBack={() => setCurrentScreen('lines-menu')} />
        );
      case 'vector-drawing':
        return (
          <VectorDrawing 
            mode="points"
            onBack={() => setCurrentScreen('lines-menu')}
          />
        );
      case 'line-drawing':
        return (
          <VectorDrawing 
            mode="lines"
            onBack={() => setCurrentScreen('lines-menu')}
          />
        );
      case 'splash':
        return (
          <SplashScreen 
            onEnter={() => setCurrentScreen('menu')} 
            onQuiz={() => setCurrentScreen('quiz')}
            onBack={() => setCurrentScreen('landing')}
          />
        );
      case 'menu':
        return <Menu onStart={handleStartLevel} onBack={() => setCurrentScreen('splash')} />;
      case 'drawing':
        return (
          <RGBDrawing 
            onBack={() => setCurrentScreen('menu')} 
            initialSegments={selectedData}
            title={levelName}
          />
        );
      case 'quiz':
        return <Quiz onBack={() => setCurrentScreen('splash')} />;
      default:
        return <LandingPage onStartColors={() => setCurrentScreen('splash')} onStartLines={() => setCurrentScreen('lines-menu')} onStartCompression={() => setCurrentScreen('compression-menu')} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-[#f8fafc]">
      {renderScreen()}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { ArrowLeft, CheckCircle2, RefreshCcw, HelpCircle, ArrowRight, Hash, FileText, Zap, Trophy, Sparkles } from 'lucide-react';

interface TextLevel {
  id: number;
  title: string;
  lines: string[];
}

const LEVELS: TextLevel[] = [
  {
    id: 1,
    title: "Prší, prší",
    lines: [
      "PRŠÍ, PRŠÍ, JEN SE LEJE.",
      "KAM KONÍČKY POJEDEME?",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ.",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ."
    ]
  },
  {
    id: 2,
    title: "Kukačka",
    lines: [
      "KUKAČKA UŽ ZAKUKALA,",
      "MÁ PANENKA ZAPLAKALA.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ."
    ]
  }
];

type Phase = 'identification' | 'dictionary' | 'assembly' | 'finished';

interface Token {
  id: string;
  text: string;
  cleanWord: string;
  isWord: boolean;
}

const TextCompression: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [levelIdx, setLevelIdx] = useState(0);
  const [phase, setPhase] = useState<Phase>('identification');
  const [selectedIndices, setSelectedIndices] = useState<Set<string>>(new Set());
  const [dictionary, setDictionary] = useState<{ word: string; code: number }[]>([]);
  const [assemblyState, setAssemblyState] = useState<{ [tokenId: string]: string | number }>({});
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  const level = LEVELS[levelIdx];

  // Rozklad textu na tokeny
  const tokensMatrix: Token[][] = useMemo(() => {
    return level.lines.map((line, lIdx) => {
      const parts = line.split(/(\s+)/);
      return parts.map((part, pIdx) => {
        const isWord = /[A-ZČŠŽŘĎŤŇŮÚ]+/.test(part.toUpperCase());
        const cleanWord = part.trim().replace(/[,.?]/g, '').toUpperCase();
        return {
          id: `${lIdx}-${pIdx}`,
          text: part,
          cleanWord,
          isWord
        };
      });
    });
  }, [level]);

  const allTokens = useMemo(() => tokensMatrix.flat(), [tokensMatrix]);
  const allWords = useMemo(() => allTokens.filter(t => t.isWord), [allTokens]);

  // Výpočet skutečných duplicit v textu
  const duplicateWords = useMemo(() => {
    const counts: { [word: string]: number } = {};
    allWords.forEach(w => {
      counts[w.cleanWord] = (counts[w.cleanWord] || 0) + 1;
    });
    return Object.keys(counts).filter(w => counts[w] > 1);
  }, [allWords]);

  // Kontrola, zda slovo ve slovníku bylo "vyhráno" (všechny instance označeny)
  const identifiedDictionaryWords = useMemo(() => {
    const result: string[] = [];
    duplicateWords.forEach(word => {
      const wordTokenIds = allWords.filter(t => t.cleanWord === word).map(t => t.id);
      if (wordTokenIds.every(id => selectedIndices.has(id))) {
        result.push(word);
      }
    });
    return result;
  }, [duplicateWords, allWords, selectedIndices]);

  useEffect(() => {
    // Reset při změně levelu
    setPhase('identification');
    setSelectedIndices(new Set());
    setDictionary([]);
    setAssemblyState({});
    setFeedback(null);
  }, [levelIdx]);

  const handleWordClick = (token: Token) => {
    if (phase !== 'identification') return;
    if (!token.isWord) return;

    const newSelected = new Set(selectedIndices);
    if (newSelected.has(token.id)) {
      newSelected.delete(token.id);
    } else {
      newSelected.add(token.id);
    }
    setSelectedIndices(newSelected);
  };

  const goToDictionaryPhase = () => {
    if (identifiedDictionaryWords.length < duplicateWords.length) {
      setFeedback({ type: 'error', message: 'Ještě jsi nenašel všechna opakující se slova!' });
      return;
    }

    // Seřadíme slova podle prvního výskytu v textu pro konzistenci
    const wordsInOrder: string[] = [];
    allWords.forEach(w => {
      if (identifiedDictionaryWords.includes(w.cleanWord) && !wordsInOrder.includes(w.cleanWord)) {
        wordsInOrder.push(w.cleanWord);
      }
    });

    const newDict = wordsInOrder.map((word, idx) => ({ word, code: idx + 1 }));
    setDictionary(newDict);
    setPhase('dictionary');
    setFeedback({ type: 'success', message: 'Skvěle! Našel jsi všechna opakující se slova. Teď jim přiřaď kódy.' });
  };

  const goToAssemblyPhase = () => {
    setPhase('assembly');
    setFeedback({ type: 'success', message: 'Slovník je hotov! Teď sestav zkomprimovaný text.' });
  };

  const handleAssemble = (tokenId: string, value: string | number) => {
    setAssemblyState(prev => ({ ...prev, [tokenId]: value }));
  };

  const checkAssembly = () => {
    let errors = 0;
    allTokens.forEach(t => {
      const userVal = assemblyState[t.id];
      if (!t.isWord) return; // Mezery nekontrolujeme tak přísně

      const dictItem = dictionary.find(d => d.word === t.cleanWord);
      if (dictItem) {
        // Musí tam být kód
        if (userVal !== dictItem.code) errors++;
      } else {
        // Musí tam být původní slovo
        if (userVal !== t.text) errors++;
      }
    });

    if (errors === 0) {
      setPhase('finished');
      setFeedback(null);
    } else {
      setFeedback({ type: 'error', message: `Máš tam ještě ${errors} chyb. Zkontroluj hlavně kódy u opakujících se slov.` });
    }
  };

  const stats = useMemo(() => {
    const originalLen = level.lines.join('\n').length;
    let compressedLen = 0;

    // Simulace délky komprese
    allTokens.forEach(t => {
      if (!t.isWord) {
        compressedLen += t.text.length;
      } else {
        const dictItem = dictionary.find(d => d.word === t.cleanWord);
        if (dictItem) compressedLen += (`#${dictItem.code}`).length;
        else compressedLen += t.text.length;
      }
    });

    const dictDataLen = dictionary.reduce((acc, curr) => acc + curr.word.length + 4, 0);
    const totalCompressed = compressedLen + dictDataLen;

    return {
      original: originalLen,
      compressed: totalCompressed,
      savings: Math.round(((originalLen - totalCompressed) / originalLen) * 100)
    };
  }, [level, allTokens, dictionary]);

  return (
    <div className="w-full max-w-6xl flex flex-col gap-6 items-center animate-in fade-in duration-500 pb-20 px-4">
      {/* Horní navigace a status */}
      <div className="w-full bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col md:flex-row items-center justify-between gap-6">
        <button onClick={onBack} className="flex items-center text-gray-400 hover:text-blue-600 transition-colors font-black uppercase text-xs tracking-widest shrink-0">
          <ArrowLeft className="w-5 h-5 mr-2" /> Zpět
        </button>

        <div className="flex gap-3">
          {LEVELS.map((l, idx) => (
            <button
              key={l.id}
              onClick={() => setLevelIdx(idx)}
              className={`px-5 py-2.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${levelIdx === idx ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' : 'bg-blue-50 text-blue-600 hover:bg-blue-100'}`}
            >
              {l.title}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-4 bg-blue-50 px-5 py-3 rounded-2xl border border-blue-100">
          <Zap className="w-5 h-5 text-blue-600" />
          <div className="text-left">
            <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Fáze</p>
            <p className="text-sm font-black text-blue-900 tracking-tight leading-none">
              {phase === 'identification' ? '1. Hledání duplicit' : phase === 'dictionary' ? '2. Tvorba slovníku' : phase === 'assembly' ? '3. Sestavení textu' : 'Dokončeno'}
            </p>
          </div>
        </div>
      </div>

      {feedback && (
        <div className={`w-full p-4 rounded-2xl border-2 flex items-center gap-3 animate-in slide-in-from-top duration-300 ${feedback.type === 'success' ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800'}`}>
          {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <HelpCircle className="w-5 h-5" />}
          <span className="font-bold text-sm uppercase tracking-tight">{feedback.message}</span>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 w-full items-start">

        {/* Hlavní pracovní plocha */}
        <div className="lg:col-span-8 bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100 min-h-[500px] flex flex-col">
          <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight mb-8 flex items-center gap-3">
            <div className={`w-3 h-8 bg-blue-500 rounded-full`}></div>
            {phase === 'identification' ? 'Označ všechna slova, která se opakují' : phase === 'dictionary' ? 'Přiřazení kódů ve slovníku' : 'Sestav zkomprimovaný text'}
          </h3>

          <div className="flex-1 space-y-6">
            {phase === 'identification' && (
              <div className="space-y-4 font-mono text-lg">
                {tokensMatrix.map((line, lIdx) => (
                  <div key={lIdx} className="flex flex-wrap items-center bg-gray-50/50 p-4 rounded-2xl">
                    {line.map(t => {
                      if (!t.isWord) return <span key={t.id} className="whitespace-pre">{t.text}</span>;
                      const isSelected = selectedIndices.has(t.id);
                      const isIdentified = identifiedDictionaryWords.includes(t.cleanWord);
                      return (
                        <button
                          key={t.id}
                          onClick={() => handleWordClick(t)}
                          className={`px-1.5 py-0.5 rounded-lg transition-all font-black relative ${isSelected ? (isIdentified ? 'bg-emerald-600 text-white shadow-md' : 'bg-blue-600 text-white shadow-md') : 'hover:bg-blue-100 text-gray-700'}`}
                        >
                          {t.text}
                          {isIdentified && <Sparkles className="absolute -top-1 -right-1 w-3 h-3 text-emerald-400" />}
                        </button>
                      );
                    })}
                  </div>
                ))}
              </div>
            )}

            {phase === 'dictionary' && (
              <div className="flex flex-col items-center justify-center h-full text-center space-y-8 animate-in zoom-in duration-500">
                <div className="p-8 bg-blue-50 rounded-[3rem] border-2 border-dashed border-blue-200">
                   <Hash className="w-16 h-16 text-blue-400 mx-auto mb-4" />
                   <p className="text-blue-900 font-bold max-w-sm">Slova byla automaticky seřazena do slovníku podle jejich prvního výskytu v textu. Prohlédni si kódovou tabulku vpravo.</p>
                </div>
                <button onClick={goToAssemblyPhase} className="px-10 py-5 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-[2rem] shadow-xl flex items-center gap-3 uppercase tracking-widest">
                  Rozumím, jdeme sestavovat <ArrowRight className="w-5 h-5" />
                </button>
              </div>
            )}

            {phase === 'assembly' && (
              <div className="space-y-4 font-mono text-sm">
                {tokensMatrix.map((line, lIdx) => (
                  <div key={lIdx} className="flex flex-wrap items-center gap-y-2 bg-gray-50/50 p-4 rounded-2xl">
                    {line.map(t => {
                      if (!t.isWord) return <span key={t.id} className="whitespace-pre">{t.text}</span>;

                      const userVal = assemblyState[t.id];
                      const isDuplicate = duplicateWords.includes(t.cleanWord);
                      const dictItem = dictionary.find(d => d.word === t.cleanWord);

                      return (
                        <div key={t.id} className="relative group mx-0.5">
                          <select 
                            value={userVal || ''}
                            onChange={(e) => {
                                const val = e.target.value;
                                handleAssemble(t.id, isNaN(Number(val)) ? val : Number(val));
                            }}
                            className={`px-2 py-1 rounded-lg border-2 font-black appearance-none cursor-pointer transition-all ${userVal ? 'bg-blue-600 text-white border-blue-400' : 'bg-white border-gray-200 text-gray-400 hover:border-blue-300'}`}
                          >
                            <option value="">???</option>
                            <option value={t.text}>{t.text}</option>
                            {dictionary.map(d => (
                              <option key={d.code} value={d.code}>#{d.code} ({d.word})</option>
                            ))}
                          </select>
                        </div>
                      );
                    })}
                  </div>
                ))}
              </div>
            )}

            {phase === 'finished' && (
              <div className="flex flex-col items-center justify-center h-full text-center space-y-8 animate-in zoom-in duration-500">
                <div className="w-24 h-24 bg-gradient-to-tr from-yellow-400 to-orange-500 rounded-[2rem] flex items-center justify-center mx-auto shadow-xl rotate-12 mb-4">
                  <Trophy className="w-12 h-12 text-white" />
                </div>
                <h2 className="text-3xl font-black text-gray-800 uppercase tracking-tighter">Text zkomprimován!</h2>
                <p className="text-gray-500 max-w-md font-medium">Dokázal jsi efektivně nahradit opakující se slova kódy a ušetřit místo v paměti počítače.</p>
                <div className="grid grid-cols-2 gap-4 w-full max-w-sm">
                  <div className="bg-blue-50 p-4 rounded-2xl">
                    <p className="text-[10px] font-black text-blue-400 uppercase">Úspora</p>
                    <p className="text-2xl font-black text-blue-600">{stats.savings}%</p>
                  </div>
                  <div className="bg-emerald-50 p-4 rounded-2xl">
                    <p className="text-[10px] font-black text-emerald-400 uppercase">Status</p>
                    <p className="text-2xl font-black text-emerald-600">MISTR</p>
                  </div>
                </div>
              </div>
            )}
          </div>

          <div className="mt-8">
            {phase === 'identification' && (
              <button onClick={goToDictionaryPhase} className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest transition-all">
                Mám označeny všechny duplicity <ArrowRight className="w-5 h-5" />
              </button>
            )}
            {phase === 'assembly' && (
              <button onClick={checkAssembly} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest transition-all">
                Zkontrolovat kompresi <CheckCircle2 className="w-5 h-5" />
              </button>
            )}
            {phase === 'finished' && (
              <button onClick={() => setLevelIdx((levelIdx + 1) % LEVELS.length)} className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest">
                Další text <ArrowRight className="w-5 h-5" />
              </button>
            )}
          </div>
        </div>

        {/* Pravý panel: Slovník a Statistiky */}
        <div className="lg:col-span-4 flex flex-col gap-6">
          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-blue-100 flex flex-col">
            <h3 className="text-xl font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
              <Hash className="w-6 h-6 text-blue-600" />
              Slovník (Kódy)
            </h3>

            <div className="space-y-3 min-h-[200px]">
              {dictionary.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-10 text-gray-300 border-2 border-dashed border-gray-100 rounded-3xl">
                  <FileText className="w-8 h-8 mb-2 opacity-20" />
                  <p className="text-[10px] font-black uppercase tracking-widest italic text-center px-4">Slovník se vytvoří po nalezení všech duplicit</p>
                </div>
              ) : (
                dictionary.map(item => (
                  <div key={item.code} className="flex items-center gap-4 p-4 bg-blue-50 border border-blue-100 rounded-2xl animate-in slide-in-from-right duration-300">
                    <span className="w-10 h-10 bg-blue-600 text-white font-black rounded-xl flex items-center justify-center shadow-sm">
                      #{item.code}
                    </span>
                    <span className="font-black text-blue-900 uppercase tracking-tight truncate">{item.word}</span>
                  </div>
                ))
              )}
            </div>
          </div>

          <div className="bg-gray-900 p-8 rounded-[3rem] shadow-2xl text-white">
            <h3 className="text-sm font-black text-gray-400 mb-8 uppercase tracking-[0.2em] flex items-center gap-3">
              <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>
              Energie k zápisu
            </h3>

            <div className="space-y-6">
              <div className="flex justify-between items-center">
                <span className="text-gray-400 font-bold uppercase text-[10px] tracking-widest">Původní text</span>
                <span className="text-xl font-black">{stats.original} znaků</span>
              </div>

              <div className="h-px bg-gray-800 w-full"></div>

              <div className="flex justify-between items-center">
                <span className="text-gray-400 font-bold uppercase text-[10px] tracking-widest">Zkomprimovaný</span>
                <span className="text-xl font-black text-blue-400">{stats.compressed} znaků</span>
              </div>

              <div className="bg-blue-600/10 border border-blue-500/20 p-6 rounded-[2rem] flex flex-col items-center text-center">
                <p className="text-xs font-black text-blue-400 uppercase tracking-widest mb-1">Úspora</p>
                <div className="text-4xl font-black text-white tracking-tighter">
                  {stats.savings}%
                </div>
              </div>
            </div>
          </div>

          <button onClick={() => { setSelectedIndices(new Set()); setPhase('identification'); setDictionary([]); setAssemblyState([]); setFeedback(null); }} className="w-full py-4 flex items-center justify-center bg-white hover:bg-gray-50 text-gray-500 font-black rounded-[2rem] transition-all shadow-sm border-2 border-gray-100 uppercase text-[10px] tracking-widest">
            <RefreshCcw className="w-4 h-4 mr-2" /> Restartovat úlohu
          </button>
        </div>
      </div>
    </div>
  );
};

export default TextCompression;

import React, { useState, useMemo, useEffect } from 'react';
import { ArrowLeft, CheckCircle2, RefreshCcw, HelpCircle, ArrowRight, Hash, FileText, Zap, Trophy, PlusCircle, AlertCircle } from 'lucide-react';

interface TextLevel {
  id: number;
  title: string;
  lines: string[];
}

const LEVELS: TextLevel[] = [
  {
    id: 1,
    title: "Prší, prší",
    lines: [
      "PRŠÍ, PRŠÍ, JEN SE LEJE.",
      "KAM KONÍČKY POJEDEME?",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ.",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ."
    ]
  },
  {
    id: 2,
    title: "Kukačka",
    lines: [
      "KUKAČKA UŽ ZAKUKALA,",
      "MÁ PANENKA ZAPLAKALA.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ."
    ]
  }
];

type Phase = 'identification' | 'numbering' | 'assembly' | 'finished';

interface Token {
  id: string;
  text: string;
  cleanWord: string;
  isWord: boolean;
}

const TextCompression: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [levelIdx, setLevelIdx] = useState(0);
  const [phase, setPhase] = useState<Phase>('identification');
  const [dictionary, setDictionary] = useState<{ word: string; code: number | null }[]>([]);
  const [selectedIndices, setSelectedIndices] = useState<Set<string>>(new Set());
  const [identifiedWords, setIdentifiedWords] = useState<Set<string>>(new Set());
  const [assemblyState, setAssemblyState] = useState<{ [tokenId: string]: string | number }>({});
  const [activeAssemblyToken, setActiveAssemblyToken] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  const level = LEVELS[levelIdx];

  const tokensMatrix: Token[][] = useMemo(() => {
    return level.lines.map((line, lIdx) => {
      const parts = line.split(/(\s+)/);
      return parts.map((part, pIdx) => {
        const isWord = /[A-ZČŠŽŘĎŤŇŮÚ]+/.test(part.toUpperCase());
        const cleanWord = part.trim().replace(/[,.?]/g, '').toUpperCase();
        return { id: `${lIdx}-${pIdx}`, text: part, cleanWord, isWord };
      });
    });
  }, [level]);

  const allTokens = useMemo(() => tokensMatrix.flat(), [tokensMatrix]);
  const allWords = useMemo(() => allTokens.filter(t => t.isWord), [allTokens]);

  const duplicateWords = useMemo(() => {
    const counts: { [word: string]: number } = {};
    allWords.forEach(w => { counts[w.cleanWord] = (counts[w.cleanWord] || 0) + 1; });
    return Object.keys(counts).filter(w => counts[w] > 1);
  }, [allWords]);

  const nonEncodableWords = useMemo(() => {
    return Array.from(new Set(allWords.filter(w => !duplicateWords.includes(w.cleanWord)).map(w => w.text)));
  }, [allWords, duplicateWords]);

  useEffect(() => {
    setPhase('identification');
    setDictionary([]);
    setSelectedIndices(new Set());
    setIdentifiedWords(new Set());
    setAssemblyState({});
    setFeedback(null);
  }, [levelIdx]);

  // FÁZE 1: Identifikace
  const handleWordClickId = (token: Token) => {
    if (phase !== 'identification' || !token.isWord || identifiedWords.has(token.cleanWord)) return;
    const newSelected = new Set(selectedIndices);
    if (newSelected.has(token.id)) newSelected.delete(token.id);
    else newSelected.add(token.id);
    setSelectedIndices(newSelected);
  };

  const addToDictionary = () => {
    if (selectedIndices.size === 0) return;
    const selectedTokens = allTokens.filter(t => selectedIndices.has(t.id));
    const word = selectedTokens[0].cleanWord;

    // Kontrola, zda jsou všechna označená slova stejná
    if (!selectedTokens.every(t => t.cleanWord === word)) {
      setFeedback({ type: 'error', message: 'Označil jsi různá slova! Musíš vybrat vždy jen výskyty stejného slova.' });
      return;
    }

    // Kontrola, zda jsou označeny VŠECHNY výskyty
    const totalOccurrences = allWords.filter(t => t.cleanWord === word).length;
    if (selectedIndices.size !== totalOccurrences) {
      setFeedback({ type: 'error', message: `Slovo ${word} se v textu vyskytuje ${totalOccurrences}x, ty jsi jich označil jen ${selectedIndices.size}.` });
      return;
    }

    if (totalOccurrences < 2) {
      setFeedback({ type: 'error', message: 'Toto slovo se neopakuje, nelze ho dát do slovníku.' });
      return;
    }

    setDictionary(prev => [...prev, { word, code: null }]);
    setIdentifiedWords(prev => new Set(prev).add(word));
    setSelectedIndices(new Set());
    setFeedback({ type: 'success', message: `Slovo ${word} uloženo do slovníku.` });
  };

  const finishIdentification = () => {
    if (identifiedWords.size < duplicateWords.length) {
      setFeedback({ type: 'error', message: 'Ještě jsi nenašel všechna opakující se slova!' });
      return;
    }
    setPhase('numbering');
    setFeedback({ type: 'success', message: 'Výborně! Teď očisluj slova ve slovníku podle toho, jak se poprvé objevují v textu.' });
  };

  // FÁZE 2: Číslování
  const setWordCode = (index: number, val: string) => {
    const code = val === '' ? null : parseInt(val);
    setDictionary(prev => prev.map((item, i) => i === index ? { ...item, code } : item));
  };

  const validateNumbering = () => {
    const sortedWordsInText: string[] = [];
    allWords.forEach(w => {
      if (duplicateWords.includes(w.cleanWord) && !sortedWordsInText.includes(w.cleanWord)) {
        sortedWordsInText.push(w.cleanWord);
      }
    });

    let errors = 0;
    dictionary.forEach(item => {
      const correctCode = sortedWordsInText.indexOf(item.word) + 1;
      if (item.code !== correctCode) errors++;
    });

    if (errors > 0) {
      setFeedback({ type: 'error', message: 'Pořadí kódů není správné. Sleduj text shora dolů.' });
    } else {
      setPhase('assembly');
      setFeedback({ type: 'success', message: 'Slovník je správně očíslován! Teď sestav zkomprimovanou báseň.' });
    }
  };

  // FÁZE 3: Sestavení
  const handleAssemblySelect = (val: string | number) => {
    if (!activeAssemblyToken) return;
    setAssemblyState(prev => ({ ...prev, [activeAssemblyToken]: val }));
    setActiveAssemblyToken(null);
  };

  const checkFinal = () => {
    let errors = 0;
    allTokens.forEach(t => {
      if (!t.isWord) return;
      const userVal = assemblyState[t.id];
      const dictItem = dictionary.find(d => d.word === t.cleanWord);
      if (dictItem) {
        if (userVal !== dictItem.code) errors++;
      } else {
        if (userVal !== t.text) errors++;
      }
    });

    if (errors === 0) {
      setPhase('finished');
      setFeedback(null);
    } else {
      setFeedback({ type: 'error', message: `Máš tam ještě ${errors} chyb. Zkontroluj hlavně kódy.` });
    }
  };

  return (
    <div className="w-full max-w-7xl flex flex-col gap-6 items-center animate-in fade-in duration-500 pb-20 px-4">
      {/* Horní navigace */}
      <div className="w-full bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col md:flex-row items-center justify-between gap-6">
        <button onClick={onBack} className="flex items-center text-gray-400 hover:text-blue-600 transition-colors font-black uppercase text-xs tracking-widest shrink-0">
          <ArrowLeft className="w-5 h-5 mr-2" /> Zpět
        </button>

        <div className="flex gap-2">
          {LEVELS.map((l, idx) => (
            <button key={l.id} onClick={() => setLevelIdx(idx)} className={`px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${levelIdx === idx ? 'bg-blue-600 text-white' : 'bg-blue-50 text-blue-600'}`}>{l.title}</button>
          ))}
        </div>

        <div className="flex items-center gap-4 bg-blue-50 px-5 py-3 rounded-2xl border border-blue-100">
          <Zap className="w-5 h-5 text-blue-600" />
          <div className="text-left">
            <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest leading-none">Fáze</p>
            <p className="text-xs font-black text-blue-900 uppercase tracking-tight">
              {phase === 'identification' ? '1. Identifikace' : phase === 'numbering' ? '2. Číslování' : phase === 'assembly' ? '3. Sestavování' : 'Hotovo'}
            </p>
          </div>
        </div>
      </div>

      {feedback && (
        <div className={`w-full p-4 rounded-2xl border-2 flex items-center gap-3 animate-in slide-in-from-top duration-300 ${feedback.type === 'success' ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800'}`}>
          {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          <span className="font-bold text-sm uppercase tracking-tight">{feedback.message}</span>
        </div>
      )}

      {/* Hlavní obsah dle fází */}
      {phase === 'identification' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 w-full">
          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100">
            <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight mb-6">1. Najdi všechny výskyty jednoho slova</h3>
            <div className="space-y-4 font-mono text-lg">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-gray-50/50 p-4 rounded-2xl">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre">{t.text}</span>;
                    const isSelected = selectedIndices.has(t.id);
                    const isDone = identifiedWords.has(t.cleanWord);
                    return (
                      <button key={t.id} onClick={() => handleWordClickId(t)} className={`px-1.5 py-0.5 rounded-lg transition-all font-black ${isDone ? 'bg-emerald-100 text-emerald-700 opacity-50 cursor-default' : isSelected ? 'bg-blue-600 text-white shadow-md' : 'hover:bg-blue-100 text-gray-700'}`}>
                        {t.text}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
            <button onClick={addToDictionary} className="w-full mt-8 py-4 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-2xl shadow-lg flex items-center justify-center gap-2 uppercase tracking-widest text-sm">
              <PlusCircle className="w-5 h-5" /> Vložit do slovníku
            </button>
          </div>

          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-blue-100 flex flex-col">
            <h3 className="text-xl font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
              <Hash className="w-6 h-6 text-blue-600" /> Slovník
            </h3>
            <div className="flex-1 space-y-3">
              {dictionary.length === 0 ? (
                <div className="py-20 text-center text-gray-300 font-bold uppercase text-xs tracking-widest border-2 border-dashed rounded-3xl">Zatím prázdné</div>
              ) : (
                dictionary.map((item, idx) => (
                  <div key={idx} className="flex items-center gap-4 p-4 bg-blue-50 rounded-2xl animate-in slide-in-from-right duration-300">
                    <div className="w-10 h-10 bg-blue-100 text-blue-600 font-black rounded-xl flex items-center justify-center">?</div>
                    <span className="font-black text-blue-900 uppercase">{item.word}</span>
                  </div>
                ))
              )}
            </div>
            {identifiedWords.size === duplicateWords.length && identifiedWords.size > 0 && (
              <button onClick={finishIdentification} className="w-full mt-6 py-4 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-2xl shadow-lg flex items-center justify-center gap-2 uppercase tracking-widest text-sm">
                Vše nalezeno, pokračovat <ArrowRight className="w-5 h-5" />
              </button>
            )}
          </div>
        </div>
      )}

      {phase === 'numbering' && (
        <div className="w-full max-w-2xl bg-white p-10 rounded-[3rem] shadow-2xl border border-blue-100 animate-in zoom-in duration-500">
          <h3 className="text-2xl font-black text-gray-800 mb-8 uppercase tracking-tighter text-center">2. Přiřaď kódům čísla (1, 2, 3...)</h3>
          <p className="text-sm text-gray-500 mb-8 text-center font-medium">Sleduj text písničky a přiřaď slova ve slovníku číslu podle toho, v jakém pořadí se v textu poprvé objeví.</p>
          <div className="space-y-4">
            {dictionary.map((item, idx) => (
              <div key={idx} className="flex items-center justify-between p-5 bg-blue-50 rounded-3xl border border-blue-100">
                <span className="font-black text-blue-900 text-lg uppercase tracking-tight">{item.word}</span>
                <div className="flex items-center gap-3">
                  <span className="text-blue-400 font-black">KÓD #</span>
                  <input type="number" value={item.code || ''} onChange={(e) => setWordCode(idx, e.target.value)} className="w-16 p-3 bg-white border-2 border-blue-200 rounded-xl text-center font-black text-blue-600 outline-none focus:border-blue-500" placeholder="?" />
                </div>
              </div>
            ))}
          </div>
          <button onClick={validateNumbering} className="w-full mt-10 py-5 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-3xl shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest">
            Zkontrolovat očíslování <ArrowRight className="w-5 h-5" />
          </button>
        </div>
      )}

      {phase === 'assembly' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 w-full items-start">
          {/* Levý sloupec: Původní text */}
          <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col">
            <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4">Originální text</h4>
            <div className="space-y-3 font-mono text-sm opacity-60">
              {level.lines.map((line, i) => <div key={i} className="bg-gray-50 p-2 rounded-lg">{line}</div>)}
            </div>
          </div>

          {/* Střední sloupec: Stavební prvky */}
          <div className="bg-blue-900 p-6 rounded-[2.5rem] shadow-xl text-white flex flex-col gap-6">
            <h4 className="text-xs font-black text-blue-300 uppercase tracking-widest">Kódy ze slovníku</h4>
            <div className="grid grid-cols-2 gap-2">
              {dictionary.map(item => (
                <button key={item.code} onClick={() => handleAssemblySelect(item.code!)} className="p-3 bg-blue-800 hover:bg-blue-700 rounded-xl flex items-center gap-2 border border-blue-700 transition-colors">
                  <span className="w-6 h-6 bg-blue-500 text-white rounded-md flex items-center justify-center text-[10px] font-black">#{item.code}</span>
                  <span className="text-[10px] font-black uppercase truncate">{item.word}</span>
                </button>
              ))}
            </div>

            <h4 className="text-xs font-black text-blue-300 uppercase tracking-widest mt-4">Slova bez kódu</h4>
            <div className="flex flex-wrap gap-2">
              {nonEncodableWords.map(word => (
                <button key={word} onClick={() => handleAssemblySelect(word)} className="px-3 py-2 bg-gray-800 hover:bg-gray-700 rounded-lg text-[10px] font-black uppercase border border-gray-700 transition-colors">{word}</button>
              ))}
            </div>
          </div>

          {/* Pravý sloupec: Sestavování */}
          <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border-4 border-emerald-100 flex flex-col">
            <h4 className="text-xs font-black text-emerald-600 uppercase tracking-widest mb-4">Komprimovaný zápis</h4>
            <div className="space-y-4 font-mono text-sm">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-emerald-50/50 p-3 rounded-xl border border-emerald-100 min-h-[48px]">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-gray-300">{t.text}</span>;
                    const val = assemblyState[t.id];
                    const isActive = activeAssemblyToken === t.id;
                    return (
                      <button key={t.id} onClick={() => setActiveAssemblyToken(t.id)} className={`min-w-[40px] px-2 py-1 mx-0.5 rounded-md font-black transition-all border-2 ${isActive ? 'bg-blue-100 border-blue-500 animate-pulse' : val ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white border-emerald-200 text-emerald-300'}`}>
                        {val ? (typeof val === 'number' ? `#${val}` : val) : '???'}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
            <button onClick={checkFinal} className="w-full mt-8 py-4 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-2xl shadow-lg flex items-center justify-center gap-2 uppercase tracking-widest text-sm">
              Zkontrolovat kompresi
            </button>
          </div>
        </div>
      )}

      {phase === 'finished' && (
        <div className="max-w-md w-full bg-white p-12 rounded-[3.5rem] shadow-2xl border-4 border-emerald-100 text-center animate-in zoom-in duration-500">
          <div className="w-24 h-24 bg-gradient-to-tr from-emerald-400 to-teal-500 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-xl rotate-12">
            <Trophy className="w-12 h-12 text-white" />
          </div>
          <h2 className="text-4xl font-black text-gray-900 mb-2 uppercase tracking-tighter">Vynikající!</h2>
          <p className="text-gray-500 mb-8 font-medium italic">Dokonale jsi zkomprimoval text a ušetřil <span className="text-emerald-600 font-black">{stats.savings}%</span> místa!</p>
          <div className="space-y-4">
            <button onClick={() => setLevelIdx((levelIdx + 1) % LEVELS.length)} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl uppercase tracking-widest">Další text</button>
            <button onClick={onBack} className="w-full py-4 bg-gray-50 text-gray-500 font-bold rounded-[2rem] uppercase tracking-widest text-xs">Menu</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default TextCompression;

import React, { useState, useMemo, useEffect } from 'react';
import { ArrowLeft, CheckCircle2, RefreshCcw, HelpCircle, ArrowRight, Hash, FileText, Zap, Trophy, PlusCircle, AlertCircle } from 'lucide-react';

interface TextLevel {
  id: number;
  title: string;
  lines: string[];
}

const LEVELS: TextLevel[] = [
  {
    id: 1,
    title: "Prší, prší",
    lines: [
      "PRŠÍ, PRŠÍ, JEN SE LEJE.",
      "KAM KONÍČČKY POJEDEME?",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ.",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ."
    ]
  },
  {
    id: 2,
    title: "Kukačka",
    lines: [
      "KUKAČKA UŽ ZAKUKALA,",
      "MÁ PANENKA ZAPLAKALA.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ."
    ]
  }
];

type Phase = 'identification' | 'numbering' | 'assembly' | 'finished';

interface Token {
  id: string;
  text: string;
  cleanWord: string;
  isWord: boolean;
}

const TextCompression: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [levelIdx, setLevelIdx] = useState(0);
  const [phase, setPhase] = useState<Phase>('identification');
  const [dictionary, setDictionary] = useState<{ word: string; code: number | null }[]>([]);
  const [selectedIndices, setSelectedIndices] = useState<Set<string>>(new Set());
  const [identifiedWords, setIdentifiedWords] = useState<Set<string>>(new Set());
  const [assemblyState, setAssemblyState] = useState<{ [tokenId: string]: string | number }>({});
  const [activeAssemblyToken, setActiveAssemblyToken] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  const level = LEVELS[levelIdx];

  const tokensMatrix: Token[][] = useMemo(() => {
    return level.lines.map((line, lIdx) => {
      const parts = line.split(/(\s+)/);
      return parts.map((part, pIdx) => {
        const isWord = /[A-ZČŠŽŘĎŤŇŮÚ]+/.test(part.toUpperCase());
        const cleanWord = part.trim().replace(/[,.?]/g, '').toUpperCase();
        return { id: `${lIdx}-${pIdx}`, text: part, cleanWord, isWord };
      });
    });
  }, [level]);

  const allTokens = useMemo(() => tokensMatrix.flat(), [tokensMatrix]);
  const allWords = useMemo(() => allTokens.filter(t => t.isWord), [allTokens]);

  const duplicateWords = useMemo(() => {
    const counts: { [word: string]: number } = {};
    allWords.forEach(w => { counts[w.cleanWord] = (counts[w.cleanWord] || 0) + 1; });
    return Object.keys(counts).filter(w => counts[w] > 1);
  }, [allWords]);

  const nonEncodableWords = useMemo(() => {
    return Array.from(new Set(allWords.filter(w => !duplicateWords.includes(w.cleanWord)).map(w => w.text)));
  }, [allWords, duplicateWords]);

  // Added missing stats calculation to fix the reference error on line 361
  const stats = useMemo(() => {
    const originalCharCount = level.lines.join('').length;
    if (originalCharCount === 0) return { savings: 0 };

    let compressedCharCount = 0;
    allTokens.forEach(t => {
      if (!t.isWord) {
        compressedCharCount += t.text.length;
      } else {
        const val = assemblyState[t.id];
        if (typeof val === 'number') {
          compressedCharCount += val.toString().length + 1; // e.g., "#1"
        } else if (typeof val === 'string') {
          compressedCharCount += val.length;
        } else {
          // If not assembled yet, assume original length
          compressedCharCount += t.text.length;
        }
      }
    });

    // Add dictionary overhead (word length + code representation length + estimated metadata overhead)
    dictionary.forEach(item => {
      compressedCharCount += item.word.length + (item.code?.toString().length || 1) + 1;
    });

    const savings = Math.max(0, Math.round((1 - compressedCharCount / originalCharCount) * 100));
    return { savings };
  }, [level, allTokens, assemblyState, dictionary]);

  useEffect(() => {
    setPhase('identification');
    setDictionary([]);
    setSelectedIndices(new Set());
    setIdentifiedWords(new Set());
    setAssemblyState({});
    setFeedback(null);
  }, [levelIdx]);

  // FÁZE 1: Identifikace
  const handleWordClickId = (token: Token) => {
    if (phase !== 'identification' || !token.isWord || identifiedWords.has(token.cleanWord)) return;
    const newSelected = new Set(selectedIndices);
    if (newSelected.has(token.id)) newSelected.delete(token.id);
    else newSelected.add(token.id);
    setSelectedIndices(newSelected);
  };

  const addToDictionary = () => {
    if (selectedIndices.size === 0) return;
    const selectedTokens = allTokens.filter(t => selectedIndices.has(t.id));
    const word = selectedTokens[0].cleanWord;

    // Kontrola, zda jsou všechna označená slova stejná
    if (!selectedTokens.every(t => t.cleanWord === word)) {
      setFeedback({ type: 'error', message: 'Označil jsi různá slova! Musíš vybrat vždy jen výskyty stejného slova.' });
      return;
    }

    // Kontrola, zda jsou označeny VŠECHNY výskyty
    const totalOccurrences = allWords.filter(t => t.cleanWord === word).length;
    if (selectedIndices.size !== totalOccurrences) {
      setFeedback({ type: 'error', message: `Slovo ${word} se v textu vyskytuje ${totalOccurrences}x, ty jsi jich označil jen ${selectedIndices.size}.` });
      return;
    }

    if (totalOccurrences < 2) {
      setFeedback({ type: 'error', message: 'Toto slovo se neopakuje, nelze ho dát do slovníku.' });
      return;
    }

    setDictionary(prev => [...prev, { word, code: null }]);
    setIdentifiedWords(prev => new Set(prev).add(word));
    setSelectedIndices(new Set());
    setFeedback({ type: 'success', message: `Slovo ${word} uloženo do slovníku.` });
  };

  const finishIdentification = () => {
    if (identifiedWords.size < duplicateWords.length) {
      setFeedback({ type: 'error', message: 'Ještě jsi nenašel všechna opakující se slova!' });
      return;
    }
    setPhase('numbering');
    setFeedback({ type: 'success', message: 'Výborně! Teď očisluj slova ve slovníku podle toho, jak se poprvé objevují v textu.' });
  };

  // FÁZE 2: Číslování
  const setWordCode = (index: number, val: string) => {
    const code = val === '' ? null : parseInt(val);
    setDictionary(prev => prev.map((item, i) => i === index ? { ...item, code } : item));
  };

  const validateNumbering = () => {
    const sortedWordsInText: string[] = [];
    allWords.forEach(w => {
      if (duplicateWords.includes(w.cleanWord) && !sortedWordsInText.includes(w.cleanWord)) {
        sortedWordsInText.push(w.cleanWord);
      }
    });

    let errors = 0;
    dictionary.forEach(item => {
      const correctCode = sortedWordsInText.indexOf(item.word) + 1;
      if (item.code !== correctCode) errors++;
    });

    if (errors > 0) {
      setFeedback({ type: 'error', message: 'Pořadí kódů není správné. Sleduj text shora dolů.' });
    } else {
      setPhase('assembly');
      setFeedback({ type: 'success', message: 'Slovník je správně očíslován! Teď sestav zkomprimovanou báseň.' });
    }
  };

  // FÁZE 3: Sestavení
  const handleAssemblySelect = (val: string | number) => {
    if (!activeAssemblyToken) return;
    setAssemblyState(prev => ({ ...prev, [activeAssemblyToken]: val }));
    setActiveAssemblyToken(null);
  };

  const checkFinal = () => {
    let errors = 0;
    allTokens.forEach(t => {
      if (!t.isWord) return;
      const userVal = assemblyState[t.id];
      const dictItem = dictionary.find(d => d.word === t.cleanWord);
      if (dictItem) {
        if (userVal !== dictItem.code) errors++;
      } else {
        if (userVal !== t.text) errors++;
      }
    });

    if (errors === 0) {
      setPhase('finished');
      setFeedback(null);
    } else {
      setFeedback({ type: 'error', message: `Máš tam ještě ${errors} chyb. Zkontroluj hlavně kódy.` });
    }
  };

  return (
    <div className="w-full max-w-7xl flex flex-col gap-6 items-center animate-in fade-in duration-500 pb-20 px-4">
      {/* Horní navigace */}
      <div className="w-full bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col md:flex-row items-center justify-between gap-6">
        <button onClick={onBack} className="flex items-center text-gray-400 hover:text-blue-600 transition-colors font-black uppercase text-xs tracking-widest shrink-0">
          <ArrowLeft className="w-5 h-5 mr-2" /> Zpět
        </button>

        <div className="flex gap-2">
          {LEVELS.map((l, idx) => (
            <button key={l.id} onClick={() => setLevelIdx(idx)} className={`px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${levelIdx === idx ? 'bg-blue-600 text-white' : 'bg-blue-50 text-blue-600'}`}>{l.title}</button>
          ))}
        </div>

        <div className="flex items-center gap-4 bg-blue-50 px-5 py-3 rounded-2xl border border-blue-100">
          <Zap className="w-5 h-5 text-blue-600" />
          <div className="text-left">
            <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest leading-none">Fáze</p>
            <p className="text-xs font-black text-blue-900 uppercase tracking-tight">
              {phase === 'identification' ? '1. Identifikace' : phase === 'numbering' ? '2. Číslování' : phase === 'assembly' ? '3. Sestavování' : 'Hotovo'}
            </p>
          </div>
        </div>
      </div>

      {feedback && (
        <div className={`w-full p-4 rounded-2xl border-2 flex items-center gap-3 animate-in slide-in-from-top duration-300 ${feedback.type === 'success' ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800'}`}>
          {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          <span className="font-bold text-sm uppercase tracking-tight">{feedback.message}</span>
        </div>
      )}

      {/* Hlavní obsah dle fází */}
      {phase === 'identification' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 w-full">
          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100">
            <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight mb-6">1. Najdi všechny výskyty jednoho slova</h3>
            <div className="space-y-4 font-mono text-lg">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-gray-50/50 p-4 rounded-2xl">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre">{t.text}</span>;
                    const isSelected = selectedIndices.has(t.id);
                    const isDone = identifiedWords.has(t.cleanWord);
                    return (
                      <button key={t.id} onClick={() => handleWordClickId(t)} className={`px-1.5 py-0.5 rounded-lg transition-all font-black ${isDone ? 'bg-emerald-100 text-emerald-700 opacity-50 cursor-default' : isSelected ? 'bg-blue-600 text-white shadow-md' : 'hover:bg-blue-100 text-gray-700'}`}>
                        {t.text}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
            <button onClick={addToDictionary} className="w-full mt-8 py-4 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-2xl shadow-lg flex items-center justify-center gap-2 uppercase tracking-widest text-sm">
              <PlusCircle className="w-5 h-5" /> Vložit do slovníku
            </button>
          </div>

          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-blue-100 flex flex-col">
            <h3 className="text-xl font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
              <Hash className="w-6 h-6 text-blue-600" /> Slovník
            </h3>
            <div className="flex-1 space-y-3">
              {dictionary.length === 0 ? (
                <div className="py-20 text-center text-gray-300 font-bold uppercase text-xs tracking-widest border-2 border-dashed rounded-3xl">Zatím prázdné</div>
              ) : (
                dictionary.map((item, idx) => (
                  <div key={idx} className="flex items-center gap-4 p-4 bg-blue-50 rounded-2xl animate-in slide-in-from-right duration-300">
                    <div className="w-10 h-10 bg-blue-100 text-blue-600 font-black rounded-xl flex items-center justify-center">?</div>
                    <span className="font-black text-blue-900 uppercase">{item.word}</span>
                  </div>
                ))
              )}
            </div>
            {identifiedWords.size === duplicateWords.length && identifiedWords.size > 0 && (
              <button onClick={finishIdentification} className="w-full mt-6 py-4 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-2xl shadow-lg flex items-center justify-center gap-2 uppercase tracking-widest text-sm">
                Vše nalezeno, pokračovat <ArrowRight className="w-5 h-5" />
              </button>
            )}
          </div>
        </div>
      )}

      {phase === 'numbering' && (
        <div className="w-full max-w-2xl bg-white p-10 rounded-[3rem] shadow-2xl border border-blue-100 animate-in zoom-in duration-500">
          <h3 className="text-2xl font-black text-gray-800 mb-8 uppercase tracking-tighter text-center">2. Přiřaď kódům čísla (1, 2, 3...)</h3>
          <p className="text-sm text-gray-500 mb-8 text-center font-medium">Sleduj text písničky a přiřaď slova ve slovníku číslu podle toho, v jakém pořadí se v textu poprvé objeví.</p>
          <div className="space-y-4">
            {dictionary.map((item, idx) => (
              <div key={idx} className="flex items-center justify-between p-5 bg-blue-50 rounded-3xl border border-blue-100">
                <span className="font-black text-blue-900 text-lg uppercase tracking-tight">{item.word}</span>
                <div className="flex items-center gap-3">
                  <span className="text-blue-400 font-black">KÓD #</span>
                  <input type="number" value={item.code || ''} onChange={(e) => setWordCode(idx, e.target.value)} className="w-16 p-3 bg-white border-2 border-blue-200 rounded-xl text-center font-black text-blue-600 outline-none focus:border-blue-500" placeholder="?" />
                </div>
              </div>
            ))}
          </div>
          <button onClick={validateNumbering} className="w-full mt-10 py-5 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-3xl shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest">
            Zkontrolovat očíslování <ArrowRight className="w-5 h-5" />
          </button>
        </div>
      )}

      {phase === 'assembly' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 w-full items-start">
          {/* Levý sloupec: Původní text */}
          <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col">
            <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4">Originální text</h4>
            <div className="space-y-3 font-mono text-sm opacity-60">
              {level.lines.map((line, i) => <div key={i} className="bg-gray-50 p-2 rounded-lg">{line}</div>)}
            </div>
          </div>

          {/* Střední sloupec: Stavební prvky */}
          <div className="bg-blue-900 p-6 rounded-[2.5rem] shadow-xl text-white flex flex-col gap-6">
            <h4 className="text-xs font-black text-blue-300 uppercase tracking-widest">Kódy ze slovníku</h4>
            <div className="grid grid-cols-2 gap-2">
              {dictionary.map(item => (
                <button key={item.code} onClick={() => handleAssemblySelect(item.code!)} className="p-3 bg-blue-800 hover:bg-blue-700 rounded-xl flex items-center gap-2 border border-blue-700 transition-colors">
                  <span className="w-6 h-6 bg-blue-500 text-white rounded-md flex items-center justify-center text-[10px] font-black">#{item.code}</span>
                  <span className="text-[10px] font-black uppercase truncate">{item.word}</span>
                </button>
              ))}
            </div>

            <h4 className="text-xs font-black text-blue-300 uppercase tracking-widest mt-4">Slova bez kódu</h4>
            <div className="flex flex-wrap gap-2">
              {nonEncodableWords.map(word => (
                <button key={word} onClick={() => handleAssemblySelect(word)} className="px-3 py-2 bg-gray-800 hover:bg-gray-700 rounded-lg text-[10px] font-black uppercase border border-gray-700 transition-colors">{word}</button>
              ))}
            </div>
          </div>

          {/* Pravý sloupec: Sestavování */}
          <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border-4 border-emerald-100 flex flex-col">
            <h4 className="text-xs font-black text-emerald-600 uppercase tracking-widest mb-4">Komprimovaný zápis</h4>
            <div className="space-y-4 font-mono text-sm">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-emerald-50/50 p-3 rounded-xl border border-emerald-100 min-h-[48px]">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-gray-300">{t.text}</span>;
                    const val = assemblyState[t.id];
                    const isActive = activeAssemblyToken === t.id;
                    return (
                      <button key={t.id} onClick={() => setActiveAssemblyToken(t.id)} className={`min-w-[40px] px-2 py-1 mx-0.5 rounded-md font-black transition-all border-2 ${isActive ? 'bg-blue-100 border-blue-500 animate-pulse' : val ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white border-emerald-200 text-emerald-300'}`}>
                        {val ? (typeof val === 'number' ? `#${val}` : val) : '???'}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
            <button onClick={checkFinal} className="w-full mt-8 py-4 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-2xl shadow-lg flex items-center justify-center gap-2 uppercase tracking-widest text-sm">
              Zkontrolovat kompresi
            </button>
          </div>
        </div>
      )}

      {phase === 'finished' && (
        <div className="max-w-md w-full bg-white p-12 rounded-[3.5rem] shadow-2xl border-4 border-emerald-100 text-center animate-in zoom-in duration-500">
          <div className="w-24 h-24 bg-gradient-to-tr from-emerald-400 to-teal-500 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-xl rotate-12">
            <Trophy className="w-12 h-12 text-white" />
          </div>
          <h2 className="text-4xl font-black text-gray-900 mb-2 uppercase tracking-tighter">Vynikající!</h2>
          <p className="text-gray-500 mb-8 font-medium italic">Dokonale jsi zkomprimoval text a ušetřil <span className="text-emerald-600 font-black">{stats.savings}%</span> místa!</p>
          <div className="space-y-4">
            <button onClick={() => setLevelIdx((levelIdx + 1) % LEVELS.length)} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl uppercase tracking-widest">Další text</button>
            <button onClick={onBack} className="w-full py-4 bg-gray-50 text-gray-500 font-bold rounded-[2rem] uppercase tracking-widest text-xs">Menu</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default TextCompression;

import React, { useState, useMemo, useEffect } from 'react';
import { ArrowLeft, CheckCircle2, RefreshCcw, HelpCircle, ArrowRight, Hash, FileText, Zap, Trophy, PlusCircle, AlertCircle, Sparkles } from 'lucide-react';

interface TextLevel {
  id: number;
  title: string;
  lines: string[];
}

const LEVELS: TextLevel[] = [
  {
    id: 1,
    title: "Prší, prší",
    lines: [
      "PRŠÍ, PRŠÍ, JEN SE LEJE.",
      "KAM KONÍČKY POJEDEME?",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ.",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ."
    ]
  },
  {
    id: 2,
    title: "Kukačka",
    lines: [
      "KUKAČKA UŽ ZAKUKALA,",
      "MÁ PANENKA ZAPLAKALA.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ."
    ]
  }
];

type Phase = 'identification' | 'numbering' | 'assembly' | 'finished';

interface Token {
  id: string;
  text: string;
  cleanWord: string;
  isWord: boolean;
}

const TextCompression: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [levelIdx, setLevelIdx] = useState(0);
  const [phase, setPhase] = useState<Phase>('identification');
  const [dictionary, setDictionary] = useState<{ word: string; code: number | null }[]>([]);
  const [selectedIndices, setSelectedIndices] = useState<Set<string>>(new Set());
  const [identifiedWords, setIdentifiedWords] = useState<Set<string>>(new Set());
  const [assemblyState, setAssemblyState] = useState<{ [tokenId: string]: string | number }>({});
  const [activeAssemblyToken, setActiveAssemblyToken] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  const level = LEVELS[levelIdx];

  const tokensMatrix: Token[][] = useMemo(() => {
    return level.lines.map((line, lIdx) => {
      const parts = line.split(/(\s+)/);
      return parts.map((part, pIdx) => {
        const isWord = /[A-ZČŠŽŘĎŤŇŮÚ]+/.test(part.toUpperCase());
        const cleanWord = part.trim().replace(/[,.?]/g, '').toUpperCase();
        return { id: `${lIdx}-${pIdx}`, text: part, cleanWord, isWord };
      });
    });
  }, [level]);

  const allTokens = useMemo(() => tokensMatrix.flat(), [tokensMatrix]);
  const allWords = useMemo(() => allTokens.filter(t => t.isWord), [allTokens]);

  const duplicateWords = useMemo(() => {
    const counts: { [word: string]: number } = {};
    allWords.forEach(w => { counts[w.cleanWord] = (counts[w.cleanWord] || 0) + 1; });
    return Object.keys(counts).filter(w => counts[w] > 1);
  }, [allWords]);

  const nonEncodableWords = useMemo(() => {
    const dups = new Set(duplicateWords);
    return Array.from(new Set(allWords.filter(w => !dups.has(w.cleanWord)).map(w => w.text)));
  }, [allWords, duplicateWords]);

  useEffect(() => {
    setPhase('identification');
    setDictionary([]);
    setSelectedIndices(new Set());
    setIdentifiedWords(new Set());
    setAssemblyState({});
    setFeedback(null);
  }, [levelIdx]);

  const stats = useMemo(() => {
    const originalLen = level.lines.join('\n').length;
    if (originalLen === 0) return { savings: 0 };

    let compressedLen = 0;
    allTokens.forEach(t => {
      if (!t.isWord) {
        compressedLen += t.text.length;
      } else {
        const val = assemblyState[t.id];
        if (typeof val === 'number') compressedLen += val.toString().length + 1;
        else compressedLen += (val || t.text).length;
      }
    });

    const dictSize = dictionary.reduce((acc, curr) => acc + curr.word.length + 4, 0);
    const total = compressedLen + dictSize;
    return { 
        original: originalLen, 
        compressed: total, 
        savings: Math.max(0, Math.round(((originalLen - total) / originalLen) * 100)) 
    };
  }, [level, allTokens, assemblyState, dictionary]);

  // Phase 1: Identification
  const handleWordClickId = (token: Token) => {
    if (phase !== 'identification' || !token.isWord || identifiedWords.has(token.cleanWord)) return;
    const newSelected = new Set(selectedIndices);
    if (newSelected.has(token.id)) newSelected.delete(token.id);
    else newSelected.add(token.id);
    setSelectedIndices(newSelected);
  };

  const addToDictionary = () => {
    if (selectedIndices.size === 0) return;
    const selectedTokens = allTokens.filter(t => selectedIndices.has(t.id));
    const word = selectedTokens[0].cleanWord;

    if (!selectedTokens.every(t => t.cleanWord === word)) {
      setFeedback({ type: 'error', message: 'Můžeš vybrat jen výskyty stejného slova!' });
      return;
    }

    const totalOccurrences = allWords.filter(t => t.cleanWord === word).length;
    if (selectedIndices.size !== totalOccurrences) {
      setFeedback({ type: 'error', message: `Slovo ${word} se v textu vyskytuje ${totalOccurrences}x, označ všechny!` });
      return;
    }

    if (totalOccurrences < 2) {
      setFeedback({ type: 'error', message: 'Toto slovo se neopakuje!' });
      return;
    }

    setDictionary(prev => [...prev, { word, code: null }]);
    setIdentifiedWords(prev => new Set(prev).add(word));
    setSelectedIndices(new Set());
    setFeedback({ type: 'success', message: `Slovo ${word} přidáno do slovníku.` });
  };

  const finishIdentification = () => {
    if (identifiedWords.size < duplicateWords.length) {
      setFeedback({ type: 'error', message: 'Ještě jsi nenašel všechna opakující se slova!' });
      return;
    }
    setPhase('numbering');
    setFeedback({ type: 'success', message: 'Všechny duplicity nalezeny. Teď jim ve slovníku přiřaď čísla.' });
  };

  // Phase 2: Numbering
  const setWordCode = (index: number, val: string) => {
    const code = val === '' ? null : parseInt(val);
    setDictionary(prev => prev.map((item, i) => i === index ? { ...item, code } : item));
  };

  const validateNumbering = () => {
    const sortedWordsInText: string[] = [];
    allWords.forEach(w => {
      if (duplicateWords.includes(w.cleanWord) && !sortedWordsInText.includes(w.cleanWord)) {
        sortedWordsInText.push(w.cleanWord);
      }
    });

    let errors = 0;
    dictionary.forEach(item => {
      const correctCode = sortedWordsInText.indexOf(item.word) + 1;
      if (item.code !== correctCode) errors++;
    });

    if (errors > 0) {
      setFeedback({ type: 'error', message: 'Pořadí kódů není správné. Sleduj text shora dolů.' });
    } else {
      setPhase('assembly');
      setFeedback({ type: 'success', message: 'Očíslování je správně! Teď sestav zkomprimovaný zápis.' });
    }
  };

  // Phase 3: Assembly
  const handleAssemblySelect = (val: string | number) => {
    if (!activeAssemblyToken) return;
    setAssemblyState(prev => ({ ...prev, [activeAssemblyToken]: val }));
    setActiveAssemblyToken(null);
  };

  const checkFinal = () => {
    let errors = 0;
    allTokens.forEach(t => {
      if (!t.isWord) return;
      const userVal = assemblyState[t.id];
      const dictItem = dictionary.find(d => d.word === t.cleanWord);
      if (dictItem) {
        if (userVal !== dictItem.code) errors++;
      } else {
        if (userVal !== t.text) errors++;
      }
    });

    if (errors === 0) {
      setPhase('finished');
      setFeedback(null);
    } else {
      setFeedback({ type: 'error', message: `Máš tam ještě ${errors} chyb.` });
    }
  };

  return (
    <div className="w-full max-w-7xl flex flex-col gap-6 items-center animate-in fade-in duration-500 pb-20 px-4">
      {/* Header */}
      <div className="w-full bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col md:flex-row items-center justify-between gap-6">
        <button onClick={onBack} className="flex items-center text-gray-400 hover:text-blue-600 transition-colors font-black uppercase text-xs tracking-widest shrink-0">
          <ArrowLeft className="w-5 h-5 mr-2" /> Zpět
        </button>

        <div className="flex gap-2">
          {LEVELS.map((l, idx) => (
            <button key={l.id} onClick={() => setLevelIdx(idx)} className={`px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${levelIdx === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-blue-50 text-blue-600'}`}>{l.title}</button>
          ))}
        </div>

        <div className="flex items-center gap-4 bg-blue-50 px-5 py-3 rounded-2xl border border-blue-100">
          <Zap className="w-5 h-5 text-blue-600" />
          <div className="text-left">
            <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest leading-none">Aktuální fáze</p>
            <p className="text-xs font-black text-blue-900 uppercase tracking-tight">
              {phase === 'identification' ? '1. Hledání slov' : phase === 'numbering' ? '2. Číslování slovníku' : phase === 'assembly' ? '3. Komprese' : 'Hotovo'}
            </p>
          </div>
        </div>
      </div>

      {feedback && (
        <div className={`w-full p-4 rounded-2xl border-2 flex items-center gap-3 animate-in slide-in-from-top duration-300 ${feedback.type === 'success' ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800'}`}>
          {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          <span className="font-bold text-sm uppercase tracking-tight">{feedback.message}</span>
        </div>
      )}

      {/* Main UI */}
      {(phase === 'identification' || phase === 'numbering') && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 w-full">
          {/* Left: Poem */}
          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100 min-h-[500px]">
            <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight mb-8 flex items-center gap-3">
              <div className="w-3 h-8 bg-blue-500 rounded-full"></div>
              {phase === 'identification' ? 'Najdi všechna opakující se slova' : 'Referenční text'}
            </h3>
            <div className="space-y-4 font-mono text-lg">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-gray-50/50 p-4 rounded-2xl border border-transparent">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre">{t.text}</span>;
                    const isSelected = selectedIndices.has(t.id);
                    const isDone = identifiedWords.has(t.cleanWord);
                    return (
                      <button 
                        key={t.id} 
                        disabled={phase !== 'identification' || isDone}
                        onClick={() => handleWordClickId(t)} 
                        className={`px-1.5 py-0.5 rounded-lg transition-all font-black ${
                          isDone ? 'bg-emerald-100 text-emerald-700 opacity-60' : 
                          isSelected ? 'bg-blue-600 text-white shadow-md scale-105' : 
                          phase === 'identification' ? 'hover:bg-blue-100 text-gray-700' : 'text-gray-400'
                        }`}
                      >
                        {t.text}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
          </div>

          {/* Right: Dictionary / Numbering */}
          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-blue-100 flex flex-col">
            <h3 className="text-xl font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
              <Hash className="w-6 h-6 text-blue-600" /> 
              {phase === 'identification' ? 'Slovník' : 'Očisluj kódy (1, 2, 3...)'}
            </h3>
            <div className="flex-1 space-y-3">
              {dictionary.length === 0 ? (
                <div className="py-20 text-center text-gray-300 font-bold uppercase text-xs tracking-widest border-2 border-dashed rounded-3xl flex flex-col items-center gap-4">
                  <FileText className="w-12 h-12 opacity-10" />
                  Slovník se vytvoří identifikací slov vlevo
                </div>
              ) : (
                dictionary.map((item, idx) => (
                  <div key={idx} className="flex items-center justify-between p-4 bg-blue-50 rounded-2xl border border-blue-100 animate-in slide-in-from-right duration-300">
                    <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-blue-600 text-white font-black rounded-xl flex items-center justify-center shadow-sm">
                            {item.code ? `#${item.code}` : '?'}
                        </div>
                        <span className="font-black text-blue-900 uppercase text-lg">{item.word}</span>
                    </div>
                    {phase === 'numbering' && (
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Kód #</span>
                            <input 
                                type="number" 
                                value={item.code || ''} 
                                onChange={(e) => setWordCode(idx, e.target.value)}
                                className="w-16 p-3 bg-white border-2 border-blue-200 rounded-xl text-center font-black text-blue-600 outline-none focus:border-blue-500 transition-all"
                                placeholder="?"
                            />
                        </div>
                    )}
                  </div>
                ))
              )}
            </div>

            <div className="mt-8 space-y-4">
              {phase === 'identification' && (
                <>
                  <button onClick={addToDictionary} className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all active:scale-95">
                    <PlusCircle className="w-5 h-5" /> Vložit do slovníku
                  </button>
                  {identifiedWords.size === duplicateWords.length && identifiedWords.size > 0 && (
                    <button onClick={finishIdentification} className="w-full py-4 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-lg flex items-center justify-center gap-3 uppercase tracking-widest text-xs transition-all">
                      Všechny duplicity nalezeny <ArrowRight className="w-4 h-4" />
                    </button>
                  )}
                </>
              )}
              {phase === 'numbering' && (
                <button onClick={validateNumbering} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all active:scale-95">
                  Zkontrolovat očíslování <CheckCircle2 className="w-5 h-5" />
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {phase === 'assembly' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 w-full items-start">
          {/* Column 1: Original reference */}
          <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col">
            <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                <FileText className="w-4 h-4" /> Původní báseň
            </h4>
            <div className="space-y-3 font-mono text-sm opacity-50 bg-gray-50/50 p-4 rounded-2xl">
              {level.lines.map((line, i) => <div key={i} className="py-1 border-b border-gray-100 last:border-0">{line}</div>)}
            </div>
          </div>

          {/* Column 2: Tools Palette */}
          <div className="bg-blue-900 p-8 rounded-[3rem] shadow-xl text-white flex flex-col gap-8 min-h-[500px]">
            <div>
                <h4 className="text-[10px] font-black text-blue-300 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Hash className="w-4 h-4" /> Kódy ze slovníku
                </h4>
                <div className="grid grid-cols-2 gap-3">
                    {dictionary.map(item => (
                        <button 
                            key={item.code} 
                            onClick={() => handleAssemblySelect(item.code!)} 
                            className="p-3 bg-blue-800 hover:bg-blue-700 active:scale-95 rounded-2xl flex items-center gap-3 border border-blue-700 transition-all shadow-sm"
                        >
                            <span className="w-8 h-8 bg-blue-500 text-white rounded-xl flex items-center justify-center text-xs font-black">#{item.code}</span>
                            <span className="text-[10px] font-black uppercase truncate">{item.word}</span>
                        </button>
                    ))}
                </div>
            </div>

            <div className="mt-auto">
                <h4 className="text-[10px] font-black text-blue-300 uppercase tracking-widest mb-4">Slova bez kódu</h4>
                <div className="flex flex-wrap gap-2">
                    {nonEncodableWords.map(word => (
                        <button 
                            key={word} 
                            onClick={() => handleAssemblySelect(word)} 
                            className="px-4 py-3 bg-gray-800 hover:bg-gray-700 active:scale-95 rounded-xl text-[10px] font-black uppercase border border-gray-700 transition-all"
                        >
                            {word}
                        </button>
                    ))}
                </div>
            </div>
          </div>

          {/* Column 3: Construction Zone */}
          <div className="bg-white p-8 rounded-[3rem] shadow-xl border-4 border-emerald-100 flex flex-col">
            <h4 className="text-xs font-black text-emerald-600 uppercase tracking-widest mb-6 flex justify-between items-center">
                <span>Zkomprimovaný zápis</span>
                <span className="bg-emerald-50 px-3 py-1 rounded-full text-[10px]">Úspora: {stats.savings}%</span>
            </h4>
            <div className="space-y-4 font-mono text-sm mb-8">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-emerald-50/50 p-3 rounded-2xl border border-emerald-100 min-h-[56px] gap-1">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-gray-300">{t.text}</span>;
                    const val = assemblyState[t.id];
                    const isActive = activeAssemblyToken === t.id;
                    return (
                      <button 
                        key={t.id} 
                        onClick={() => setActiveAssemblyToken(t.id)} 
                        className={`min-w-[48px] h-10 px-2 rounded-xl font-black transition-all border-2 text-xs ${
                            isActive ? 'bg-blue-50 border-blue-500 shadow-md ring-4 ring-blue-50 z-10 scale-110' : 
                            val ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm' : 
                            'bg-white border-emerald-100 text-emerald-200 border-dashed hover:border-emerald-300'
                        }`}
                      >
                        {val ? (typeof val === 'number' ? `#${val}` : val) : '???'}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
            <button onClick={checkFinal} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all">
              <CheckCircle2 className="w-5 h-5" /> Ověřit výsledek
            </button>
          </div>
        </div>
      )}

      {phase === 'finished' && (
        <div className="max-w-md w-full bg-white p-12 rounded-[3.5rem] shadow-2xl border-4 border-emerald-100 text-center animate-in zoom-in duration-500">
          <div className="w-24 h-24 bg-gradient-to-tr from-emerald-400 to-teal-500 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-xl rotate-12">
            <Trophy className="w-12 h-12 text-white" />
          </div>
          <h2 className="text-4xl font-black text-gray-900 mb-2 uppercase tracking-tighter">Vynikající!</h2>
          <p className="text-gray-500 mb-8 font-medium italic">Dokonale jsi zkomprimoval text a ušetřil <span className="text-emerald-600 font-black">{stats.savings}%</span> místa!</p>
          <div className="space-y-4">
            <button onClick={() => setLevelIdx((levelIdx + 1) % LEVELS.length)} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl uppercase tracking-widest">Další text</button>
            <button onClick={onBack} className="w-full py-4 bg-gray-50 text-gray-500 font-bold rounded-[2rem] uppercase tracking-widest text-xs">Menu</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default TextCompression;

import React, { useState, useMemo, useEffect } from 'react';
import { ArrowLeft, CheckCircle2, RefreshCcw, HelpCircle, ArrowRight, Hash, FileText, Zap, Trophy, PlusCircle, AlertCircle, Sparkles } from 'lucide-react';

interface TextLevel {
  id: number;
  title: string;
  lines: string[];
}

const LEVELS: TextLevel[] = [
  {
    id: 1,
    title: "Prší, prší",
    lines: [
      "PRŠÍ, PRŠÍ, JEN SE LEJE.",
      "KAM KONÍČKY POJEDEME?",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ.",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ."
    ]
  },
  {
    id: 2,
    title: "Kukačka",
    lines: [
      "KUKAČKA UŽ ZAKUKALA,",
      "MÁ PANENKA ZAPLAKALA.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ."
    ]
  }
];

type Phase = 'identification' | 'assembly' | 'finished';

interface Token {
  id: string;
  text: string;
  cleanWord: string;
  isWord: boolean;
}

const TextCompression: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [levelIdx, setLevelIdx] = useState(0);
  const [phase, setPhase] = useState<Phase>('identification');
  const [dictionary, setDictionary] = useState<{ word: string; code: number }[]>([]);
  const [selectedIndices, setSelectedIndices] = useState<Set<string>>(new Set());
  const [assemblyState, setAssemblyState] = useState<{ [tokenId: string]: string | number }>({});
  const [activeAssemblyToken, setActiveAssemblyToken] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  const level = LEVELS[levelIdx];

  const tokensMatrix: Token[][] = useMemo(() => {
    return level.lines.map((line, lIdx) => {
      const parts = line.split(/(\s+)/);
      return parts.map((part, pIdx) => {
        const isWord = /[A-ZČŠŽŘĎŤŇŮÚ]+/.test(part.toUpperCase());
        const cleanWord = part.trim().replace(/[,.?]/g, '').toUpperCase();
        return { id: `${lIdx}-${pIdx}`, text: part, cleanWord, isWord };
      });
    });
  }, [level]);

  const allTokens = useMemo(() => tokensMatrix.flat(), [tokensMatrix]);
  const allWords = useMemo(() => allTokens.filter(t => t.isWord), [allTokens]);

  // Seznam slov, která mají duplicitu, seřazený podle prvního výskytu v textu
  const targetDictionaryWords = useMemo(() => {
    const counts: { [word: string]: number } = {};
    allWords.forEach(w => { counts[w.cleanWord] = (counts[w.cleanWord] || 0) + 1; });
    const duplicates = Object.keys(counts).filter(w => counts[w] > 1);

    const wordsInOrder: string[] = [];
    allWords.forEach(w => {
      if (duplicates.includes(w.cleanWord) && !wordsInOrder.includes(w.cleanWord)) {
        wordsInOrder.push(w.cleanWord);
      }
    });
    return wordsInOrder;
  }, [allWords]);

  const nonEncodableWords = useMemo(() => {
    const dups = new Set(targetDictionaryWords);
    return Array.from(new Set(allWords.filter(w => !dups.has(w.cleanWord)).map(w => w.text)));
  }, [allWords, targetDictionaryWords]);

  useEffect(() => {
    setPhase('identification');
    setDictionary([]);
    setSelectedIndices(new Set());
    setAssemblyState({});
    setFeedback(null);
  }, [levelIdx]);

  const stats = useMemo(() => {
    const originalLen = level.lines.join('\n').length;
    if (originalLen === 0) return { savings: 0 };

    let compressedLen = 0;
    allTokens.forEach(t => {
      if (!t.isWord) {
        compressedLen += t.text.length;
      } else {
        const val = assemblyState[t.id];
        if (typeof val === 'number') compressedLen += val.toString().length + 1;
        else compressedLen += (val || t.text).length;
      }
    });

    const dictSize = dictionary.reduce((acc, curr) => acc + curr.word.length + 4, 0);
    const total = compressedLen + dictSize;
    return { 
        original: originalLen, 
        compressed: total, 
        savings: Math.max(0, Math.round(((originalLen - total) / originalLen) * 100)) 
    };
  }, [level, allTokens, assemblyState, dictionary]);

  // Phase 1: Identification
  const handleWordClickId = (token: Token) => {
    if (phase !== 'identification' || !token.isWord) return;

    // Pokud je už ve slovníku, nelze vybrat
    if (dictionary.some(d => d.word === token.cleanWord)) return;

    const newSelected = new Set(selectedIndices);
    if (newSelected.has(token.id)) newSelected.delete(token.id);
    else newSelected.add(token.id);
    setSelectedIndices(newSelected);
  };

  const addToDictionary = () => {
    if (selectedIndices.size === 0) return;
    const selectedTokens = allTokens.filter(t => selectedIndices.has(t.id));
    const word = selectedTokens[0].cleanWord;

    // 1. Musí být vybrány jen instance jednoho slova
    if (!selectedTokens.every(t => t.cleanWord === word)) {
      setFeedback({ type: 'error', message: 'Musíš vybrat výskyty jen jednoho stejného slova!' });
      return;
    }

    // 2. Musí být vybrány VŠECHNY instance toho slova
    const totalOccurrences = allWords.filter(t => t.cleanWord === word).length;
    if (selectedIndices.size !== totalOccurrences) {
      setFeedback({ type: 'error', message: `Slovo ${word} se v textu vyskytuje ${totalOccurrences}x, označ všechny jeho výskyty!` });
      return;
    }

    // 3. Musí to být slovo s duplicitiou
    if (totalOccurrences < 2) {
      setFeedback({ type: 'error', message: 'Toto slovo se neopakuje, nepatří do slovníku.' });
      return;
    }

    // 4. KRITICKÉ: Musí to být DALŠÍ slovo v pořadí výskytu
    const nextTargetWord = targetDictionaryWords[dictionary.length];
    if (word !== nextTargetWord) {
      setFeedback({ type: 'error', message: `Nesprávné pořadí! Musíš přidávat slova tak, jak se poprvé objevují v textu (shora dolů).` });
      return;
    }

    // Vše OK -> Přidat do slovníku s automatickým kódem
    setDictionary(prev => [...prev, { word, code: prev.length + 1 }]);
    setSelectedIndices(new Set());
    setFeedback({ type: 'success', message: `Slovo ${word} uloženo jako kód #${dictionary.length + 1}.` });

    // Pokud už jsou všechna slova ve slovníku, můžeme dál
    if (dictionary.length + 1 === targetDictionaryWords.length) {
      setTimeout(() => {
        setPhase('assembly');
        setFeedback({ type: 'success', message: 'Slovník je kompletní! Nyní sestav zkomprimovanou báseň.' });
      }, 1000);
    }
  };

  // Phase 2: Assembly
  const handleAssemblySelect = (val: string | number) => {
    if (!activeAssemblyToken) return;
    setAssemblyState(prev => ({ ...prev, [activeAssemblyToken]: val }));
    setActiveAssemblyToken(null);
  };

  const checkFinal = () => {
    let errors = 0;
    allTokens.forEach(t => {
      if (!t.isWord) return;
      const userVal = assemblyState[t.id];
      const dictItem = dictionary.find(d => d.word === t.cleanWord);
      if (dictItem) {
        if (userVal !== dictItem.code) errors++;
      } else {
        if (userVal !== t.text) errors++;
      }
    });

    if (errors === 0) {
      setPhase('finished');
      setFeedback(null);
    } else {
      setFeedback({ type: 'error', message: `Máš tam ještě ${errors} chyb. Zkontroluj hlavně kódy u opakujících se slov.` });
    }
  };

  return (
    <div className="w-full max-w-7xl flex flex-col gap-6 items-center animate-in fade-in duration-500 pb-20 px-4">
      {/* Header */}
