          {/* Column 3: Construction Zone */}
          <div className="bg-white p-8 rounded-[3rem] shadow-xl border-4 border-emerald-100 flex flex-col">
            <h4 className="text-xs font-black text-emerald-600 uppercase tracking-widest mb-6 flex justify-between items-center">
                <span>Zkomprimovaný zápis</span>
                <span className="bg-emerald-50 px-3 py-1 rounded-full text-[10px]">Úspora: {stats.savings}%</span>
            </h4>
            <div className="space-y-4 font-mono text-sm mb-8">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-emerald-50/50 p-3 rounded-2xl border border-emerald-100 min-h-[56px] gap-1">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-gray-300">{t.text}</span>;
                    const val = assemblyState[t.id];
                    const isActive = activeAssemblyToken === t.id;
                    return (
                      <button 
                        key={t.id} 
                        onClick={() => setActiveAssemblyToken(t.id)} 
                        className={`min-w-[48px] h-10 px-2 rounded-xl font-black transition-all border-2 text-xs ${
                            isActive ? 'bg-blue-50 border-blue-500 shadow-md ring-4 ring-blue-50 z-10 scale-110' : 
                            val ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm' : 
                            'bg-white border-emerald-100 text-emerald-200 border-dashed hover:border-emerald-300'
                        }`}
                      >
                        {val ? (typeof val === 'number' ? `#${val}` : val) : '???'}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
            <button onClick={checkFinal} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all">
              <CheckCircle2 className="w-5 h-5" /> Ověřit kompresi
            </button>
          </div>
        </div>
      )}

      {/* Success Screen */}
      {phase === 'finished' && (
        <div className="max-w-md w-full bg-white p-12 rounded-[3.5rem] shadow-2xl border-4 border-emerald-100 text-center animate-in zoom-in duration-500">
          <div className="w-24 h-24 bg-gradient-to-tr from-emerald-400 to-teal-500 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-xl rotate-12">
            <Trophy className="w-12 h-12 text-white" />
          </div>
          <h2 className="text-4xl font-black text-gray-900 mb-2 uppercase tracking-tighter">Hotovo!</h2>
          <p className="text-gray-500 mb-8 font-medium italic">Sestavil jsi úsporný zápis písně. <br/> Úspora paměti: <span className="text-emerald-600 font-black">{stats.savings}%</span></p>
          <div className="space-y-4">
            <button onClick={() => setLevelIdx((levelIdx + 1) % LEVELS.length)} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl uppercase tracking-widest">Další text</button>
            <button onClick={onBack} className="w-full py-4 bg-gray-50 text-gray-500 font-bold rounded-[2rem] uppercase tracking-widest text-xs">Zpět do menu</button>
          </div>
        </div>
      )}
    </div>
  );
};

