  setValue: (v: number) => void;
  color: string;
  max: number;
  unit?: string;
}

const ControlSlider: React.FC<ControlSliderProps> = ({ label, value, setValue, color, max, unit = "" }) => {
  const colorMap: Record<string, string> = {
