              </p>
            </div>
          </div>
        </div>

        {/* Komprimovaná mřížka */}
        <div className={`bg-white p-8 rounded-[3rem] shadow-xl border-4 transition-all duration-300 flex flex-col items-center ${
          feedback === 'correct' ? 'border-emerald-500 ring-8 ring-emerald-50' : 
