              className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl shadow-emerald-200 transition-all active:scale-95 uppercase tracking-widest text-sm"
            >
              Zpět do menu
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

