  const targetDictionaryWords = useMemo(() => {
    const counts: { [word: string]: number } = {};
    allWords.forEach(w => { counts[w.cleanWord] = (counts[w.cleanWord] || 0) + 1; });
    const duplicates = Object.keys(counts).filter(w => counts[w] > 1);

    const wordsInOrder: string[] = [];
    allWords.forEach(w => {
      if (duplicates.includes(w.cleanWord) && !wordsInOrder.includes(w.cleanWord)) {
        wordsInOrder.push(w.cleanWord);
      }
    });
    return wordsInOrder;
  }, [allWords]);

  const nonEncodableWords = useMemo(() => {
    const dups = new Set(targetDictionaryWords);
    return Array.from(new Set(allWords.filter(w => !dups.has(w.cleanWord)).map(w => w.text)));
  }, [allWords, targetDictionaryWords]);

  useEffect(() => {
    setPhase('identification');
    setDictionary([]);
    setSelectedIndices(new Set());
    setAssemblyState({});
    setFeedback(null);
    setIsFinalCorrect(false);
  }, [levelIdx]);

  // Opravený výpočet úspory
  const stats = useMemo(() => {
    const originalString = level.lines.join('\n');
    const originalLen = originalString.length;

    if (originalLen === 0) return { savings: 0 };

    // Délka komprimovaného textu: nekomprimovaná slova + mezery/interpunkce + kódy (např. "#1" jsou 2 znaky)
    let compressedTextLen = 0;
    allTokens.forEach(t => {
      if (!t.isWord) {
        compressedTextLen += t.text.length;
      } else {
        const val = assemblyState[t.id];
        if (typeof val === 'number') {
          compressedTextLen += val.toString().length + 1; // # + číslo
        } else {
          compressedTextLen += (val || t.text).length;
        }
      }
    });

    // Délka slovníku: každé slovo + jeho kód + oddělovač (pro zjednodušení: slovo + kód + 2 znaky režie)
    const dictionaryLen = dictionary.reduce((acc, curr) => acc + curr.word.length + curr.code.toString().length + 2, 0);

    const totalCompressed = compressedTextLen + dictionaryLen;
    const savings = Math.max(0, Math.round(((originalLen - totalCompressed) / originalLen) * 100));

    return { originalLen, totalCompressed, savings };
  }, [level, allTokens, assemblyState, dictionary]);

  // PHASE 1 Logic
  const handleWordClickId = (token: Token) => {
    if (phase !== 'identification' || !token.isWord || dictionary.some(d => d.word === token.cleanWord)) return;
    const newSelected = new Set(selectedIndices);
    if (newSelected.has(token.id)) newSelected.delete(token.id);
    else newSelected.add(token.id);
    setSelectedIndices(newSelected);
  };

  const addToDictionary = () => {
    if (selectedIndices.size === 0) return;
    const selectedTokens = allTokens.filter(t => selectedIndices.has(t.id));
    const word = selectedTokens[0].cleanWord;

    if (!selectedTokens.every(t => t.cleanWord === word)) {
      setFeedback({ type: 'error', message: 'Vyber výskyty pouze jednoho stejného slova!' });
      return;
    }

    const totalOccurrences = allWords.filter(t => t.cleanWord === word).length;
    if (selectedIndices.size !== totalOccurrences) {
      setFeedback({ type: 'error', message: `Slovo ${word} se v textu vyskytuje ${totalOccurrences}x, označ všechny!` });
      return;
    }

    if (totalOccurrences < 2) {
      setFeedback({ type: 'error', message: 'Slovo se neopakuje, nepatří do slovníku.' });
      return;
    }

    const nextTargetWord = targetDictionaryWords[dictionary.length];
    if (word !== nextTargetWord) {
      setFeedback({ type: 'error', message: `Postupuj podle pořadí! První neuložená duplicita je: ${nextTargetWord}` });
      return;
    }

    setDictionary(prev => [...prev, { word, code: prev.length + 1 }]);
    setSelectedIndices(new Set());
    setFeedback({ type: 'success', message: `Slovo ${word} uloženo pod kódem #${dictionary.length + 1}.` });

    if (dictionary.length + 1 === targetDictionaryWords.length) {
      setTimeout(() => {
        setPhase('assembly');
        setFeedback({ type: 'success', message: 'Slovník hotov! Teď přetáhni prvky do komprimovaného zápisu.' });
      }, 800);
    }
  };

  // DRAG AND DROP Logic
  const onDragStart = (e: React.DragEvent, value: string | number) => {
    e.dataTransfer.setData("text/plain", value.toString());
  };

  const onDrop = (e: React.DragEvent, tokenId: string) => {
    e.preventDefault();
    const data = e.dataTransfer.getData("text/plain");
    const value = isNaN(Number(data)) ? data : Number(data);
    setAssemblyState(prev => ({ ...prev, [tokenId]: value }));
  };

  const checkFinal = () => {
    let errors = 0;
    allTokens.forEach(t => {
      if (!t.isWord) return;
      const userVal = assemblyState[t.id];
      const dictItem = dictionary.find(d => d.word === t.cleanWord);
      if (dictItem) {
        if (userVal !== dictItem.code) errors++;
      } else {
        if (userVal !== t.text) errors++;
      }
    });

    if (errors === 0) {
      setFeedback({ type: 'success', message: `Vynikající! Úspora paměti je ${stats.savings}%.` });
      setIsFinalCorrect(true);
    } else {
      setFeedback({ type: 'error', message: `Někde máš chybu (${errors}x). Zkontroluj hlavně kódy.` });
      setIsFinalCorrect(false);
    }
  };

  return (
    <div className="w-full max-w-7xl flex flex-col gap-6 items-center animate-in fade-in duration-500 pb-20 px-4">
      {/* Header */}
      <div className="w-full bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col md:flex-row items-center justify-between gap-6">
        <button onClick={onBack} className="flex items-center text-gray-400 hover:text-blue-600 transition-colors font-black uppercase text-xs tracking-widest shrink-0">
          <ArrowLeft className="w-5 h-5 mr-2" /> Zpět
        </button>

        <div className="flex gap-2">
          {LEVELS.map((l, idx) => (
            <button key={l.id} onClick={() => setLevelIdx(idx)} className={`px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${levelIdx === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-blue-50 text-blue-600'}`}>{l.title}</button>
          ))}
        </div>

        <div className="flex items-center gap-4 bg-blue-50 px-5 py-3 rounded-2xl border border-blue-100">
          <Zap className="w-5 h-5 text-blue-600" />
          <div className="text-left">
            <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest leading-none">Fáze úkolu</p>
            <p className="text-xs font-black text-blue-900 uppercase tracking-tight">
              {phase === 'identification' ? '1. Tvorba slovníku' : '2. Drag & Drop komprese'}
            </p>
          </div>
        </div>
      </div>

      {feedback && (
        <div className={`w-full p-4 rounded-2xl border-2 flex items-center gap-3 animate-in slide-in-from-top duration-300 ${feedback.type === 'success' ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800'}`}>
          {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          <span className="font-bold text-sm uppercase tracking-tight">{feedback.message}</span>
        </div>
      )}

      {/* Identifikace - První krok */}
      {phase === 'identification' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 w-full">
          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100">
            <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight flex items-center gap-3 mb-6">
                <div className="w-3 h-8 bg-blue-500 rounded-full"></div>
                Označ všechny výskyty slova
            </h3>
            <div className="space-y-4 font-mono text-lg">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-gray-50/50 p-4 rounded-2xl border border-transparent">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-black font-bold">{t.text}</span>;
                    const isSelected = selectedIndices.has(t.id);
                    const isAlreadyInDict = dictionary.some(d => d.word === t.cleanWord);
                    return (
                      <button 
                        key={t.id} 
                        disabled={isAlreadyInDict}
                        onClick={() => handleWordClickId(t)} 
                        className={`px-1.5 py-0.5 rounded-lg transition-all font-black ${
                          isAlreadyInDict ? 'bg-emerald-100 text-emerald-700 opacity-60' : 
                          isSelected ? 'bg-blue-600 text-white shadow-md scale-105' : 
                          'hover:bg-blue-100 text-black font-bold'
                        }`}
                      >
                        {t.text}
                        {isAlreadyInDict && <Sparkles className="inline-block w-3 h-3 ml-1" />}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
            <button onClick={addToDictionary} className="w-full mt-8 py-5 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all active:scale-95">
              <PlusCircle className="w-5 h-5" /> Vložit do slovníku
            </button>
          </div>

          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-blue-100 flex flex-col">
            <h3 className="text-xl font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
              <Hash className="w-6 h-6 text-blue-600" /> Slovník kódů
            </h3>
            <div className="flex-1 space-y-3">
              {dictionary.length === 0 ? (
                <div className="py-20 text-center text-gray-300 font-bold uppercase text-xs tracking-widest border-2 border-dashed rounded-3xl flex flex-col items-center gap-4">
                  <FileText className="w-12 h-12 opacity-10" />
                  Zatím prázdné
                </div>
              ) : (
                dictionary.map((item) => (
                  <div key={item.code} className="flex items-center justify-between p-4 bg-blue-50 rounded-2xl border border-blue-100 animate-in slide-in-from-right duration-300">
                    <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-blue-600 text-white font-black rounded-xl flex items-center justify-center shadow-sm">#{item.code}</div>
                        <span className="font-black text-blue-900 uppercase text-lg">{item.word}</span>
                    </div>
                    <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}

      {/* Assembly - Druhý krok (Drag and Drop) */}
      {phase === 'assembly' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 w-full items-start">
          {/* Původní text (Reference) */}
          <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col">
            <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                <FileText className="w-4 h-4" /> Původní báseň
            </h4>
            <div className="space-y-3 font-mono text-sm bg-gray-50/50 p-4 rounded-2xl">
              {level.lines.map((line, i) => <div key={i} className="py-1 border-b border-gray-100 last:border-0 text-black font-bold whitespace-pre-wrap">{line}</div>)}
            </div>
            {isFinalCorrect && (
                <div className="mt-4 p-4 bg-emerald-50 rounded-2xl border border-emerald-200">
                    <div className="flex justify-between text-xs font-black uppercase text-emerald-700 mb-2">
                        <span>Původní velikost:</span>
                        <span>{stats.originalLen} znaků</span>
                    </div>
                </div>
            )}
          </div>

          {/* Paleta prvků (Draggable) */}
          <div className="bg-blue-900 p-8 rounded-[3rem] shadow-xl text-white flex flex-col gap-6 min-h-[500px]">
            <div>
                <h4 className="text-[10px] font-black text-blue-300 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Hash className="w-4 h-4" /> Slovník (Kódy)
                </h4>
                <div className="grid grid-cols-2 gap-3">
                    {dictionary.map(item => (
                        <div 
                            key={item.code} 
                            draggable
                            onDragStart={(e) => onDragStart(e, item.code)}
                            className="p-3 bg-blue-800 hover:bg-blue-700 cursor-grab active:cursor-grabbing rounded-2xl flex items-center gap-3 border border-blue-700 transition-all shadow-sm group"
                        >
                            <span className="w-8 h-8 bg-blue-500 text-white rounded-xl flex items-center justify-center text-xs font-black">#{item.code}</span>
                            <span className="text-[10px] font-black uppercase truncate">{item.word}</span>
                        </div>
                    ))}
                </div>
            </div>

            <div className="mt-auto">
                <h4 className="text-[10px] font-black text-blue-300 uppercase tracking-widest mb-4">Unikátní slova</h4>
                <div className="flex flex-wrap gap-2">
                    {nonEncodableWords.map(word => (
                        <div 
                            key={word} 
                            draggable
                            onDragStart={(e) => onDragStart(e, word)}
                            className="px-4 py-3 bg-gray-800 hover:bg-gray-700 cursor-grab active:cursor-grabbing rounded-xl text-[10px] font-black uppercase border border-gray-700 transition-all"
                        >
                            {word}
                        </div>
                    ))}
                </div>
            </div>
            <p className="text-[9px] text-blue-400 font-bold uppercase italic mt-4">Přetahuj prvky do prázdných polí vpravo.</p>
          </div>

          {/* Komprimovaný zápis (Drop Targets) */}
          <div className={`bg-white p-8 rounded-[3rem] shadow-xl border-4 transition-all ${isFinalCorrect ? 'border-emerald-500 shadow-emerald-100' : 'border-emerald-100'} flex flex-col`}>
            <h4 className="text-xs font-black text-emerald-600 uppercase tracking-widest mb-6 flex justify-between items-center">
                <span>Komprimovaný zápis</span>
                <span className="bg-emerald-50 px-3 py-1 rounded-full text-[10px] text-emerald-700">Úspora: {stats.savings}%</span>
            </h4>
            <div className="space-y-4 font-mono text-sm mb-8">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-emerald-50/50 p-3 rounded-2xl border border-emerald-100 min-h-[56px] gap-1">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-gray-500">{t.text}</span>;
                    const val = assemblyState[t.id];
                    return (
                      <div 
                        key={t.id} 
                        onDragOver={(e) => e.preventDefault()}
                        onDrop={(e) => onDrop(e, t.id)}
                        className={`min-w-[54px] h-10 px-2 rounded-xl font-black transition-all border-2 text-xs flex items-center justify-center ${
                            val ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm' : 
                            'bg-white border-emerald-100 text-emerald-200 border-dashed hover:border-emerald-400'
                        }`}
                      >
                        {val ? (typeof val === 'number' ? `#${val}` : val) : ''}
                      </div>
                    );
                  })}
                </div>
              ))}
            </div>

            {isFinalCorrect ? (
                <div className="mt-auto space-y-4">
                    <div className="p-5 bg-emerald-600 rounded-[2rem] text-white text-center animate-in zoom-in">
                        <Trophy className="w-8 h-8 mx-auto mb-2" />
                        <p className="font-black uppercase tracking-widest text-sm">Skvělá práce!</p>
                        <p className="text-[10px] opacity-80">Zkomprimováno na {stats.totalCompressed} znaků.</p>
                    </div>
                    <button onClick={() => setLevelIdx((levelIdx + 1) % LEVELS.length)} className="w-full py-4 bg-gray-900 text-white font-black rounded-[2rem] uppercase tracking-widest text-xs hover:bg-black transition-all">Další text</button>
                </div>
            ) : (
                <button onClick={checkFinal} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all active:scale-95">
                  <CheckCircle2 className="w-5 h-5" /> Ověřit kompresi
                </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default TextCompression;

import React, { useState, useMemo, useEffect } from 'react';
import { ArrowLeft, CheckCircle2, ArrowRight, Hash, FileText, Zap, Trophy, PlusCircle, AlertCircle, Sparkles, GripVertical } from 'lucide-react';

interface TextLevel {
  id: number;
  title: string;
  lines: string[];
}

const LEVELS: TextLevel[] = [
  {
    id: 1,
    title: "Prší, prší",
    lines: [
      "PRŠÍ, PRŠÍ, JEN SE LEJE.",
      "KAM KONÍČKY POJEDEME?",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ.",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ."
    ]
  },
  {
    id: 2,
    title: "Kukačka",
    lines: [
      "KUKAČKA UŽ ZAKUKALA,",
      "MÁ PANENKA ZAPLAKALA.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ."
    ]
  }
];

type Phase = 'identification' | 'assembly';

interface Token {
  id: string;
  text: string;
  cleanWord: string;
  isWord: boolean;
}

const TextCompression: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [levelIdx, setLevelIdx] = useState(0);
  const [phase, setPhase] = useState<Phase>('identification');
  const [dictionary, setDictionary] = useState<{ word: string; code: number }[]>([]);
  const [selectedIndices, setSelectedIndices] = useState<Set<string>>(new Set());
  const [assemblyState, setAssemblyState] = useState<{ [tokenId: string]: string | number }>({});
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);
  const [isFinalCorrect, setIsFinalCorrect] = useState(false);

  const level = LEVELS[levelIdx];

  const tokensMatrix: Token[][] = useMemo(() => {
    return level.lines.map((line, lIdx) => {
      const parts = line.split(/(\s+)/);
      return parts.map((part, pIdx) => {
        const isWord = /[A-ZČŠŽŘĎŤŇŮÚ]+/.test(part.toUpperCase());
        const cleanWord = part.trim().replace(/[,.?]/g, '').toUpperCase();
        return { id: `${lIdx}-${pIdx}`, text: part, cleanWord, isWord };
      });
    });
  }, [level]);

  const allTokens = useMemo(() => tokensMatrix.flat(), [tokensMatrix]);
  const allWords = useMemo(() => allTokens.filter(t => t.isWord), [allTokens]);

  const targetDictionaryWords = useMemo(() => {
    const counts: { [word: string]: number } = {};
    allWords.forEach(w => { counts[w.cleanWord] = (counts[w.cleanWord] || 0) + 1; });
    const duplicates = Object.keys(counts).filter(w => counts[w] > 1);

    const wordsInOrder: string[] = [];
    allWords.forEach(w => {
      if (duplicates.includes(w.cleanWord) && !wordsInOrder.includes(w.cleanWord)) {
        wordsInOrder.push(w.cleanWord);
      }
    });
    return wordsInOrder;
  }, [allWords]);

  const nonEncodableWords = useMemo(() => {
    const dups = new Set(targetDictionaryWords);
    return Array.from(new Set(allWords.filter(w => !dups.has(w.cleanWord)).map(w => w.text)));
  }, [allWords, targetDictionaryWords]);

  useEffect(() => {
    setPhase('identification');
    setDictionary([]);
    setSelectedIndices(new Set());
    setAssemblyState({});
    setFeedback(null);
    setIsFinalCorrect(false);
  }, [levelIdx]);

  // Vylepšený výpočet úspory dle požadavků
  const stats = useMemo(() => {
    const originalText = level.lines.join('\n');
    const originalLen = originalText.length;

    if (originalLen === 0) return { originalLen: 0, totalCompressed: 0, ratio: 100 };

    // 1. Délka komprimovaného textu
    let compressedTextLen = 0;
    allTokens.forEach(t => {
      if (!t.isWord) {
        // Mezery a interpunkce
        compressedTextLen += t.text.length;
      } else {
        const val = assemblyState[t.id];
        if (typeof val === 'number') {
          // Kód ze slovníku - počítáme jen délku čísla (bez hashtagu)
          compressedTextLen += val.toString().length;
        } else if (typeof val === 'string') {
          // Unikátní slovo
          compressedTextLen += val.length;
        } else {
          // Pokud ještě není vyplněno, bereme původní délku pro náhled
          compressedTextLen += t.text.length;
        }
      }
    });

    // 2. Délka slovníku (Slovo + Kód)
    const dictionaryLen = dictionary.reduce((acc, curr) => {
        return acc + curr.word.length + curr.code.toString().length;
    }, 0);

    const totalCompressed = compressedTextLen + dictionaryLen;
    // Poměr nové velikosti k původní v procentech
    const ratio = Math.round((totalCompressed / originalLen) * 100);

    return { originalLen, totalCompressed, ratio };
  }, [level, allTokens, assemblyState, dictionary]);

  // PHASE 1 Logic
  const handleWordClickId = (token: Token) => {
    if (phase !== 'identification' || !token.isWord || dictionary.some(d => d.word === token.cleanWord)) return;
    const newSelected = new Set(selectedIndices);
    if (newSelected.has(token.id)) newSelected.delete(token.id);
    else newSelected.add(token.id);
    setSelectedIndices(newSelected);
  };

  const addToDictionary = () => {
    if (selectedIndices.size === 0) return;
    const selectedTokens = allTokens.filter(t => selectedIndices.has(t.id));
    const word = selectedTokens[0].cleanWord;

    if (!selectedTokens.every(t => t.cleanWord === word)) {
      setFeedback({ type: 'error', message: 'Vyber výskyty pouze jednoho stejného slova!' });
      return;
    }

    const totalOccurrences = allWords.filter(t => t.cleanWord === word).length;
    if (selectedIndices.size !== totalOccurrences) {
      setFeedback({ type: 'error', message: `Slovo ${word} se v textu vyskytuje ${totalOccurrences}x, označ všechny!` });
      return;
    }

    if (totalOccurrences < 2) {
      setFeedback({ type: 'error', message: 'Slovo se neopakuje, nepatří do slovníku.' });
      return;
    }

    const nextTargetWord = targetDictionaryWords[dictionary.length];
    if (word !== nextTargetWord) {
      setFeedback({ type: 'error', message: `Postupuj podle pořadí! První neuložená duplicita je: ${nextTargetWord}` });
      return;
    }

    setDictionary(prev => [...prev, { word, code: prev.length + 1 }]);
    setSelectedIndices(new Set());
    setFeedback({ type: 'success', message: `Slovo ${word} uloženo pod kódem #${dictionary.length + 1}.` });

    if (dictionary.length + 1 === targetDictionaryWords.length) {
      setTimeout(() => {
        setPhase('assembly');
        setFeedback({ type: 'success', message: 'Slovník hotov! Teď přetáhni prvky do komprimovaného zápisu.' });
      }, 800);
    }
  };

  // DRAG AND DROP Logic
  const onDragStart = (e: React.DragEvent, value: string | number) => {
    e.dataTransfer.setData("text/plain", value.toString());
  };

  const onDrop = (e: React.DragEvent, tokenId: string) => {
    e.preventDefault();
    const data = e.dataTransfer.getData("text/plain");
    // Pokud je to číslo, uložíme ho jako number (kód), jinak jako string (slovo)
    const value = !isNaN(Number(data)) && data.trim() !== "" ? Number(data) : data;
    setAssemblyState(prev => ({ ...prev, [tokenId]: value }));
  };

  const checkFinal = () => {
    let errors = 0;
    let missing = 0;
    allTokens.forEach(t => {
      if (!t.isWord) return;
      const userVal = assemblyState[t.id];
      if (userVal === undefined) {
          missing++;
          return;
      }
      const dictItem = dictionary.find(d => d.word === t.cleanWord);
      if (dictItem) {
        if (userVal !== dictItem.code) errors++;
      } else {
        if (userVal !== t.text) errors++;
      }
    });

    if (missing > 0) {
        setFeedback({ type: 'error', message: `Doplň všechna pole v textu!` });
        return;
    }

    if (errors === 0) {
      setFeedback({ type: 'success', message: `Vynikající! Nová velikost je jen ${stats.ratio}% původní.` });
      setIsFinalCorrect(true);
    } else {
      setFeedback({ type: 'error', message: `Někde máš chybu (${errors}x). Zkontroluj hlavně kódy.` });
      setIsFinalCorrect(false);
    }
  };

  return (
    <div className="w-full max-w-7xl flex flex-col gap-6 items-center animate-in fade-in duration-500 pb-20 px-4">
      {/* Header */}
      <div className="w-full bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col md:flex-row items-center justify-between gap-6">
        <button onClick={onBack} className="flex items-center text-gray-400 hover:text-blue-600 transition-colors font-black uppercase text-xs tracking-widest shrink-0">
          <ArrowLeft className="w-5 h-5 mr-2" /> Zpět
        </button>

        <div className="flex gap-2">
          {LEVELS.map((l, idx) => (
            <button key={l.id} onClick={() => setLevelIdx(idx)} className={`px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${levelIdx === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-blue-50 text-blue-600'}`}>{l.title}</button>
          ))}
        </div>

        <div className="flex items-center gap-4 bg-blue-50 px-5 py-3 rounded-2xl border border-blue-100">
          <Zap className="w-5 h-5 text-blue-600" />
          <div className="text-left">
            <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest leading-none">Fáze úkolu</p>
            <p className="text-xs font-black text-blue-900 uppercase tracking-tight">
              {phase === 'identification' ? '1. Tvorba slovníku' : '2. Drag & Drop komprese'}
            </p>
          </div>
        </div>
      </div>

      {feedback && (
        <div className={`w-full p-4 rounded-2xl border-2 flex items-center gap-3 animate-in slide-in-from-top duration-300 ${feedback.type === 'success' ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800'}`}>
          {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          <span className="font-bold text-sm uppercase tracking-tight">{feedback.message}</span>
        </div>
      )}

      {/* Identifikace - První krok */}
      {phase === 'identification' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 w-full">
          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100">
            <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight flex items-center gap-3 mb-6">
                <div className="w-3 h-8 bg-blue-500 rounded-full"></div>
                Označ všechny výskyty slova
            </h3>
            <div className="space-y-4 font-mono text-lg">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-gray-50/50 p-4 rounded-2xl border border-transparent">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-black font-bold">{t.text}</span>;
                    const isSelected = selectedIndices.has(t.id);
                    const isAlreadyInDict = dictionary.some(d => d.word === t.cleanWord);
                    return (
                      <button 
                        key={t.id} 
                        disabled={isAlreadyInDict}
                        onClick={() => handleWordClickId(t)} 
                        className={`px-1.5 py-0.5 rounded-lg transition-all font-black ${
                          isAlreadyInDict ? 'bg-emerald-100 text-emerald-700 opacity-60' : 
                          isSelected ? 'bg-blue-600 text-white shadow-md scale-105' : 
                          'hover:bg-blue-100 text-black font-bold'
                        }`}
                      >
                        {t.text}
                        {isAlreadyInDict && <Sparkles className="inline-block w-3 h-3 ml-1" />}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
            <button onClick={addToDictionary} className="w-full mt-8 py-5 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all active:scale-95">
              <PlusCircle className="w-5 h-5" /> Vložit do slovníku
            </button>
          </div>

          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-blue-100 flex flex-col">
            <h3 className="text-xl font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
              <Hash className="w-6 h-6 text-blue-600" /> Slovník kódů
            </h3>
            <div className="flex-1 space-y-3">
              {dictionary.length === 0 ? (
                <div className="py-20 text-center text-gray-300 font-bold uppercase text-xs tracking-widest border-2 border-dashed rounded-3xl flex flex-col items-center gap-4">
                  <FileText className="w-12 h-12 opacity-10" />
                  Zatím prázdné
                </div>
              ) : (
                dictionary.map((item) => (
                  <div key={item.code} className="flex items-center justify-between p-4 bg-blue-50 rounded-2xl border border-blue-100 animate-in slide-in-from-right duration-300">
                    <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-blue-600 text-white font-black rounded-xl flex items-center justify-center shadow-sm">#{item.code}</div>
                        <span className="font-black text-blue-900 uppercase text-lg">{item.word}</span>
                    </div>
                    <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}

      {/* Assembly - Druhý krok (Drag and Drop) */}
      {phase === 'assembly' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 w-full items-start">
          {/* Původní text (Reference) */}
          <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col">
            <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                <FileText className="w-4 h-4" /> Původní text
            </h4>
            <div className="space-y-3 font-mono text-sm bg-gray-50/50 p-4 rounded-2xl">
              {level.lines.map((line, i) => <div key={i} className="py-1 border-b border-gray-100 last:border-0 text-black font-bold whitespace-pre-wrap">{line}</div>)}
            </div>
            <div className="mt-6 p-5 bg-blue-50 rounded-[2rem] border border-blue-100">
                <div className="flex justify-between items-center mb-1">
                    <span className="text-[10px] font-black uppercase text-blue-400">Původní velikost:</span>
                    <span className="text-sm font-black text-blue-900">{stats.originalLen} znaků</span>
                </div>
                <div className="flex justify-between items-center">
                    <span className="text-[10px] font-black uppercase text-emerald-500">Nová velikost:</span>
                    <span className="text-sm font-black text-emerald-700">{stats.totalCompressed} znaků</span>
                </div>
            </div>
          </div>

          {/* Paleta prvků (Draggable) */}
          <div className="bg-blue-900 p-8 rounded-[3rem] shadow-xl text-white flex flex-col gap-6 min-h-[500px]">
            <div>
                <h4 className="text-[10px] font-black text-blue-300 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Hash className="w-4 h-4" /> Slovník (Kódy)
                </h4>
                <div className="grid grid-cols-2 gap-3">
                    {dictionary.map(item => (
                        <div 
                            key={item.code} 
                            draggable
                            onDragStart={(e) => onDragStart(e, item.code)}
                            className="p-3 bg-blue-800 hover:bg-blue-700 cursor-grab active:cursor-grabbing rounded-2xl flex items-center gap-3 border border-blue-700 transition-all shadow-sm group"
                        >
                            <span className="w-8 h-8 bg-blue-500 text-white rounded-xl flex items-center justify-center text-xs font-black">#{item.code}</span>
                            <span className="text-[10px] font-black uppercase truncate">{item.word}</span>
                        </div>
                    ))}
                </div>
            </div>

            <div className="mt-auto">
                <h4 className="text-[10px] font-black text-blue-300 uppercase tracking-widest mb-4">Unikátní slova</h4>
                <div className="flex flex-wrap gap-2">
                    {nonEncodableWords.map(word => (
                        <div 
                            key={word} 
                            draggable
                            onDragStart={(e) => onDragStart(e, word)}
                            className="px-4 py-3 bg-gray-800 hover:bg-gray-700 cursor-grab active:cursor-grabbing rounded-xl text-[10px] font-black uppercase border border-gray-700 transition-all"
                        >
                            {word}
                        </div>
                    ))}
                </div>
            </div>
            <p className="text-[9px] text-blue-400 font-bold uppercase italic mt-4 leading-relaxed">Při výpočtu se kód ze slovníku v textu započítává jako délka čísla (bez znaku #). Unikátní slova se počítají celá.</p>
          </div>

          {/* Komprimovaný zápis (Drop Targets) */}
          <div className={`bg-white p-8 rounded-[3rem] shadow-xl border-4 transition-all ${isFinalCorrect ? 'border-emerald-500 shadow-emerald-100' : 'border-emerald-100'} flex flex-col`}>
            <div className="flex justify-between items-center mb-6">
                <h4 className="text-xs font-black text-emerald-600 uppercase tracking-widest">Komprimovaný zápis</h4>
                <div className="flex flex-col items-end">
                    <span className="text-[9px] font-black text-gray-400 uppercase">Velikost:</span>
                    <span className="bg-emerald-600 px-3 py-1 rounded-full text-xs font-black text-white">{stats.ratio}%</span>
                </div>
            </div>
            <div className="space-y-4 font-mono text-sm mb-8">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-emerald-50/50 p-3 rounded-2xl border border-emerald-100 min-h-[56px] gap-1">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-gray-500">{t.text}</span>;
                    const val = assemblyState[t.id];
                    return (
                      <div 
                        key={t.id} 
                        onDragOver={(e) => e.preventDefault()}
                        onDrop={(e) => onDrop(e, t.id)}
                        className={`min-w-[54px] h-10 px-2 rounded-xl font-black transition-all border-2 text-xs flex items-center justify-center ${
                            val !== undefined ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm' : 
                            'bg-white border-emerald-100 text-emerald-200 border-dashed hover:border-emerald-400'
                        }`}
                      >
                        {val !== undefined ? (typeof val === 'number' ? `#${val}` : val) : ''}
                      </div>
                    );
                  })}
                </div>
              ))}
            </div>

            {isFinalCorrect ? (
                <div className="mt-auto space-y-4">
                    <div className="p-5 bg-emerald-600 rounded-[2rem] text-white text-center animate-in zoom-in">
                        <Trophy className="w-8 h-8 mx-auto mb-2" />
                        <p className="font-black uppercase tracking-widest text-sm">Vynikající!</p>
                        <p className="text-[10px] opacity-80 leading-relaxed">Data byla zkomprimována na {stats.totalCompressed} znaků (včetně slovníku).</p>
                    </div>
                    <button onClick={() => setLevelIdx((levelIdx + 1) % LEVELS.length)} className="w-full py-4 bg-gray-900 text-white font-black rounded-[2rem] uppercase tracking-widest text-xs hover:bg-black transition-all shadow-lg shadow-gray-200">Další úkol</button>
                </div>
            ) : (
                <button onClick={checkFinal} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all active:scale-95">
                  <CheckCircle2 className="w-5 h-5" /> Ověřit výsledek
                </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default TextCompression;

import React, { useState, useMemo, useEffect } from 'react';
import { ArrowLeft, CheckCircle2, ArrowRight, Hash, FileText, Zap, Trophy, PlusCircle, AlertCircle, Sparkles, GripVertical } from 'lucide-react';

interface TextLevel {
  id: number;
  title: string;
  lines: string[];
}

const LEVELS: TextLevel[] = [
  {
    id: 1,
    title: "Prší, prší",
    lines: [
      "PRŠÍ, PRŠÍ, JEN SE LEJE.",
      "KAM KONÍČKY POJEDEME?",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ.",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ."
    ]
  },
  {
    id: 2,
    title: "Kukačka",
    lines: [
      "KUKAČKA UŽ ZAKUKALA,",
      "MÁ PANENKA ZAPLAKALA.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ."
    ]
  }
];

type Phase = 'identification' | 'assembly';

interface Token {
  id: string;
  text: string;
  cleanWord: string;
  isWord: boolean;
}

const TextCompression: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [levelIdx, setLevelIdx] = useState(0);
  const [phase, setPhase] = useState<Phase>('identification');
  const [dictionary, setDictionary] = useState<{ word: string; code: number }[]>([]);
  const [selectedIndices, setSelectedIndices] = useState<Set<string>>(new Set());
  const [assemblyState, setAssemblyState] = useState<{ [tokenId: string]: string | number }>({});
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);
  const [isFinalCorrect, setIsFinalCorrect] = useState(false);

  const level = LEVELS[levelIdx];

  const tokensMatrix: Token[][] = useMemo(() => {
    return level.lines.map((line, lIdx) => {
      const parts = line.split(/(\s+)/);
      return parts.map((part, pIdx) => {
        const isWord = /[A-ZČŠŽŘĎŤŇŮÚ]+/.test(part.toUpperCase());
        const cleanWord = part.trim().replace(/[,.?]/g, '').toUpperCase();
        return { id: `${lIdx}-${pIdx}`, text: part, cleanWord, isWord };
      });
    });
  }, [level]);

  const allTokens = useMemo(() => tokensMatrix.flat(), [tokensMatrix]);
  const allWords = useMemo(() => allTokens.filter(t => t.isWord), [allTokens]);

  const targetDictionaryWords = useMemo(() => {
    const counts: { [word: string]: number } = {};
    allWords.forEach(w => { counts[w.cleanWord] = (counts[w.cleanWord] || 0) + 1; });
    const duplicates = Object.keys(counts).filter(w => counts[w] > 1);

    const wordsInOrder: string[] = [];
    allWords.forEach(w => {
      if (duplicates.includes(w.cleanWord) && !wordsInOrder.includes(w.cleanWord)) {
        wordsInOrder.push(w.cleanWord);
      }
    });
    return wordsInOrder;
  }, [allWords]);

  const nonEncodableWords = useMemo(() => {
    const dups = new Set(targetDictionaryWords);
    return Array.from(new Set(allWords.filter(w => !dups.has(w.cleanWord)).map(w => w.text)));
  }, [allWords, targetDictionaryWords]);

  useEffect(() => {
    setPhase('identification');
    setDictionary([]);
    setSelectedIndices(new Set());
    setAssemblyState({});
    setFeedback(null);
    setIsFinalCorrect(false);
  }, [levelIdx]);

  // Finální výpočet úspory
  const stats = useMemo(() => {
    const originalText = level.lines.join('\n');
    const originalLen = originalText.length;

    if (originalLen === 0) return { originalLen: 0, totalCompressed: 0, ratio: 100 };

    // 1. Délka zkomprimovaného textu (bez slovníku)
    let compressedTextLen = 0;
    allTokens.forEach(t => {
      if (!t.isWord) {
        // Mezery a interpunkce započítáme jak jsou
        compressedTextLen += t.text.length;
      } else {
        const val = assemblyState[t.id];
        if (typeof val === 'number') {
          // Kód ze slovníku - počítáme pouze délku čísla (bez znaku #)
          compressedTextLen += val.toString().length;
        } else if (typeof val === 'string') {
          // Unikátní slovo (nepřenášené do slovníku)
          compressedTextLen += val.length;
        } else {
          // Pokud slot není vyplněn, pro odhad počítáme původní délku
          compressedTextLen += t.text.length;
        }
      }
    });

    // Musíme připočítat konce řádků (\n), které join('\n') vytvořil v originalLen
    // V tokensMatrix jsou jen tokeny z jednotlivých řádků, oddělovače řádků tam nejsou.
    compressedTextLen += (level.lines.length - 1);

    // 2. Délka slovníku (Slovo + Kód)
    // Např. "LUKA" + "1" = 5 znaků
    const dictionaryLen = dictionary.reduce((acc, curr) => {
        return acc + curr.word.length + curr.code.toString().length;
    }, 0);

    const totalCompressed = compressedTextLen + dictionaryLen;

    // Poměr nové velikosti k původní v procentech
    const ratio = Math.round((totalCompressed / originalLen) * 100);

    return { originalLen, totalCompressed, ratio };
  }, [level, allTokens, assemblyState, dictionary]);

  const handleWordClickId = (token: Token) => {
    if (phase !== 'identification' || !token.isWord || dictionary.some(d => d.word === token.cleanWord)) return;
    const newSelected = new Set(selectedIndices);
    if (newSelected.has(token.id)) newSelected.delete(token.id);
    else newSelected.add(token.id);
    setSelectedIndices(newSelected);
  };

  const addToDictionary = () => {
    if (selectedIndices.size === 0) return;
    const selectedTokens = allTokens.filter(t => selectedIndices.has(t.id));
    const word = selectedTokens[0].cleanWord;

    if (!selectedTokens.every(t => t.cleanWord === word)) {
      setFeedback({ type: 'error', message: 'Vyber výskyty pouze jednoho stejného slova!' });
      return;
    }

    const totalOccurrences = allWords.filter(t => t.cleanWord === word).length;
    if (selectedIndices.size !== totalOccurrences) {
      setFeedback({ type: 'error', message: `Slovo ${word} se v textu vyskytuje ${totalOccurrences}x, označ všechny!` });
      return;
    }

    if (totalOccurrences < 2) {
      setFeedback({ type: 'error', message: 'Slovo se neopakuje, nepatří do slovníku.' });
      return;
    }

    const nextTargetWord = targetDictionaryWords[dictionary.length];
    if (word !== nextTargetWord) {
      setFeedback({ type: 'error', message: `Postupuj podle pořadí! První neuložená duplicita je: ${nextTargetWord}` });
      return;
    }

    setDictionary(prev => [...prev, { word, code: prev.length + 1 }]);
    setSelectedIndices(new Set());
    setFeedback({ type: 'success', message: `Slovo ${word} uloženo pod kódem #${dictionary.length + 1}.` });

    if (dictionary.length + 1 === targetDictionaryWords.length) {
      setTimeout(() => {
        setPhase('assembly');
        setFeedback({ type: 'success', message: 'Slovník hotov! Teď přetáhni prvky do komprimovaného zápisu.' });
      }, 800);
    }
  };

  const onDragStart = (e: React.DragEvent, value: string | number) => {
    e.dataTransfer.setData("text/plain", value.toString());
  };

  const onDrop = (e: React.DragEvent, tokenId: string) => {
    e.preventDefault();
    const data = e.dataTransfer.getData("text/plain");
    const value = !isNaN(Number(data)) && data.trim() !== "" ? Number(data) : data;
    setAssemblyState(prev => ({ ...prev, [tokenId]: value }));
  };

  const checkFinal = () => {
    let errors = 0;
    let missing = 0;
    allTokens.forEach(t => {
      if (!t.isWord) return;
      const userVal = assemblyState[t.id];
      if (userVal === undefined) {
          missing++;
          return;
      }
      const dictItem = dictionary.find(d => d.word === t.cleanWord);
      if (dictItem) {
        if (userVal !== dictItem.code) errors++;
      } else {
        if (userVal !== t.text) errors++;
      }
    });

    if (missing > 0) {
        setFeedback({ type: 'error', message: `Doplň všechna pole v textu!` });
        return;
    }

    if (errors === 0) {
      setFeedback({ type: 'success', message: `Vynikající! Nová velikost dat je jen ${stats.ratio}% původní.` });
      setIsFinalCorrect(true);
    } else {
      setFeedback({ type: 'error', message: `Někde máš chybu (${errors}x). Zkontroluj hlavně kódy.` });
      setIsFinalCorrect(false);
    }
  };

  return (
    <div className="w-full max-w-7xl flex flex-col gap-6 items-center animate-in fade-in duration-500 pb-20 px-4">
      {/* Header */}
      <div className="w-full bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col md:flex-row items-center justify-between gap-6">
        <button onClick={onBack} className="flex items-center text-gray-400 hover:text-blue-600 transition-colors font-black uppercase text-xs tracking-widest shrink-0">
          <ArrowLeft className="w-5 h-5 mr-2" /> Zpět
        </button>

        <div className="flex gap-2">
          {LEVELS.map((l, idx) => (
            <button key={l.id} onClick={() => setLevelIdx(idx)} className={`px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${levelIdx === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-blue-50 text-blue-600'}`}>{l.title}</button>
          ))}
        </div>

        <div className="flex items-center gap-4 bg-blue-50 px-5 py-3 rounded-2xl border border-blue-100">
          <Zap className="w-5 h-5 text-blue-600" />
          <div className="text-left">
            <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest leading-none">Fáze úkolu</p>
            <p className="text-xs font-black text-blue-900 uppercase tracking-tight">
              {phase === 'identification' ? '1. Tvorba slovníku' : '2. Sestavení básně'}
            </p>
          </div>
        </div>
      </div>

      {feedback && (
        <div className={`w-full p-4 rounded-2xl border-2 flex items-center gap-3 animate-in slide-in-from-top duration-300 ${feedback.type === 'success' ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800'}`}>
          {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          <span className="font-bold text-sm uppercase tracking-tight">{feedback.message}</span>
        </div>
      )}

      {phase === 'identification' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 w-full">
          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100">
            <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight flex items-center gap-3 mb-6">
                <div className="w-3 h-8 bg-blue-500 rounded-full"></div>
                Označ všechny výskyty slova
            </h3>
            <div className="space-y-4 font-mono text-lg">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-gray-50/50 p-4 rounded-2xl border border-transparent">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-black font-bold">{t.text}</span>;
                    const isSelected = selectedIndices.has(t.id);
                    const isAlreadyInDict = dictionary.some(d => d.word === t.cleanWord);
                    return (
                      <button 
                        key={t.id} 
                        disabled={isAlreadyInDict}
                        onClick={() => handleWordClickId(t)} 
                        className={`px-1.5 py-0.5 rounded-lg transition-all font-black ${
                          isAlreadyInDict ? 'bg-emerald-100 text-emerald-700 opacity-60' : 
                          isSelected ? 'bg-blue-600 text-white shadow-md scale-105' : 
                          'hover:bg-blue-100 text-black font-bold'
                        }`}
                      >
                        {t.text}
                        {isAlreadyInDict && <Sparkles className="inline-block w-3 h-3 ml-1" />}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
            <button onClick={addToDictionary} className="w-full mt-8 py-5 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all active:scale-95">
              <PlusCircle className="w-5 h-5" /> Vložit do slovníku
            </button>
          </div>

          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-blue-100 flex flex-col">
            <h3 className="text-xl font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
              <Hash className="w-6 h-6 text-blue-600" /> Slovník kódů
            </h3>
            <div className="flex-1 space-y-3">
              {dictionary.length === 0 ? (
                <div className="py-20 text-center text-gray-300 font-bold uppercase text-xs tracking-widest border-2 border-dashed rounded-3xl flex flex-col items-center gap-4">
                  <FileText className="w-12 h-12 opacity-10" />
                  Zatím prázdné
                </div>
              ) : (
                dictionary.map((item) => (
                  <div key={item.code} className="flex items-center justify-between p-4 bg-blue-50 rounded-2xl border border-blue-100 animate-in slide-in-from-right duration-300">
                    <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-blue-600 text-white font-black rounded-xl flex items-center justify-center shadow-sm">#{item.code}</div>
                        <span className="font-black text-blue-900 uppercase text-lg">{item.word}</span>
                    </div>
                    <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}

      {phase === 'assembly' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 w-full items-start">
          <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col">
            <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                <FileText className="w-4 h-4" /> Původní text
            </h4>
            <div className="space-y-3 font-mono text-sm bg-gray-50/50 p-4 rounded-2xl">
              {level.lines.map((line, i) => <div key={i} className="py-1 border-b border-gray-100 last:border-0 text-black font-bold whitespace-pre-wrap">{line}</div>)}
            </div>
            <div className="mt-6 p-5 bg-blue-50 rounded-[2rem] border border-blue-100">
                <div className="flex justify-between items-center mb-1">
                    <span className="text-[10px] font-black uppercase text-blue-400">Původní:</span>
                    <span className="text-sm font-black text-blue-900">{stats.originalLen} znaků</span>
                </div>
                <div className="flex justify-between items-center">
                    <span className="text-[10px] font-black uppercase text-emerald-500">Zkomprimováno:</span>
                    <span className="text-sm font-black text-emerald-700">{stats.totalCompressed} znaků</span>
                </div>
                <div className="mt-2 pt-2 border-t border-blue-100 flex justify-between items-center">
                    <span className="text-[10px] font-black uppercase text-gray-400">Poměr:</span>
                    <span className="text-lg font-black text-blue-600">{stats.ratio}%</span>
                </div>
            </div>
          </div>

          <div className="bg-blue-900 p-8 rounded-[3rem] shadow-xl text-white flex flex-col gap-6 min-h-[500px]">
            <div>
                <h4 className="text-[10px] font-black text-blue-300 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Hash className="w-4 h-4" /> Slovník (Kódy)
                </h4>
                <div className="grid grid-cols-2 gap-3">
                    {dictionary.map(item => (
                        <div 
                            key={item.code} 
                            draggable
                            onDragStart={(e) => onDragStart(e, item.code)}
                            className="p-3 bg-blue-800 hover:bg-blue-700 cursor-grab active:cursor-grabbing rounded-2xl flex items-center gap-3 border border-blue-700 transition-all shadow-sm group"
                        >
                            <span className="w-8 h-8 bg-blue-500 text-white rounded-xl flex items-center justify-center text-xs font-black">#{item.code}</span>
                            <span className="text-[10px] font-black uppercase truncate">{item.word}</span>
                        </div>
                    ))}
                </div>
            </div>

            <div className="mt-auto">
                <h4 className="text-[10px] font-black text-blue-300 uppercase tracking-widest mb-4">Unikátní slova</h4>
                <div className="flex flex-wrap gap-2">
                    {nonEncodableWords.map(word => (
                        <div 
                            key={word} 
                            draggable
                            onDragStart={(e) => onDragStart(e, word)}
                            className="px-4 py-3 bg-gray-800 hover:bg-gray-700 cursor-grab active:cursor-grabbing rounded-xl text-[10px] font-black uppercase border border-gray-700 transition-all"
                        >
                            {word}
                        </div>
                    ))}
                </div>
            </div>
            <p className="text-[9px] text-blue-400 font-bold uppercase italic mt-4 leading-relaxed">
              Výpočet: (Zkomprimovaný text + Slovník) / Původní text.<br/>
              Kód v textu se počítá jako délka čísla (bez #).
            </p>
          </div>

          <div className={`bg-white p-8 rounded-[3rem] shadow-xl border-4 transition-all ${isFinalCorrect ? 'border-emerald-500 shadow-emerald-100' : 'border-emerald-100'} flex flex-col`}>
            <div className="flex justify-between items-center mb-6">
                <h4 className="text-xs font-black text-emerald-600 uppercase tracking-widest">Komprimovaný zápis</h4>
                <span className="bg-emerald-600 px-3 py-1 rounded-full text-xs font-black text-white">{stats.ratio}%</span>
            </div>
            <div className="space-y-4 font-mono text-sm mb-8">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-emerald-50/50 p-3 rounded-2xl border border-emerald-100 min-h-[56px] gap-1">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-gray-500">{t.text}</span>;
                    const val = assemblyState[t.id];
                    return (
                      <div 
                        key={t.id} 
                        onDragOver={(e) => e.preventDefault()}
                        onDrop={(e) => onDrop(e, t.id)}
                        className={`min-w-[54px] h-10 px-2 rounded-xl font-black transition-all border-2 text-xs flex items-center justify-center ${
                            val !== undefined ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm' : 
                            'bg-white border-emerald-100 text-emerald-200 border-dashed hover:border-emerald-400'
                        }`}
                      >
                        {val !== undefined ? (typeof val === 'number' ? `#${val}` : val) : ''}
                      </div>
                    );
                  })}
                </div>
              ))}
            </div>

            {isFinalCorrect ? (
                <div className="mt-auto space-y-4">
                    <div className="p-5 bg-emerald-600 rounded-[2rem] text-white text-center animate-in zoom-in">
                        <Trophy className="w-8 h-8 mx-auto mb-2" />
                        <p className="font-black uppercase tracking-widest text-sm">Skvělá práce!</p>
                        <p className="text-[10px] opacity-80 leading-relaxed">Podařilo se vám ušetřit {100 - stats.ratio}% paměti.</p>
                    </div>
                    <button onClick={() => setLevelIdx((levelIdx + 1) % LEVELS.length)} className="w-full py-4 bg-gray-900 text-white font-black rounded-[2rem] uppercase tracking-widest text-xs hover:bg-black transition-all shadow-lg shadow-gray-200">Další úkol</button>
                </div>
            ) : (
                <button onClick={checkFinal} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all active:scale-95">
                  <CheckCircle2 className="w-5 h-5" /> Ověřit výsledek
                </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default TextCompression;

import React, { useState, useMemo, useEffect } from 'react';
import { ArrowLeft, CheckCircle2, ArrowRight, Hash, FileText, Zap, Trophy, PlusCircle, AlertCircle, Sparkles, GripVertical } from 'lucide-react';

interface TextLevel {
  id: number;
  title: string;
  lines: string[];
}

const LEVELS: TextLevel[] = [
  {
    id: 1,
    title: "Prší, prší",
    lines: [
      "PRŠÍ, PRŠÍ, JEN SE LEJE.",
      "KAM KONÍČKY POJEDEME?",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ.",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ."
    ]
  },
  {
    id: 2,
    title: "Kukačka",
    lines: [
      "KUKAČKA UŽ ZAKUKALA,",
      "MÁ PANENKA ZAPLAKALA.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ.",
      "KUKAČKO, UŽ NEKUKEJ,",
      "MÁ PANENKO, NEPLAKEJ."
    ]
  }
];

type Phase = 'identification' | 'assembly';

interface Token {
  id: string;
  text: string;
  cleanWord: string;
  isWord: boolean;
}

const TextCompression: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [levelIdx, setLevelIdx] = useState(0);
  const [phase, setPhase] = useState<Phase>('identification');
  const [dictionary, setDictionary] = useState<{ word: string; code: number }[]>([]);
  const [selectedIndices, setSelectedIndices] = useState<Set<string>>(new Set());
  const [assemblyState, setAssemblyState] = useState<{ [tokenId: string]: string | number }>({});
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);
  const [isFinalCorrect, setIsFinalCorrect] = useState(false);

  const level = LEVELS[levelIdx];

  const tokensMatrix: Token[][] = useMemo(() => {
    return level.lines.map((line, lIdx) => {
      const parts = line.split(/(\s+)/);
      return parts.map((part, pIdx) => {
        const isWord = /[A-ZČŠŽŘĎŤŇŮÚ]+/.test(part.toUpperCase());
        const cleanWord = part.trim().replace(/[,.?]/g, '').toUpperCase();
        return { id: `${lIdx}-${pIdx}`, text: part, cleanWord, isWord };
      });
    });
  }, [level]);

  const allTokens = useMemo(() => tokensMatrix.flat(), [tokensMatrix]);
  const allWords = useMemo(() => allTokens.filter(t => t.isWord), [allTokens]);

  const targetDictionaryWords = useMemo(() => {
    const counts: { [word: string]: number } = {};
    allWords.forEach(w => { counts[w.cleanWord] = (counts[w.cleanWord] || 0) + 1; });
    const duplicates = Object.keys(counts).filter(w => counts[w] > 1);

    const wordsInOrder: string[] = [];
    allWords.forEach(w => {
      if (duplicates.includes(w.cleanWord) && !wordsInOrder.includes(w.cleanWord)) {
        wordsInOrder.push(w.cleanWord);
      }
    });
    return wordsInOrder;
  }, [allWords]);

  const nonEncodableWords = useMemo(() => {
    const dups = new Set(targetDictionaryWords);
    return Array.from(new Set(allWords.filter(w => !dups.has(w.cleanWord)).map(w => w.text)));
  }, [allWords, targetDictionaryWords]);

  useEffect(() => {
    setPhase('identification');
    setDictionary([]);
    setSelectedIndices(new Set());
    setAssemblyState({});
    setFeedback(null);
    setIsFinalCorrect(false);
  }, [levelIdx]);

  // Finální výpočet úspory - BEZ konců řádků a BEZ velikosti slovníku
  const stats = useMemo(() => {
    // Původní délka jako součet všech znaků v řádcích (bez \n)
    const originalLen = level.lines.reduce((acc, line) => acc + line.length, 0);

    if (originalLen === 0) return { originalLen: 0, totalCompressed: 0, ratio: 100 };

    // Délka zkomprimovaného textu
    let totalCompressed = 0;
    allTokens.forEach(t => {
      if (!t.isWord) {
        // Mezery a interpunkce
        totalCompressed += t.text.length;
      } else {
        const val = assemblyState[t.id];
        if (typeof val === 'number') {
          // Kód ze slovníku - počítáme pouze délku čísla (např. 10 = 2 znaky)
          totalCompressed += val.toString().length;
        } else if (typeof val === 'string') {
          // Unikátní slovo
          totalCompressed += val.length;
        } else {
          // Náhled: pokud není vyplněno, počítáme původní slovo
          totalCompressed += t.text.length;
        }
      }
    });

    // Poměr nové velikosti k původní v procentech
    const ratio = Math.round((totalCompressed / originalLen) * 100);

    return { originalLen, totalCompressed, ratio };
  }, [level, allTokens, assemblyState]);

  const handleWordClickId = (token: Token) => {
    if (phase !== 'identification' || !token.isWord || dictionary.some(d => d.word === token.cleanWord)) return;
    const newSelected = new Set(selectedIndices);
    if (newSelected.has(token.id)) newSelected.delete(token.id);
    else newSelected.add(token.id);
    setSelectedIndices(newSelected);
  };

  const addToDictionary = () => {
    if (selectedIndices.size === 0) return;
    const selectedTokens = allTokens.filter(t => selectedIndices.has(t.id));
    const word = selectedTokens[0].cleanWord;

    if (!selectedTokens.every(t => t.cleanWord === word)) {
      setFeedback({ type: 'error', message: 'Vyber výskyty pouze jednoho stejného slova!' });
      return;
    }

    const totalOccurrences = allWords.filter(t => t.cleanWord === word).length;
    if (selectedIndices.size !== totalOccurrences) {
      setFeedback({ type: 'error', message: `Slovo ${word} se v textu vyskytuje ${totalOccurrences}x, označ všechny!` });
      return;
    }

    if (totalOccurrences < 2) {
      setFeedback({ type: 'error', message: 'Slovo se neopakuje, nepatří do slovníku.' });
      return;
    }

    const nextTargetWord = targetDictionaryWords[dictionary.length];
    if (word !== nextTargetWord) {
      setFeedback({ type: 'error', message: `Postupuj podle pořadí! První neuložená duplicita je: ${nextTargetWord}` });
      return;
    }

    setDictionary(prev => [...prev, { word, code: prev.length + 1 }]);
    setSelectedIndices(new Set());
    setFeedback({ type: 'success', message: `Slovo ${word} uloženo pod kódem #${dictionary.length + 1}.` });

    if (dictionary.length + 1 === targetDictionaryWords.length) {
      setTimeout(() => {
        setPhase('assembly');
        setFeedback({ type: 'success', message: 'Slovník hotov! Teď přetáhni prvky do komprimovaného zápisu.' });
      }, 800);
    }
  };

  const onDragStart = (e: React.DragEvent, value: string | number) => {
    e.dataTransfer.setData("text/plain", value.toString());
  };

  const onDrop = (e: React.DragEvent, tokenId: string) => {
    e.preventDefault();
    const data = e.dataTransfer.getData("text/plain");
    const value = !isNaN(Number(data)) && data.trim() !== "" ? Number(data) : data;
    setAssemblyState(prev => ({ ...prev, [tokenId]: value }));
  };

  const checkFinal = () => {
    let errors = 0;
    let missing = 0;
    allTokens.forEach(t => {
      if (!t.isWord) return;
      const userVal = assemblyState[t.id];
      if (userVal === undefined) {
          missing++;
          return;
      }
      const dictItem = dictionary.find(d => d.word === t.cleanWord);
      if (dictItem) {
        if (userVal !== dictItem.code) errors++;
      } else {
        if (userVal !== t.text) errors++;
      }
    });

    if (missing > 0) {
        setFeedback({ type: 'error', message: `Doplň všechna pole v textu!` });
        return;
    }

    if (errors === 0) {
      setFeedback({ type: 'success', message: `Vynikající! Nová velikost textu je ${stats.ratio}% původní.` });
      setIsFinalCorrect(true);
    } else {
      setFeedback({ type: 'error', message: `Někde máš chybu (${errors}x). Zkontroluj hlavně kódy.` });
      setIsFinalCorrect(false);
    }
  };

  return (
    <div className="w-full max-w-7xl flex flex-col gap-6 items-center animate-in fade-in duration-500 pb-20 px-4">
      {/* Header */}
      <div className="w-full bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col md:flex-row items-center justify-between gap-6">
        <button onClick={onBack} className="flex items-center text-gray-400 hover:text-blue-600 transition-colors font-black uppercase text-xs tracking-widest shrink-0">
          <ArrowLeft className="w-5 h-5 mr-2" /> Zpět
        </button>

        <div className="flex gap-2">
          {LEVELS.map((l, idx) => (
            <button key={l.id} onClick={() => setLevelIdx(idx)} className={`px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${levelIdx === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-blue-50 text-blue-600'}`}>{l.title}</button>
          ))}
        </div>

        <div className="flex items-center gap-4 bg-blue-50 px-5 py-3 rounded-2xl border border-blue-100">
          <Zap className="w-5 h-5 text-blue-600" />
          <div className="text-left">
            <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest leading-none">Fáze úkolu</p>
            <p className="text-xs font-black text-blue-900 uppercase tracking-tight">
              {phase === 'identification' ? '1. Tvorba slovníku' : '2. Sestavení básně'}
            </p>
          </div>
        </div>
      </div>

      {feedback && (
        <div className={`w-full p-4 rounded-2xl border-2 flex items-center gap-3 animate-in slide-in-from-top duration-300 ${feedback.type === 'success' ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800'}`}>
          {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          <span className="font-bold text-sm uppercase tracking-tight">{feedback.message}</span>
        </div>
      )}

      {phase === 'identification' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 w-full">
          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100">
            <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight flex items-center gap-3 mb-6">
                <div className="w-3 h-8 bg-blue-500 rounded-full"></div>
                Označ všechny výskyty slova
            </h3>
            <div className="space-y-4 font-mono text-lg">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-gray-50/50 p-4 rounded-2xl border border-transparent">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-black font-bold">{t.text}</span>;
                    const isSelected = selectedIndices.has(t.id);
                    const isAlreadyInDict = dictionary.some(d => d.word === t.cleanWord);
                    return (
                      <button 
                        key={t.id} 
                        disabled={isAlreadyInDict}
                        onClick={() => handleWordClickId(t)} 
                        className={`px-1.5 py-0.5 rounded-lg transition-all font-black ${
                          isAlreadyInDict ? 'bg-emerald-100 text-emerald-700 opacity-60' : 
                          isSelected ? 'bg-blue-600 text-white shadow-md scale-105' : 
                          'hover:bg-blue-100 text-black font-bold'
                        }`}
                      >
                        {t.text}
                        {isAlreadyInDict && <Sparkles className="inline-block w-3 h-3 ml-1" />}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
            <button onClick={addToDictionary} className="w-full mt-8 py-5 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all active:scale-95">
              <PlusCircle className="w-5 h-5" /> Vložit do slovníku
            </button>
          </div>

          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-blue-100 flex flex-col">
            <h3 className="text-xl font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
              <Hash className="w-6 h-6 text-blue-600" /> Slovník kódů
            </h3>
            <div className="flex-1 space-y-3">
              {dictionary.length === 0 ? (
                <div className="py-20 text-center text-gray-300 font-bold uppercase text-xs tracking-widest border-2 border-dashed rounded-3xl flex flex-col items-center gap-4">
                  <FileText className="w-12 h-12 opacity-10" />
                  Zatím prázdné
                </div>
              ) : (
                dictionary.map((item) => (
                  <div key={item.code} className="flex items-center justify-between p-4 bg-blue-50 rounded-2xl border border-blue-100 animate-in slide-in-from-right duration-300">
                    <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-blue-600 text-white font-black rounded-xl flex items-center justify-center shadow-sm">#{item.code}</div>
                        <span className="font-black text-blue-900 uppercase text-lg">{item.word}</span>
                    </div>
                    <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}

      {phase === 'assembly' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 w-full items-start">
          <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col">
            <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                <FileText className="w-4 h-4" /> Původní text
            </h4>
            <div className="space-y-3 font-mono text-sm bg-gray-50/50 p-4 rounded-2xl">
              {level.lines.map((line, i) => <div key={i} className="py-1 border-b border-gray-100 last:border-0 text-black font-bold whitespace-pre-wrap">{line}</div>)}
            </div>
            <div className="mt-6 p-5 bg-blue-50 rounded-[2rem] border border-blue-100">
                <div className="flex justify-between items-center mb-1">
                    <span className="text-[10px] font-black uppercase text-blue-400">Původní (znaky):</span>
                    <span className="text-sm font-black text-blue-900">{stats.originalLen}</span>
                </div>
                <div className="flex justify-between items-center">
                    <span className="text-[10px] font-black uppercase text-emerald-500">Zkomprimováno (znaky):</span>
                    <span className="text-sm font-black text-emerald-700">{stats.totalCompressed}</span>
                </div>
                <div className="mt-2 pt-2 border-t border-blue-100 flex justify-between items-center">
                    <span className="text-[10px] font-black uppercase text-gray-400">Poměr:</span>
                    <span className="text-lg font-black text-blue-600">{stats.ratio}%</span>
                </div>
            </div>
          </div>

          <div className="bg-blue-900 p-8 rounded-[3rem] shadow-xl text-white flex flex-col gap-6 min-h-[500px]">
            <div>
                <h4 className="text-[10px] font-black text-blue-300 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Hash className="w-4 h-4" /> Slovník (Kódy)
                </h4>
                <div className="grid grid-cols-2 gap-3">
                    {dictionary.map(item => (
                        <div 
                            key={item.code} 
                            draggable
                            onDragStart={(e) => onDragStart(e, item.code)}
                            className="p-3 bg-blue-800 hover:bg-blue-700 cursor-grab active:cursor-grabbing rounded-2xl flex items-center gap-3 border border-blue-700 transition-all shadow-sm group"
                        >
                            <span className="w-8 h-8 bg-blue-500 text-white rounded-xl flex items-center justify-center text-xs font-black">#{item.code}</span>
                            <span className="text-[10px] font-black uppercase truncate">{item.word}</span>
                        </div>
                    ))}
                </div>
            </div>

            <div className="mt-auto">
                <h4 className="text-[10px] font-black text-blue-300 uppercase tracking-widest mb-4">Unikátní slova</h4>
                <div className="flex flex-wrap gap-2">
                    {nonEncodableWords.map(word => (
                        <div 
                            key={word} 
                            draggable
                            onDragStart={(e) => onDragStart(e, word)}
                            className="px-4 py-3 bg-gray-800 hover:bg-gray-700 cursor-grab active:cursor-grabbing rounded-xl text-[10px] font-black uppercase border border-gray-700 transition-all"
                        >
                            {word}
                        </div>
                    ))}
                </div>
            </div>
            <p className="text-[9px] text-blue-400 font-bold uppercase italic mt-4 leading-relaxed">
              Výpočet: Počet znaků zkomprimovaného textu / Původní počet znaků.<br/>
              Kód se počítá jako délka čísla (bez #). Konce řádků ani slovník se nepočítají.
            </p>
          </div>

          <div className={`bg-white p-8 rounded-[3rem] shadow-xl border-4 transition-all ${isFinalCorrect ? 'border-emerald-500 shadow-emerald-100' : 'border-emerald-100'} flex flex-col`}>
            <div className="flex justify-between items-center mb-6">
                <h4 className="text-xs font-black text-emerald-600 uppercase tracking-widest">Komprimovaný zápis</h4>
                <span className="bg-emerald-600 px-3 py-1 rounded-full text-xs font-black text-white">{stats.ratio}%</span>
            </div>
            <div className="space-y-4 font-mono text-sm mb-8">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-emerald-50/50 p-3 rounded-2xl border border-emerald-100 min-h-[56px] gap-1">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-gray-500">{t.text}</span>;
                    const val = assemblyState[t.id];
                    return (
                      <div 
                        key={t.id} 
                        onDragOver={(e) => e.preventDefault()}
                        onDrop={(e) => onDrop(e, t.id)}
                        className={`min-w-[54px] h-10 px-2 rounded-xl font-black transition-all border-2 text-xs flex items-center justify-center ${
                            val !== undefined ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm' : 
                            'bg-white border-emerald-100 text-emerald-200 border-dashed hover:border-emerald-400'
                        }`}
                      >
                        {val !== undefined ? (typeof val === 'number' ? `#${val}` : val) : ''}
                      </div>
                    );
                  })}
                </div>
              ))}
            </div>

            {isFinalCorrect ? (
                <div className="mt-auto space-y-4">
                    <div className="p-5 bg-emerald-600 rounded-[2rem] text-white text-center animate-in zoom-in">
                        <Trophy className="w-8 h-8 mx-auto mb-2" />
                        <p className="font-black uppercase tracking-widest text-sm">Skvělá práce!</p>
                        <p className="text-[10px] opacity-80 leading-relaxed">Podařilo se vám ušetřit {100 - stats.ratio}% místa v textu.</p>
                    </div>
                    <button onClick={() => setLevelIdx((levelIdx + 1) % LEVELS.length)} className="w-full py-4 bg-gray-900 text-white font-black rounded-[2rem] uppercase tracking-widest text-xs hover:bg-black transition-all shadow-lg shadow-gray-200">Další úkol</button>
                </div>
            ) : (
                <button onClick={checkFinal} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all active:scale-95">
                  <CheckCircle2 className="w-5 h-5" /> Ověřit výsledek
                </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default TextCompression;

import React, { useState, useMemo, useEffect } from 'react';
import { ArrowLeft, CheckCircle2, ArrowRight, Hash, FileText, Zap, Trophy, PlusCircle, AlertCircle, Sparkles, GripVertical } from 'lucide-react';

interface TextLevel {
  id: number;
  title: string;
  lines: string[];
}

const LEVELS: TextLevel[] = [
  {
    id: 1,
    title: "Prší, prší",
    lines: [
      "PRŠÍ, PRŠÍ, JEN SE LEJE.",
      "KAM KONÍČKY POJEDEME?",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ.",
      "POJEDEME NA LUKA,",
      "AŽ KUKAČKA ZAKUKÁ."
    ]
  },
  {
    id: 2,
    title: "Pec nám spadla",
    lines: [
      "PEC NÁM SPADLA, PEC NÁM SPADLA,",
      "KDOŽE NÁM JI OPRAVÍ?",
      "STAREJ PECNÁŘ NENÍ DOMA,",
      "NEMÁ DOMA KLADIVO.",
      "STAREJ PECNÁŘ NENÍ DOMA,",
      "NEMÁ DOMA KLADIVO."
    ]
  }
];

type Phase = 'identification' | 'assembly';

interface Token {
  id: string;
  text: string;
  cleanWord: string;
  isWord: boolean;
}

const TextCompression: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [levelIdx, setLevelIdx] = useState(0);
  const [phase, setPhase] = useState<Phase>('identification');
  const [dictionary, setDictionary] = useState<{ word: string; code: number }[]>([]);
  const [selectedIndices, setSelectedIndices] = useState<Set<string>>(new Set());
  const [assemblyState, setAssemblyState] = useState<{ [tokenId: string]: string | number }>({});
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);
  const [isFinalCorrect, setIsFinalCorrect] = useState(false);

  const level = LEVELS[levelIdx];

  const tokensMatrix: Token[][] = useMemo(() => {
    return level.lines.map((line, lIdx) => {
      const parts = line.split(/(\s+)/);
      return parts.map((part, pIdx) => {
        const isWord = /[A-ZČŠŽŘĎŤŇŮÚ]+/.test(part.toUpperCase());
        const cleanWord = part.trim().replace(/[,.?]/g, '').toUpperCase();
        return { id: `${lIdx}-${pIdx}`, text: part, cleanWord, isWord };
      });
    });
  }, [level]);

  const allTokens = useMemo(() => tokensMatrix.flat(), [tokensMatrix]);
  const allWords = useMemo(() => allTokens.filter(t => t.isWord), [allTokens]);

  const targetDictionaryWords = useMemo(() => {
    const counts: { [word: string]: number } = {};
    allWords.forEach(w => { counts[w.cleanWord] = (counts[w.cleanWord] || 0) + 1; });
    const duplicates = Object.keys(counts).filter(w => counts[w] > 1);

    const wordsInOrder: string[] = [];
    allWords.forEach(w => {
      if (duplicates.includes(w.cleanWord) && !wordsInOrder.includes(w.cleanWord)) {
        wordsInOrder.push(w.cleanWord);
      }
    });
    return wordsInOrder;
  }, [allWords]);

  const nonEncodableWords = useMemo(() => {
    const dups = new Set(targetDictionaryWords);
    return Array.from(new Set(allWords.filter(w => !dups.has(w.cleanWord)).map(w => w.text)));
  }, [allWords, targetDictionaryWords]);

  useEffect(() => {
    setPhase('identification');
    setDictionary([]);
    setSelectedIndices(new Set());
    setAssemblyState({});
    setFeedback(null);
    setIsFinalCorrect(false);
  }, [levelIdx]);

  const stats = useMemo(() => {
    const originalLen = level.lines.reduce((acc, line) => acc + line.length, 0);

    if (originalLen === 0) return { originalLen: 0, totalCompressed: 0, ratio: 100 };

    let totalCompressed = 0;
    allTokens.forEach(t => {
      if (!t.isWord) {
        totalCompressed += t.text.length;
      } else {
        const val = assemblyState[t.id];
        if (typeof val === 'number') {
          totalCompressed += val.toString().length;
        } else if (typeof val === 'string') {
          totalCompressed += val.length;
        } else {
          totalCompressed += t.text.length;
        }
      }
    });

    const ratio = Math.round((totalCompressed / originalLen) * 100);

    return { originalLen, totalCompressed, ratio };
  }, [level, allTokens, assemblyState]);

  const handleWordClickId = (token: Token) => {
    if (phase !== 'identification' || !token.isWord || dictionary.some(d => d.word === token.cleanWord)) return;
    const newSelected = new Set(selectedIndices);
    if (newSelected.has(token.id)) newSelected.delete(token.id);
    else newSelected.add(token.id);
    setSelectedIndices(newSelected);
  };

  const addToDictionary = () => {
    if (selectedIndices.size === 0) return;
    const selectedTokens = allTokens.filter(t => selectedIndices.has(t.id));
    const word = selectedTokens[0].cleanWord;

    if (!selectedTokens.every(t => t.cleanWord === word)) {
      setFeedback({ type: 'error', message: 'Vyber výskyty pouze jednoho stejného slova!' });
      return;
    }

    const totalOccurrences = allWords.filter(t => t.cleanWord === word).length;
    if (selectedIndices.size !== totalOccurrences) {
      setFeedback({ type: 'error', message: `Slovo ${word} se v textu vyskytuje ${totalOccurrences}x, označ všechny!` });
      return;
    }

    if (totalOccurrences < 2) {
      setFeedback({ type: 'error', message: 'Slovo se neopakuje, nepatří do slovníku.' });
      return;
    }

    const nextTargetWord = targetDictionaryWords[dictionary.length];
    if (word !== nextTargetWord) {
      setFeedback({ type: 'error', message: `Postupuj podle pořadí! První neuložená duplicita je: ${nextTargetWord}` });
      return;
    }

    setDictionary(prev => [...prev, { word, code: prev.length + 1 }]);
    setSelectedIndices(new Set());
    setFeedback({ type: 'success', message: `Slovo ${word} uloženo pod kódem #${dictionary.length + 1}.` });

    if (dictionary.length + 1 === targetDictionaryWords.length) {
      setTimeout(() => {
        setPhase('assembly');
        setFeedback({ type: 'success', message: 'Slovník hotov! Teď přetáhni prvky do komprimovaného zápisu.' });
      }, 800);
    }
  };

  const onDragStart = (e: React.DragEvent, value: string | number) => {
    e.dataTransfer.setData("text/plain", value.toString());
  };

  const onDrop = (e: React.DragEvent, tokenId: string) => {
    e.preventDefault();
    const data = e.dataTransfer.getData("text/plain");
    const value = !isNaN(Number(data)) && data.trim() !== "" ? Number(data) : data;
    setAssemblyState(prev => ({ ...prev, [tokenId]: value }));
  };

  const checkFinal = () => {
    let errors = 0;
    let missing = 0;
    allTokens.forEach(t => {
      if (!t.isWord) return;
      const userVal = assemblyState[t.id];
      if (userVal === undefined) {
          missing++;
          return;
      }
      const dictItem = dictionary.find(d => d.word === t.cleanWord);
      if (dictItem) {
        if (userVal !== dictItem.code) errors++;
      } else {
        if (userVal !== t.text) errors++;
      }
    });

    if (missing > 0) {
        setFeedback({ type: 'error', message: `Doplň všechna pole v textu!` });
        return;
    }

    if (errors === 0) {
      setFeedback({ type: 'success', message: `Vynikající! Nová velikost textu je ${stats.ratio}% původní.` });
      setIsFinalCorrect(true);
    } else {
      setFeedback({ type: 'error', message: `Někde máš chybu (${errors}x). Zkontroluj hlavně kódy.` });
      setIsFinalCorrect(false);
    }
  };

  return (
    <div className="w-full max-w-7xl flex flex-col gap-6 items-center animate-in fade-in duration-500 pb-20 px-4">
      {/* Header */}
      <div className="w-full bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col md:flex-row items-center justify-between gap-6">
        <button onClick={onBack} className="flex items-center text-gray-400 hover:text-blue-600 transition-colors font-black uppercase text-xs tracking-widest shrink-0">
          <ArrowLeft className="w-5 h-5 mr-2" /> Zpět
        </button>

        <div className="flex gap-2">
          {LEVELS.map((l, idx) => (
            <button key={l.id} onClick={() => setLevelIdx(idx)} className={`px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${levelIdx === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-blue-50 text-blue-600'}`}>{l.title}</button>
          ))}
        </div>

        <div className="flex items-center gap-4 bg-blue-50 px-5 py-3 rounded-2xl border border-blue-100">
          <Zap className="w-5 h-5 text-blue-600" />
          <div className="text-left">
            <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest leading-none">Fáze úkolu</p>
            <p className="text-xs font-black text-blue-900 uppercase tracking-tight">
              {phase === 'identification' ? '1. Tvorba slovníku' : '2. Sestavení básně'}
            </p>
          </div>
        </div>
      </div>

      {feedback && (
        <div className={`w-full p-4 rounded-2xl border-2 flex items-center gap-3 animate-in slide-in-from-top duration-300 ${feedback.type === 'success' ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800'}`}>
          {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          <span className="font-bold text-sm uppercase tracking-tight">{feedback.message}</span>
        </div>
      )}

      {phase === 'identification' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 w-full">
          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100">
            <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight flex items-center gap-3 mb-6">
                <div className="w-3 h-8 bg-blue-500 rounded-full"></div>
                Označ všechny výskyty slova
            </h3>
            <div className="space-y-4 font-mono text-lg">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-gray-50/50 p-4 rounded-2xl border border-transparent">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-black font-bold">{t.text}</span>;
                    const isSelected = selectedIndices.has(t.id);
                    const isAlreadyInDict = dictionary.some(d => d.word === t.cleanWord);
                    return (
                      <button 
                        key={t.id} 
                        disabled={isAlreadyInDict}
                        onClick={() => handleWordClickId(t)} 
                        className={`px-1.5 py-0.5 rounded-lg transition-all font-black ${
                          isAlreadyInDict ? 'bg-emerald-100 text-emerald-700 opacity-60' : 
                          isSelected ? 'bg-blue-600 text-white shadow-md scale-105' : 
                          'hover:bg-blue-100 text-black font-bold'
                        }`}
                      >
                        {t.text}
                        {isAlreadyInDict && <Sparkles className="inline-block w-3 h-3 ml-1" />}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
            <button onClick={addToDictionary} className="w-full mt-8 py-5 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all active:scale-95">
              <PlusCircle className="w-5 h-5" /> Vložit do slovníku
            </button>
          </div>

          <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-blue-100 flex flex-col">
            <h3 className="text-xl font-black text-gray-800 mb-6 uppercase tracking-tight flex items-center gap-3">
              <Hash className="w-6 h-6 text-blue-600" /> Slovník kódů
            </h3>
            <div className="flex-1 space-y-3">
              {dictionary.length === 0 ? (
                <div className="py-20 text-center text-gray-300 font-bold uppercase text-xs tracking-widest border-2 border-dashed rounded-3xl flex flex-col items-center gap-4">
                  <FileText className="w-12 h-12 opacity-10" />
                  Zatím prázdné
                </div>
              ) : (
                dictionary.map((item) => (
                  <div key={item.code} className="flex items-center justify-between p-4 bg-blue-50 rounded-2xl border border-blue-100 animate-in slide-in-from-right duration-300">
                    <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-blue-600 text-white font-black rounded-xl flex items-center justify-center shadow-sm">#{item.code}</div>
                        <span className="font-black text-blue-900 uppercase text-lg">{item.word}</span>
                    </div>
                    <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}

      {phase === 'assembly' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 w-full items-start">
          <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-gray-100 flex flex-col">
            <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                <FileText className="w-4 h-4" /> Původní text
            </h4>
            <div className="space-y-3 font-mono text-sm bg-gray-50/50 p-4 rounded-2xl">
              {level.lines.map((line, i) => <div key={i} className="py-1 border-b border-gray-100 last:border-0 text-black font-bold whitespace-pre-wrap">{line}</div>)}
            </div>
            <div className="mt-6 p-5 bg-blue-50 rounded-[2rem] border border-blue-100">
                <div className="flex justify-between items-center mb-1">
                    <span className="text-[10px] font-black uppercase text-blue-400">Původní (znaky):</span>
                    <span className="text-sm font-black text-blue-900">{stats.originalLen}</span>
                </div>
                <div className="flex justify-between items-center">
                    <span className="text-[10px] font-black uppercase text-emerald-500">Zkomprimováno (znaky):</span>
                    <span className="text-sm font-black text-emerald-700">{stats.totalCompressed}</span>
                </div>
                <div className="mt-2 pt-2 border-t border-blue-100 flex justify-between items-center">
                    <span className="text-[10px] font-black uppercase text-gray-400">Poměr:</span>
                    <span className="text-lg font-black text-blue-600">{stats.ratio}%</span>
                </div>
            </div>
          </div>

          <div className="bg-blue-900 p-8 rounded-[3rem] shadow-xl text-white flex flex-col gap-6 min-h-[500px]">
            <div>
                <h4 className="text-[10px] font-black text-blue-300 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Hash className="w-4 h-4" /> Slovník (Kódy)
                </h4>
                <div className="grid grid-cols-2 gap-3">
                    {dictionary.map(item => (
                        <div 
                            key={item.code} 
                            draggable
                            onDragStart={(e) => onDragStart(e, item.code)}
                            className="p-3 bg-blue-800 hover:bg-blue-700 cursor-grab active:cursor-grabbing rounded-2xl flex items-center gap-3 border border-blue-700 transition-all shadow-sm group"
                        >
                            <span className="w-8 h-8 bg-blue-500 text-white rounded-xl flex items-center justify-center text-xs font-black">#{item.code}</span>
                            <span className="text-[10px] font-black uppercase truncate">{item.word}</span>
                        </div>
                    ))}
                </div>
            </div>

            <div className="mt-auto">
                <h4 className="text-[10px] font-black text-blue-300 uppercase tracking-widest mb-4">Unikátní slova</h4>
                <div className="flex flex-wrap gap-2">
                    {nonEncodableWords.map(word => (
                        <div 
                            key={word} 
                            draggable
                            onDragStart={(e) => onDragStart(e, word)}
                            className="px-4 py-3 bg-gray-800 hover:bg-gray-700 cursor-grab active:cursor-grabbing rounded-xl text-[10px] font-black uppercase border border-gray-700 transition-all"
                        >
                            {word}
                        </div>
                    ))}
                </div>
            </div>
            <p className="text-[9px] text-blue-400 font-bold uppercase italic mt-4 leading-relaxed">
              Výpočet: Počet znaků zkomprimovaného textu / Původní počet znaků.<br/>
              Kód se počítá jako délka čísla (bez #). Konce řádků ani slovník se nepočítají.
            </p>
          </div>

          <div className={`bg-white p-8 rounded-[3rem] shadow-xl border-4 transition-all ${isFinalCorrect ? 'border-emerald-500 shadow-emerald-100' : 'border-emerald-100'} flex flex-col`}>
            <div className="flex justify-between items-center mb-6">
                <h4 className="text-xs font-black text-emerald-600 uppercase tracking-widest">Komprimovaný zápis</h4>
                <span className="bg-emerald-600 px-3 py-1 rounded-full text-xs font-black text-white">{stats.ratio}%</span>
            </div>
            <div className="space-y-4 font-mono text-sm mb-8">
              {tokensMatrix.map((line, lIdx) => (
                <div key={lIdx} className="flex flex-wrap items-center bg-emerald-50/50 p-3 rounded-2xl border border-emerald-100 min-h-[56px] gap-1">
                  {line.map(t => {
                    if (!t.isWord) return <span key={t.id} className="whitespace-pre text-gray-500">{t.text}</span>;
                    const val = assemblyState[t.id];
                    return (
                      <div 
                        key={t.id} 
                        onDragOver={(e) => e.preventDefault()}
                        onDrop={(e) => onDrop(e, t.id)}
                        className={`min-w-[54px] h-10 px-2 rounded-xl font-black transition-all border-2 text-xs flex items-center justify-center ${
                            val !== undefined ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm' : 
                            'bg-white border-emerald-100 text-emerald-200 border-dashed hover:border-emerald-400'
                        }`}
                      >
                        {val !== undefined ? (typeof val === 'number' ? `#${val}` : val) : ''}
                      </div>
                    );
                  })}
                </div>
              ))}
            </div>

            {isFinalCorrect ? (
                <div className="mt-auto space-y-4">
                    <div className="p-5 bg-emerald-600 rounded-[2rem] text-white text-center animate-in zoom-in">
                        <Trophy className="w-8 h-8 mx-auto mb-2" />
                        <p className="font-black uppercase tracking-widest text-sm">Skvělá práce!</p>
                        <p className="text-[10px] opacity-80 leading-relaxed">Podařilo se vám ušetřit {100 - stats.ratio}% místa v textu.</p>
                    </div>
                    <button onClick={() => setLevelIdx((levelIdx + 1) % LEVELS.length)} className="w-full py-4 bg-gray-900 text-white font-black rounded-[2rem] uppercase tracking-widest text-xs hover:bg-black transition-all shadow-lg shadow-gray-200">Další úkol</button>
                </div>
            ) : (
                <button onClick={checkFinal} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white font-black rounded-[2rem] shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest text-sm transition-all active:scale-95">
                  <CheckCircle2 className="w-5 h-5" /> Ověřit výsledek
                </button>
            )}
