                </p>
            </div>
        </div>

        {/* COL 3: KOMPRIMOVANÝ ZÁPIS */}
        <div className={`bg-white p-6 rounded-[2.5rem] shadow-xl border-4 transition-all flex flex-col ${isFinalCorrect ? 'border-emerald-500' : 'border-emerald-50'}`}>
