const CHAR_MAP: { [key: string]: number } = {
  ' ': 2, // Mezera je dle výpočtu 180 u "1. KONTROLA" rovna 2
  '.': 2,
  ',': 3,
  'A': 4, 'B': 5, 'C': 6, 'D': 7, 'E': 8, 'F': 9, 'G': 10,
  'H': 11, 'CH': 12, 'I': 13, 'J': 14, 'K': 15, 'L': 16, 'M': 17, 'N': 18, 'O': 19, 'P': 20,
  'Q': 21, 'R': 22, 'S': 23, 'T': 24, 'U': 25, 'V': 26, 'W': 27, 'X': 28, 'Y': 29, 'Z': 30,
  '9': 31, '8': 32, '7': 33, '6': 34, '5': 35, '4': 36, '3': 37, '2': 38, '1': 39, '0': 40
};

const MESSAGES = [
  "1. KONTROLA",
  "AHOJ",
  "DATA",
  "INFORMATIKA",
  "KOD 123",
  "ZDAR"
];

const ChecksumGame: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [levelIdx, setLevelIdx] = useState(0);
  const [userValue, setUserValue] = useState('');
  const [feedback, setFeedback] = useState<'none' | 'correct' | 'wrong'>('none');
  const [showWin, setShowWin] = useState(false);

  const currentMessage = MESSAGES[levelIdx];

  const correctChecksum = useMemo(() => {
    let sum = 0;
    // Speciální ošetření pro "CH" v češtině
    let i = 0;
    const msg = currentMessage.toUpperCase();
    while (i < msg.length) {
      if (msg[i] === 'C' && msg[i+1] === 'H') {
        sum += CHAR_MAP['CH'];
        i += 2;
      } else {
        sum += CHAR_MAP[msg[i]] || 0;
        i++;
      }
    }
    return sum;
  }, [currentMessage]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const val = parseInt(userValue);
    if (val === correctChecksum) {
      setFeedback('correct');
      setTimeout(() => {
        if (levelIdx < MESSAGES.length - 1) {
          setLevelIdx(prev => prev + 1);
          setUserValue('');
          setFeedback('none');
        } else {
          setShowWin(true);
        }
      }, 1500);
    } else {
      setFeedback('wrong');
      setTimeout(() => setFeedback('none'), 1500);
    }
